import http from 'k6/http';
import { fail, sleep } from 'k6';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = 'bench';
const VU = __VU;
const USER = (VU >= 1 && VU <= 16) ? `bench-${VU}` : 'bench';
const REDIRECT_DISABLED = { redirects: 0 };

let currentCsrf = '';
let currentCartId = null;
let currentEtag = null;
let idempotencyKey = '';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
};

function resolveUrl(raw) {
  if (!raw) return null;
  if (/^https?:\/\//i.test(raw)) return raw;
  if (raw.startsWith('/')) return BASE_URL + raw;
  return BASE_URL + '/' + raw;
}

function parseJson(body) {
  try {
    return JSON.parse(body);
  } catch (e) {
    return null;
  }
}

function getHeader(res, name) {
  if (!res || !res.headers) return null;
  const lower = name.toLowerCase();
  const keys = Object.keys(res.headers);
  for (const k of keys) {
    if (k.toLowerCase() === lower) return res.headers[k];
  }
  return null;
}

function must(condition, message) {
  if (!condition) {
    fail(message);
  }
}

function extractHiddenCsrf(html) {
  const inputRegex = /<input\b[^>]*>/gi;
  let m;
  while ((m = inputRegex.exec(html)) !== null) {
    const tag = m[0];
    const typeMatch = tag.match(/\btype\s*=\s*(?:"hidden"|'hidden'|hidden)/i);
    if (!typeMatch) continue;
    const nameMatch = tag.match(/\bname\s*=\s*(?:"csrf"|'csrf'|csrf)/i);
    if (!nameMatch) continue;
    const valueMatch = tag.match(/\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (valueMatch) {
      return valueMatch[1] || valueMatch[2] || valueMatch[3] || '';
    }
  }
  return null;
}

function extractFormAction(html) {
  const formRegex = /<form\b[^>]*>/gi;
  let m;
  while ((m = formRegex.exec(html)) !== null) {
    const tag = m[0];
    const actionMatch = tag.match(/\baction\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (actionMatch) {
      return actionMatch[1] || actionMatch[2] || actionMatch[3] || '';
    }
  }
  return null;
}

function extractInputValue(html, name) {
  const inputRegex = /<input\b[^>]*>/gi;
  let m;
  while ((m = inputRegex.exec(html)) !== null) {
    const tag = m[0];
    const nameMatch = tag.match(/\bname\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!nameMatch) continue;
    const nm = nameMatch[1] || nameMatch[2] || nameMatch[3];
    if (nm !== name) continue;
    const valueMatch = tag.match(/\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (valueMatch) return valueMatch[1] || valueMatch[2] || valueMatch[3] || '';
  }
  return null;
}

function doLogin() {
  let res = http.get(`${BASE_URL}/v2/login-form`, REDIRECT_DISABLED);
  must(res.status === 200, `login form status ${res.status}`);
  const csrf = extractHiddenCsrf(res.body);
  must(csrf, 'login form csrf missing');
  currentCsrf = csrf;

  let loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: USER,
    password: PASSWORD,
    csrf: currentCsrf,
  }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': currentCsrf },
    redirects: 0,
  });

  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location') || loginRes.headers.Location;
    must(loc, 'login 302 missing Location');
    loginRes = http.get(resolveUrl(loc), {
      headers: { 'X-CSRF-Token': currentCsrf },
      redirects: 0,
    });
  }

  must(loginRes.status === 200 || loginRes.status === 201 || loginRes.status === 204,
    `login status ${loginRes.status} body ${loginRes.body}`);
  const json = parseJson(loginRes.body);
  if (json && json.csrf) currentCsrf = json.csrf;
  if (json && json.user) must(json.user === USER, `login user ${json.user} != ${USER}`);
  if (!currentCsrf) fail('no csrf after login');
}

function solveChallenge() {
  let res = http.get(`${BASE_URL}/v2/challenge-form`, {
    headers: { 'X-CSRF-Token': currentCsrf },
    redirects: 0,
  });
  must(res.status === 200, `challenge form status ${res.status}`);
  const action = extractFormAction(res.body);
  must(action, 'challenge form action missing');
  const challenge = extractInputValue(res.body, 'challenge');
  must(challenge !== null, 'challenge input missing');

  const actionUrl = resolveUrl(action);
  let postRes = http.post(actionUrl, JSON.stringify({ challenge: challenge }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': currentCsrf },
    redirects: 0,
  });

  if (postRes.status === 302) {
    const loc = getHeader(postRes, 'Location') || postRes.headers.Location;
    must(loc, 'challenge 302 missing Location');
    postRes = http.get(resolveUrl(loc), {
      headers: { 'X-CSRF-Token': currentCsrf },
      redirects: 0,
    });
  }

  must(postRes.status === 200 || postRes.status === 201,
    `challenge final status ${postRes.status} body ${postRes.body}`);
  const json = parseJson(postRes.body);
  must(json && json.grant_id, `challenge grant_id missing body ${postRes.body}`);
  if (json.csrf) currentCsrf = json.csrf;
  return json.grant_id;
}

function findProduct() {
  let products = [];
  let res = http.get(`${BASE_URL}/v2/catalog`, {
    headers: { 'X-CSRF-Token': currentCsrf },
    redirects: 0,
  });
  must(res.status === 200, `catalog status ${res.status}`);
  let json = parseJson(res.body);
  const rawProducts = json && json.data && json.data.products;
  const initialProducts = rawProducts
    ? (Array.isArray(rawProducts) ? rawProducts : [rawProducts])
    : [];
  products = products.concat(initialProducts);

  const findInStock = (list) => {
    for (const product of list) {
      if (!product || !product.id || !product.variants) continue;
      const variants = Array.isArray(product.variants) ? product.variants : [product.variants];
      for (const variant of variants) {
        if (variant && variant.id && variant.in_stock) {
          return { product_id: product.id, variant_id: variant.id };
        }
      }
    }
    return null;
  };

  let found = findInStock(products);
  if (found) return found;

  let pageUrl = '/v2/catalog/page';
  for (let i = 0; i < 3; i++) {
    res = http.get(resolveUrl(pageUrl), {
      headers: { 'X-CSRF-Token': currentCsrf },
      redirects: 0,
    });
    must(res.status === 200, `catalog page status ${res.status}`);
    json = parseJson(res.body);
    const data = json && json.data;
    const pageProduct = data && (data.product || (Array.isArray(data.products) ? data.products[0] : data.products));
    if (pageProduct) products.push(pageProduct);
    const next = (data && data.next) || (json && json.next) || null;

    found = findInStock(products);
    if (found) return found;
    if (!next) break;
    pageUrl = next;
  }

  fail('no in-stock variant found');
}

function recoverSession(cartId) {
  let res = http.get(`${BASE_URL}/v2/login-form`, REDIRECT_DISABLED);
  must(res.status === 200, `fresh login form status ${res.status}`);
  const csrf = extractHiddenCsrf(res.body);
  must(csrf, 'fresh login csrf missing');
  currentCsrf = csrf;

  let loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: USER,
    password: PASSWORD,
    csrf: currentCsrf,
  }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': currentCsrf },
    redirects: 0,
  });

  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location') || loginRes.headers.Location;
    must(loc, 'fresh login 302 missing Location');
