    });
    must(recRes.status === 200 || recRes.status === 201 || recRes.status === 204,
      `fresh recover status ${recRes.status} body ${recRes.body}`);
    const recJson = parseJson(recRes.body);
    if (recJson && recJson.csrf) currentCsrf = recJson.csrf;
  }
  return true;
}

function renewSession(cartId) {
  const res = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': currentCsrf },
    redirects: 0,
  });

  if (res.status === 401 && parseError(res) === 'session') {
    return recoverSession(cartId);
  }

  must(res.status === 200 || res.status === 201 || res.status === 204,
    `renew status ${res.status} body ${res.body}`);
  const json = parseJson(res.body);
  if (json && json.csrf) currentCsrf = json.csrf;

  if (cartId) {
    let recRes = http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': currentCsrf },
      redirects: 0,
    });
    must(recRes.status === 200 || recRes.status === 201 || recRes.status === 204,
      `cart recover status ${recRes.status} body ${recRes.body}`);
    const recJson = parseJson(recRes.body);
    if (recJson && recJson.csrf) currentCsrf = recJson.csrf;
  }
  return true;
}

function parseError(res) {
  if (!res || res.status !== 401) return null;
  const json = parseJson(res.body);
  if (json && json.error) return json.error;
  return 'unknown';
}

function recoverFrom401(res, cartId) {
  const err = parseError(res);
  must(err, `401 body invalid ${res.body}`);
  if (err === 'denied') {
    fail(`401 denied: ${res.body}`);
  }
  if (err === 'expired') {
    return renewSession(cartId);
  }
  if (err === 'session') {
    return recoverSession(cartId);
  }
  fail(`unknown 401 error ${err}`);
}

function performWithRecovery(opFn, cartId) {
  let res = opFn();
  if (res.status === 401) {
    recoverFrom401(res, cartId);
    res = opFn();
  }
  return res;
}

function createCart(grantId, product) {
  const opFn = () => http.post(`${BASE_URL}/v2/carts`, JSON.stringify({
    product_id: product.product_id,
    variant_id: product.variant_id,
    grant_id: grantId,
  }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': currentCsrf },
    redirects: 0,
  });

  let res = performWithRecovery(opFn, null);
  must(res.status === 201, `cart create status ${res.status} body ${res.body}`);
  const json = parseJson(res.body);
  must(json && json.id, 'cart id missing');
  currentCartId = json.id;
  if (json.csrf) currentCsrf = json.csrf;
  currentEtag = getHeader(res, 'ETag') || getHeader(res, 'etag');
  idempotencyKey = `idem-${currentCartId}`;
}

function readCart() {
  const opFn = () => http.get(`${BASE_URL}/v2/carts/${currentCartId}`, {
    headers: { 'X-CSRF-Token': currentCsrf },
    redirects: 0,
  });
  let res = performWithRecovery(opFn, currentCartId);
  must(res.status === 200, `cart read status ${res.status} body ${res.body}`);
  const etag = getHeader(res, 'ETag') || getHeader(res, 'etag');
  if (etag) currentEtag = etag;
  return currentEtag;
}

function patchCartQuantity() {
  const quantity = 1;
  const doPatch = () => http.patch(`${BASE_URL}/v2/carts/${currentCartId}`, JSON.stringify({ quantity: quantity }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': currentCsrf,
      'If-Match': currentEtag,
    },
    redirects: 0,
  });

  let res = performWithRecovery(doPatch, currentCartId);
  if (res.status === 412) {
    readCart();
    res = performWithRecovery(doPatch, currentCartId);
  }
  must(res.status === 200 || res.status === 201,
    `patch quantity status ${res.status} body ${res.body}`);
  const json = parseJson(res.body);
  if (json && json.csrf) currentCsrf = json.csrf;
  const etag = getHeader(res, 'ETag') || getHeader(res, 'etag');
  if (etag) currentEtag = etag;
}

function createReservation() {
  const opFn = () => http.post(`${BASE_URL}/v2/reservations`, JSON.stringify({ cart_id: currentCartId }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': currentCsrf },
    redirects: 0,
  });
  let res = performWithRecovery(opFn, currentCartId);
  must(res.status === 202, `reservation create status ${res.status} body ${res.body}`);
  const json = parseJson(res.body);
  must(json && json.status_url, 'reservation status_url missing');
  if (json.csrf) currentCsrf = json.csrf;
  return json.status_url;
}

function pollReservation(statusUrl) {
  for (let i = 0; i < 5; i++) {
    sleep(0.05);
    const opFn = () => http.get(resolveUrl(statusUrl), {
      headers: { 'X-CSRF-Token': currentCsrf },
      redirects: 0,
    });
    let res = performWithRecovery(opFn, currentCartId);
    must(res.status === 200, `reservation poll status ${res.status} body ${res.body}`);
    const json = parseJson(res.body);
    must(json, `reservation poll no json ${res.body}`);
    if (json.csrf) currentCsrf = json.csrf;
    if (json.status === 'ready') {
      must(json.reservation_id, 'ready reservation_id missing');
      return json.reservation_id;
    }
    if (json.status === 'failed') {
      fail('reservation failed');
    }
  }
  fail('reservation not ready after 5 polls');
}

function placeOrder(reservationId) {
  readCart();

  const payload = { cart_id: currentCartId };
  if (reservationId) payload.reservation_id = reservationId;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': currentCsrf,
    'Idempotency-Key': idempotencyKey,
  };
  if (currentEtag) headers['If-Match'] = currentEtag;

  const opFn = () => http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers,
    redirects: 0,
  });

  let res = performWithRecovery(opFn, currentCartId);
  must(res.status === 201, `order status ${res.status} body ${res.body}`);
  const json = parseJson(res.body);
  must(json && json.accepted === true, `order not accepted ${res.body}`);
  must(json.id, 'order id missing');
  if (json.csrf) currentCsrf = json.csrf;
}

export default function () {
  currentCsrf = '';
  currentCartId = null;
  currentEtag = null;
  idempotencyKey = '';

  doLogin();
  const product = findProduct();
  const grantId = solveChallenge();
  createCart(grantId, product);
  readCart();
  patchCartQuantity();
  const statusUrl = createReservation();
  const reservationId = pollReservation(statusUrl);
