import os
import time
import html
import threading
from html.parser import HTMLParser
from urllib.parse import urljoin

from locust import HttpUser, task, LoadTestShape, between
from locust.exception import StopUser


EXPECTED_USERS = 2


class CsrfInputParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.candidates = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "input":
            d = {k.lower(): v for k, v in attrs}
            if d.get("name") == "csrf":
                self.candidates.append(d)

    def value(self):
        if not self.candidates:
            return None
        hidden = [c for c in self.candidates if c.get("type", "").lower() == "hidden"]
        chosen = hidden[0] if hidden else self.candidates[0]
        return html.unescape(chosen.get("value") or "")


class ChallengeFormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.action = None
        self.challenge = None

    def handle_starttag(self, tag, attrs):
        d = {k.lower(): v for k, v in attrs}
        if tag.lower() == "form":
            self.action = html.unescape(d.get("action", ""))
        elif tag.lower() == "input":
            if d.get("name") == "challenge":
                self.challenge = html.unescape(d.get("value") or "")


class ShopUser(HttpUser):
    wait_time = between(0.1, 0.3)
    TARGET_ITERATIONS = 2

    started_users = 0
    completed_users = 0
    _account_counter = 0
    _account_lock = threading.Lock()

    def on_start(self):
        with ShopUser._account_lock:
            idx = ShopUser._account_counter % 16
            ShopUser._account_counter += 1
        self.account = f"bench-{idx + 1}"

        ShopUser.started_users += 1

        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.reservation_id = None
        self.grant_id = None
        self.iterations_done = 0

    def on_stop(self):
        ShopUser.completed_users += 1

    @task
    def shop_flow(self):
        if self.iterations_done >= self.TARGET_ITERATIONS:
            raise StopUser()
        self.iterations_done += 1
        self._journey()

    def _base_url(self):
        return self.host or os.environ.get("BASE_URL", "http://127.0.0.1:8000")

    def _join_url(self, url):
        if url.startswith("http"):
            return url
        return urljoin(self._base_url() + "/", url)

    def _update_csrf(self, resp):
        try:
            data = resp.json()
            csrf = data.get("csrf")
            if csrf:
                self.csrf = csrf
        except Exception:
            pass

    def _csrf_headers(self, extra=None):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        if extra:
            headers.update(extra)
        return headers

    def _parse_error(self, resp):
        try:
            data = resp.json()
            return data.get("error")
        except Exception:
            return None

    def _journey(self):
        self.client.cookies.clear()
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.reservation_id = None
        self.grant_id = None

        if not self._login():
            return

        product_id, variant_id = self._select_product()
        if product_id is None:
            return

        if not self._perform_challenge():
            return

        if not self._create_cart(product_id, variant_id):
            return

        if not self._update_cart_quantity():
            return

        if not self._create_reservation():
            return

        if not self._place_order():
            return

        self._work_sample()

    def _login(self):
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                r.failure(f"login-form status {r.status_code}")
                return False
            parser = CsrfInputParser()
            parser.feed(r.text)
            parser.close()
            login_csrf = parser.value()
            if not login_csrf:
                r.failure("login-form missing csrf input")
                return False

        with self.client.post(
            "/v2/login",
            json={"username": self.account, "password": "bench", "csrf": login_csrf},
            headers={"X-CSRF-Token": login_csrf},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("login 302 missing Location")
                    return False
                loc_url = self._join_url(loc)
                with self.client.get(loc_url, catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code != 200:
                        r2.failure(f"login Location status {r2.status_code}")
                        return False
                    self._update_csrf(r2)
                    if not self.csrf:
                        r2.failure("login Location missing csrf")
                        return False
                    return True

            if r.status_code == 200:
                self._update_csrf(r)
                if not self.csrf:
                    r.failure("login response missing csrf")
                    return False
                return True

            try:
                detail = r.json().get("error") or r.text[:200]
            except Exception:
                detail = r.text[:200]
            r.failure(f"login status {r.status_code}: {detail}")
            return False

    def _fresh_login(self):
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                r.failure("fresh login-form failed")
                return False
            parser = CsrfInputParser()
            parser.feed(r.text)
            parser.close()
            login_csrf = parser.value()
            if not login_csrf:
                r.failure("fresh login missing csrf")
                return False

        with self.client.post(
            "/v2/login",
            json={"username": self.account, "password": "bench", "csrf": login_csrf},
            headers={"X-CSRF-Token": login_csrf},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("fresh login 302 missing Location")
                    return False
                with self.client.get(self._join_url(loc), catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code != 200:
                        r2.failure("fresh login Location failed")
                        return False
                    self._update_csrf(r2)
                    if not self.csrf:
                        r2.failure("fresh login Location missing csrf")
                        return False
                    return True

            if r.status_code == 200:
                self._update_csrf(r)
                if not self.csrf:
                    r.failure("fresh login missing csrf")
                    return False
                return True

            r.failure("fresh login failed")
            return False

    def _select_product(self):
        with self.client.get("/v2/catalog", catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure(f"catalog status {r.status_code}")
                return None, None

            data = r.json()
            products = data.get("data", {}).get("products", [])
            if not products:
                r.failure("catalog empty")
                return None, None

            for product in products:
                pid = product.get("id")
                for variant in product.get("variants", []):
                    if variant.get("in_stock"):
                        vid = variant.get("id")
                        if pid is not None and vid is not None:
                            return pid, vid

            r.failure("no in-stock variant found")
            return None, None

    def _perform_challenge(self):
        with self.client.get(
            "/v2/challenge-form",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                # Some fixture variants may not require a challenge grant.
                self.grant_id = None
                return True

            parser = ChallengeFormParser()
            parser.feed(r.text)
            parser.close()
            action = parser.action
            challenge = parser.challenge
            if not action or challenge is None:
                r.failure("challenge form missing action or challenge input")
                return False

        action_url = self._join_url(action)
        resp = self._auth_post(
            action_url,
            {"challenge": challenge},
            allowed_statuses=(200, 302),
            name="/v2/challenges/post",
        )
        if resp is None:
            return False

        if resp.status_code == 302:
            loc = resp.headers.get("Location")
            if not loc:
                resp.failure("challenge 302 missing Location")
                return False
            with self.client.get(self._join_url(loc), catch_response=True, allow_redirects=False) as r2:
                if r2.status_code != 200:
                    r2.failure(f"challenge Location status {r2.status_code}")
                    return False
                self._update_csrf(r2)
                data = r2.json()
                self.grant_id = data.get("grant_id")
                if not self.grant_id:
                    r2.failure("challenge Location missing grant_id")
                    return False
                return True

        data = resp.json()
        self.grant_id = data.get("grant_id")
        if not self.grant_id:
            resp.failure("challenge response missing grant_id")
