    def _auth_post(self, url, json_payload, allowed_statuses, extra_headers=None, name=None, retry_on_412=False):
        headers = self._csrf_headers(extra_headers)

        for attempt in range(1, 3):
            with self.client.post(
                url,
                json=json_payload,
                headers=headers,
                catch_response=True,
                allow_redirects=False,
                name=name,
            ) as resp:
                if resp.status_code in allowed_statuses:
                    self._update_csrf(resp)
                    resp.success()
                    return resp

                if resp.status_code == 401 and attempt == 1:
                    err = self._parse_error(resp)
                    if err == "expired":
                        if self._renew_session():
                            headers = self._csrf_headers(extra_headers)
                            if self.cart_id:
                                self._recover_cart()
                            continue
                        resp.failure("401 expired, renew failed")
                        return None
                    if err == "session":
                        if self._fresh_login():
                            headers = self._csrf_headers(extra_headers)
                            if self.cart_id:
                                self._recover_cart()
                            continue
                        resp.failure("401 session, fresh login failed")
