                    if err == "denied":
                        resp.failure("401 denied")
                        return None
                    resp.failure(f"401 {err}")
                    return None

                if resp.status_code == 412 and attempt == 1 and retry_on_412:
                    if self._read_cart():
                        new_extra = dict(extra_headers or {})
                        new_extra["If-Match"] = self.cart_etag
                        headers = self._csrf_headers(new_extra)
