                    resp.failure("412 and failed to re-read cart")
                    return None

                try:
                    data = resp.json()
                    detail = data.get("error") or data.get("detail") or data.get("message") or resp.text[:200]
                except Exception:
                    detail = resp.text[:200]
                resp.failure(f"{url} status {resp.status_code}: {detail}")
                return None

        return None

    def _renew_session(self):
        if not self.csrf:
            return False
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=self._csrf_headers(),
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code in (200, 201, 202, 204):
                self._update_csrf(r)
                r.success()
                return True
            r.failure(f"renew failed: {r.status_code}")
            return False

    def _recover_cart(self):
