    def _create_reservation(self):
        resp = self._auth_post(
            "/v2/reservations",
            {"cart_id": self.cart_id},
            allowed_statuses=(202,),
            name="/v2/reservations",
        )
        if resp is None:
            return False

        data = resp.json()
        status_url = data.get("status_url")
        if not status_url:
            resp.failure("reservation response missing status_url")
            return False

        reservation_id = self._poll_reservation(status_url)
        if reservation_id is None:
            return False

        self.reservation_id = reservation_id
        return True

    def _poll_reservation(self, status_url):
        url = self._join_url(status_url)
        for i in range(5):
