            "/v2/orders",
            payload,
            allowed_statuses=(201,),
            extra_headers=headers,
            name="/v2/orders",
        )
        if resp is None:
            return False

        data = resp.json()
        if data.get("accepted") is not True or not data.get("id"):
            resp.failure("order not accepted")
