        return True

    def _work_sample(self):
        headers = self._csrf_headers()
        for _ in range(5):
            with self.client.post(
                "/v2/work",
                json={},
                headers=headers,
                catch_response=True,
                allow_redirects=False,
                name="/v2/work",
            ) as r:
                if r.status_code == 200:
                    try:
                        data = r.json()
                    except Exception:
                        r.failure("work bad json")
                        return
                    if data.get("ok") is True:
                        self._update_csrf(r)
                        r.success()
                        return
                    r.failure("work ok false")
                    return

                if r.status_code == 429:
                    retry_after = r.headers.get("Retry-After")
                    if retry_after:
                        try:
                            time.sleep(float(retry_after))
                        except ValueError:
                            time.sleep(1)
                    else:
                        time.sleep(1)
                    # Scheduled 429 is expected, not a failure.
                    r.success()
                    continue

                r.failure(f"unexpected work status {r.status_code}")
                return


class ShopShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.initial_spawned = False

    def tick(self):
        if not self.initial_spawned:
            self.initial_spawned = True
            return (EXPECTED_USERS, EXPECTED_USERS)

        if ShopUser.started_users < EXPECTED_USERS:
            return (EXPECTED_USERS, EXPECTED_USERS)

        active = ShopUser.started_users - ShopUser.completed_users
        if active <= 0:
            return None
        return (active, 2)
