import http from 'k6/http';
import { fail, sleep } from 'k6';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

export const options = {
  scenarios: {
    journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '3m',
    },
  },
  maxRedirects: 0,
};

function escapeRegExp(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function attrValue(tag, name) {
  const re = new RegExp(`(?:\\s|^)${escapeRegExp(name)}\\s*=\\s*(?:"([^"]*)"|'([^']*)'|([^\\s>]+))`, 'i');
  const m = tag.match(re);
  if (!m) return null;
  if (m[1] !== undefined) return m[1];
  if (m[2] !== undefined) return m[2];
  if (m[3] !== undefined) return m[3];
  return null;
}

function extractInputValue(html, name) {
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const nameVal = attrValue(tag, 'name');
    if (nameVal === name) {
      const val = attrValue(tag, 'value');
      if (val !== null && val !== '') return val;
    }
  }
  return null;
}

function extractChallengeFormAction(html) {
  const re = /<form\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const action = attrValue(tag, 'action');
    if (action && action.indexOf('/v2/challenges/') !== -1) return action;
  }
  return null;
}

function jsonOrNull(body) {
  try {
    return JSON.parse(body);
  } catch (e) {
    return null;
  }
}

function resolveUrl(url) {
  if (/^https?:\/\//i.test(url)) return url;
  return BASE_URL + (url.startsWith('/') ? url : '/' + url);
}

function getHeader(res, name) {
  const lower = name.toLowerCase();
  for (const key of Object.keys(res.headers)) {
    if (key.toLowerCase() === lower) return res.headers[key];
  }
  return null;
}

function login(jar, username) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, { jar: jar, tags: { name: 'login-form' } });
  if (formRes.status !== 200) fail(`login-form status ${formRes.status}: ${formRes.body}`);

  const csrf = extractInputValue(formRes.body, 'csrf');
  if (!csrf) fail('login csrf not found');

  const postRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username: username, password: 'bench', csrf: csrf }),
    {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      jar: jar,
      tags: { name: 'login' },
    },
  );

  let currentCsrf = null;

  if (postRes.status === 302) {
    const location = getHeader(postRes, 'Location');
    if (!location) fail('login 302 missing Location');

    const locRes = http.get(resolveUrl(location), { jar: jar, tags: { name: 'login-location' } });
    if (locRes.status !== 200) fail(`login location GET status ${locRes.status}: ${locRes.body}`);

    const json = jsonOrNull(locRes.body);
    currentCsrf = json && json.csrf ? json.csrf : null;
  } else if (postRes.status === 200) {
    const json = jsonOrNull(postRes.body);
    currentCsrf = json && json.csrf ? json.csrf : null;
  } else {
    fail(`login POST status ${postRes.status}: ${postRes.body}`);
  }

  if (!currentCsrf) fail('login did not provide session csrf');
  return currentCsrf;
}

function findInStock(products) {
  for (const product of products) {
    const variants = product.variants || [];
    for (const variant of variants) {
      if (variant.in_stock === true) {
        return { product_id: product.id, variant_id: variant.id };
      }
    }
  }
  return null;
}

function selectInStockProduct(jar, csrf) {
  const catalogRes = http.get(`${BASE_URL}/v2/catalog`, {
    jar: jar,
    headers: { 'X-CSRF-Token': csrf },
    tags: { name: 'catalog' },
  });

  if (catalogRes.status === 200) {
    const json = jsonOrNull(catalogRes.body);
    const products = json && json.data && json.data.products ? json.data.products : null;
    if (products) {
      const selected = findInStock(products);
      if (selected) return selected;
    }
  }

  let next = '/v2/catalog/page';
  for (let i = 0; i < 3 && next; i++) {
    const pageRes = http.get(resolveUrl(next), {
      jar: jar,
      headers: { 'X-CSRF-Token': csrf },
      tags: { name: 'catalog-page' },
    });
    if (pageRes.status !== 200) break;

    const json = jsonOrNull(pageRes.body);
    const product = (json && json.data && json.data.product) || (json && json.product) || null;
    if (product) {
      const selected = findInStock([product]);
      if (selected) return selected;
    }
    next = json && json.next ? json.next : null;
  }

  fail('no in-stock product found in catalog');
}

function obtainGrant(jar, csrf) {
  const formRes = http.get(`${BASE_URL}/v2/challenge-form`, {
    jar: jar,
    headers: { 'X-CSRF-Token': csrf },
    tags: { name: 'challenge-form' },
  });
  if (formRes.status !== 200) return null;

  const action = extractChallengeFormAction(formRes.body);
  if (!action) return null;

  const challenge = extractInputValue(formRes.body, 'challenge');
  if (challenge === null || challenge === undefined) return null;

  const postRes = http.post(
    resolveUrl(action),
    JSON.stringify({ challenge: challenge }),
    {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      jar: jar,
      tags: { name: 'challenge-post' },
    },
  );

  if (postRes.status === 302) {
    const location = getHeader(postRes, 'Location');
    if (!location) return null;

    const locRes = http.get(resolveUrl(location), {
      jar: jar,
      headers: { 'X-CSRF-Token': csrf },
      tags: { name: 'challenge-location' },
    });
    if (locRes.status !== 200) return null;

    const json = jsonOrNull(locRes.body);
    if (json && json.grant_id) {
      return { grant_id: json.grant_id, csrf: json.csrf || csrf };
    }
  } else if (postRes.status === 200) {
    const json = jsonOrNull(postRes.body);
    if (json && json.grant_id) {
      return { grant_id: json.grant_id, csrf: json.csrf || csrf };
    }
  }

  return null;
}

function createCart(jar, csrf, selected, grantId) {
  const payload = {
    product_id: selected.product_id,
    variant_id: selected.variant_id,
  };
  if (grantId) payload.grant_id = grantId;

  const res = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    jar: jar,
    tags: { name: 'create-cart' },
  });

  if (res.status !== 201) fail(`create cart status ${res.status}: ${res.body}`);

  const json = jsonOrNull(res.body);
  if (!json || !json.id) fail(`create cart missing id: ${res.body}`);

  const etag = getHeader(res, 'ETag');
  if (!etag) fail(`create cart missing ETag: ${res.body}`);

  return {
    cart_id: json.id,
    csrf: json.csrf || csrf,
    etag: etag,
  };
}

function setCartQuantity(jar, csrf, cartId, etag) {
  const payload = JSON.stringify({ quantity: 1 });
  let currentEtag = etag;

  let res = http.patch(`${BASE_URL}/v2/carts/${cartId}`, payload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': currentEtag,
    },
    jar: jar,
    tags: { name: 'patch-cart' },
  });

  if (res.status === 412) {
    const getRes = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
      jar: jar,
      headers: { 'X-CSRF-Token': csrf },
      tags: { name: 'get-cart' },
    });
    if (getRes.status !== 200) fail(`cart re-read status ${getRes.status}: ${getRes.body}`);

    const freshEtag = getHeader(getRes, 'ETag');
    if (!freshEtag) fail(`cart re-read missing ETag: ${getRes.body}`);
    currentEtag = freshEtag;

    res = http.patch(`${BASE_URL}/v2/carts/${cartId}`, payload, {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
        'If-Match': currentEtag,
      },
      jar: jar,
      tags: { name: 'patch-cart-retry' },
    });
    if (res.status === 412) fail('cart patch 412 on retry');
  }

  if (res.status !== 200 && res.status !== 201 && res.status !== 204) {
    fail(`patch cart status ${res.status}: ${res.body}`);
  }

  const json = jsonOrNull(res.body);
  const nextCsrf = json && json.csrf ? json.csrf : csrf;
  const nextEtag = getHeader(res, 'ETag') || currentEtag;
  return { csrf: nextCsrf, etag: nextEtag };
}

function createReservation(jar, csrf, cartId) {
  const res = http.post(
    `${BASE_URL}/v2/reservations`,
    JSON.stringify({ cart_id: cartId }),
    {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      jar: jar,
      tags: { name: 'create-reservation' },
    },
  );

  if (res.status !== 202) fail(`reservation POST status ${res.status}: ${res.body}`);

  const json = jsonOrNull(res.body);
  if (!json || !json.status_url) fail(`reservation missing status_url: ${res.body}`);

  let currentCsrf = json.csrf || csrf;
  const statusUrl = resolveUrl(json.status_url);

  let reservationId = null;
  for (let i = 0; i < 5; i++) {
    sleep(0.05);

    const statusRes = http.get(statusUrl, {
      jar: jar,
      headers: { 'X-CSRF-Token': currentCsrf },
      tags: { name: 'reservation-status' },
    });
    if (statusRes.status !== 200) fail(`reservation poll status ${statusRes.status}: ${statusRes.body}`);

    const statusJson = jsonOrNull(statusRes.body);
    if (!statusJson) fail(`reservation poll invalid JSON: ${statusRes.body}`);
    if (statusJson.csrf) currentCsrf = statusJson.csrf;

    if (statusJson.status === 'ready') {
      reservationId = statusJson.reservation_id;
      if (!reservationId) fail(`reservation ready but missing reservation_id: ${statusRes.body}`);
      break;
    } else if (statusJson.status === 'failed') {
      fail(`reservation failed: ${statusRes.body}`);
    } else if (statusJson.status !== 'pending') {
      fail(`unexpected reservation status "${statusJson.status}": ${statusRes.body}`);
    }
  }

  if (!reservationId) fail('reservation never became ready');
  return { reservation_id: reservationId, csrf: currentCsrf };
}

function createOrder(jar, csrf, cartId, reservationId, etag) {
  const idempotencyKey = `order-${cartId}`;
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;

  const res = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag,
      'Idempotency-Key': idempotencyKey,
    },
    jar: jar,
    tags: { name: 'create-order' },
  });

  if (res.status === 201) {
    const json = jsonOrNull(res.body);
    if (json && json.accepted === true && json.id) {
      return { order_id: json.id, csrf: json.csrf || csrf };
    }
    fail(`order 201 but not accepted true: ${res.body}`);
  } else if (res.status === 200) {
    const json = jsonOrNull(res.body);
    if (json && json.accepted === true && json.id) {
      return { order_id: json.id, csrf: json.csrf || csrf };
    }
    fail(`order accepted:false business failure: ${res.body}`);
  } else {
    fail(`order POST status ${res.status}: ${res.body}`);
  }
}

export default function () {
  const vu = __VU;
  const username = vu <= 16 ? `bench-${vu}` : 'bench';
  const jar = http.cookieJar();

  let csrf = login(jar, username);

  const selected = selectInStockProduct(jar, csrf);

  const grant = obtainGrant(jar, csrf);
  if (grant) csrf = grant.csrf;

  const cart = createCart(jar, csrf, selected, grant ? grant.grant_id : null);
  csrf = cart.csrf;

  const cartState = setCartQuantity(jar, csrf, cart.cart_id, cart.etag);
  csrf = cartState.csrf;

  const reservation = createReservation(jar, csrf, cart.cart_id);
  csrf = reservation.csrf;

  const order = createOrder(jar, csrf, cart.cart_id, reservation.reservation_id, cartState.etag);
}
