import os
import time
import uuid
from html.parser import HTMLParser

from locust import HttpUser, LoadTestShape, task, constant
from locust.exception import StopUser

TARGET_USERS = 2
TARGET_ITERATIONS = 2

STARTED_USERS = 0
COMPLETED_USERS = 0
_ACCOUNT_COUNTER = 0


class _FormHTMLParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.inputs = []
        self.forms = []

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attrs_dict = {}
        for key, value in attrs:
            attrs_dict[key.lower()] = value
        if tag == "input":
            self.inputs.append(attrs_dict)
        elif tag == "form":
            self.forms.append(attrs_dict)


class FlowShape(LoadTestShape):
    def tick(self):
        if STARTED_USERS < TARGET_USERS:
            return (TARGET_USERS, TARGET_USERS)

        if COMPLETED_USERS >= TARGET_USERS:
            return None

        runner = getattr(self, "runner", None)
        user_count = runner.user_count if runner else 0
        if user_count == 0:
            return None

        return (user_count, 1)


class ShopUser(HttpUser):
    wait_time = constant(0)

    def on_start(self):
        global STARTED_USERS, _ACCOUNT_COUNTER
        self.username = f"bench-{(_ACCOUNT_COUNTER % 16) + 1}"
        _ACCOUNT_COUNTER += 1

        self.csrf = None
        self.grant_id = None
        self.cart_id = None
        self.etag = None
        self.idempotency_key = None
        self.iterations_completed = 0

        STARTED_USERS += 1

    def on_stop(self):
        global COMPLETED_USERS
        COMPLETED_USERS += 1

    @task
    def journey(self):
        self._run_business_flow()
        self._do_work()

        self.iterations_completed += 1
        if self.iterations_completed >= TARGET_ITERATIONS:
            raise StopUser()

    # ---------- helpers ----------

    def _json_or_none(self, response):
        try:
            return response.json()
        except Exception:
            return None

    def _parse_form(self, html):
        parser = _FormHTMLParser()
        try:
            parser.feed(html)
        except Exception:
            pass

        csrf = None
        challenge = None
        action = None

        for inp in parser.inputs:
            name = (inp.get("name") or "").lower()
            if name == "csrf":
                csrf = inp.get("value")
                break

        for inp in parser.inputs:
            name = (inp.get("name") or "").lower()
            if name == "challenge":
                challenge = inp.get("value")
                break

        for form in parser.forms:
            act = form.get("action")
            if act:
                action = act
                break

        return csrf, challenge, action

    def _parse_challenge_form(self, html):
        parser = _FormHTMLParser()
        try:
            parser.feed(html)
        except Exception:
            pass

        challenge = None
        action = None

        for inp in parser.inputs:
            name = (inp.get("name") or "").lower()
            if name == "challenge":
                challenge = inp.get("value")
                break

        for form in parser.forms:
            act = form.get("action") or ""
            if "/challenges/" in act:
                action = act
                break

        if not action:
            for form in parser.forms:
                act = form.get("action")
                if act:
                    action = act
                    break

        return challenge, action

    def _get_json(self, url):
        with self.client.get(url, allow_redirects=False, catch_response=True) as response:
            if response.status_code != 200:
                response.failure(f"GET {url} unexpected status {response.status_code}")
                return None
            data = self._json_or_none(response)
            if data is None:
                response.failure(f"GET {url} invalid JSON")
                return None
            return data

    def _login(self):
        with self.client.get("/v2/login-form", allow_redirects=False, catch_response=True) as response:
            if response.status_code != 200:
                response.failure(f"login-form unexpected status {response.status_code}")
                return False
            html = response.text

        csrf, _, _ = self._parse_form(html)
        if csrf is None:
            with self.client.get("/v2/login-form", allow_redirects=False, catch_response=True) as response:
                response.failure("login-form missing csrf input")
            return False

        payload = {"username": self.username, "password": "bench", "csrf": csrf}
        headers = {"X-CSRF-Token": csrf}

        with self.client.post("/v2/login", json=payload, headers=headers, allow_redirects=False, catch_response=True) as response:
            if response.status_code == 302:
                location = response.headers.get("Location")
                if not location:
                    response.failure("login POST 302 missing Location")
                    return False

                # GET the dynamic Location exactly once.
                with self.client.get(location, allow_redirects=False, catch_response=True) as redirect_response:
                    if redirect_response.status_code != 200:
                        redirect_response.failure(f"login redirect status {redirect_response.status_code}")
                        return False
                    data = self._json_or_none(redirect_response)
                    if data is None:
                        redirect_response.failure("login redirect invalid JSON")
                        return False
                    self.csrf = data.get("csrf")
                    if not self.csrf:
                        redirect_response.failure("login redirect missing csrf")
                        return False
                    return True

            elif response.status_code == 200:
                data = self._json_or_none(response)
                if data is None:
                    response.failure("login invalid JSON")
                    return False
                self.csrf = data.get("csrf")
                if not self.csrf:
                    response.failure("login missing csrf")
                    return False
                return True

            else:
                response.failure(f"login unexpected status {response.status_code}")
                return False

    def _products_from_payload(self, payload):
        if not isinstance(payload, dict):
            return []

        data = payload.get("data")
        if isinstance(data, dict):
            if "products" in data:
                products = data.get("products")
                if isinstance(products, list):
                    return products
                if isinstance(products, dict):
                    return [products]
                return []

            if "product" in data:
                return [data.get("product")]

            if "id" in data and "variants" in data:
                return [data]

        if isinstance(data, list):
            return data

        return []

    def _select_variant_from_products(self, products):
        for product in products:
            if not isinstance(product, dict):
                continue

            product_id = product.get("id")
            variants = product.get("variants")
            if isinstance(variants, dict):
                variants = [variants]
            if not isinstance(variants, list):
                continue

            for variant in variants:
                if isinstance(variant, dict) and variant.get("in_stock") is True:
                    variant_id = variant.get("id")
                    if product_id is not None and variant_id is not None:
                        return product_id, variant_id

        return None, None

    def _fetch_catalog_candidates(self):
        data = self._get_json("/v2/catalog")
        if data is not None:
            products = self._products_from_payload(data)
            product_id, variant_id = self._select_variant_from_products(products)
            if product_id is not None:
                return product_id, variant_id

        next_url = "/v2/catalog/page"
        for _ in range(3):
            data = self._get_json(next_url)
            if data is None:
                break

            products = self._products_from_payload(data)
            product_id, variant_id = self._select_variant_from_products(products)
            if product_id is not None:
                return product_id, variant_id

            next_link = data.get("next")
            if not next_link:
                break

            if next_link.startswith("http://") or next_link.startswith("https://"):
                next_url = next_link
            else:
                next_url = next_link

        return None, None

    def _mark_no_product_failure(self):
        with self.client.get("/v2/catalog", allow_redirects=False, catch_response=True) as response:
            if response.status_code == 200:
                response.failure("no in-stock product found")
            else:
                response.failure(f"catalog status {response.status_code}")

    def _claim_grant(self):
        with self.client.get("/v2/challenge-form", allow_redirects=False, catch_response=True) as response:
            if response.status_code != 200:
                return False
            html = response.text

        challenge, action = self._parse_challenge_form(html)
        if challenge is None or not action:
            return False

        payload = {"challenge": challenge}
        headers = {"X-CSRF-Token": self.csrf}

        with self.client.post(action, json=payload, headers=headers, allow_redirects=False, catch_response=True) as response:
            if response.status_code == 302:
                location = response.headers.get("Location")
                if not location:
                    return False

                with self.client.get(location, allow_redirects=False, catch_response=True) as redirect_response:
                    if redirect_response.status_code != 200:
                        return False
                    data = self._json_or_none(redirect_response)
                    if data is None:
                        return False
                    grant_id = data.get("grant_id")
                    fresh_csrf = data.get("csrf")
                    if grant_id:
                        self.grant_id = grant_id
                    if fresh_csrf:
                        self.csrf = fresh_csrf
                    return grant_id is not None

            elif response.status_code == 200:
                data = self._json_or_none(response)
                if data is None:
                    return False
                grant_id = data.get("grant_id")
                fresh_csrf = data.get("csrf")
                if grant_id:
                    self.grant_id = grant_id
                if fresh_csrf:
                    self.csrf = fresh_csrf
                return grant_id is not None

            else:
                return False

    def _create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id

        headers = {"X-CSRF-Token": self.csrf}

        with self.client.post("/v2/carts", json=payload, headers=headers, allow_redirects=False, catch_response=True) as response:
            if response.status_code == 201:
                data = self._json_or_none(response)
                if data is None:
                    response.failure("cart create invalid JSON")
                    return None

                cart_id = data.get("id")
                if cart_id is None:
                    response.failure("cart create missing id")
                    return None

                self.etag = response.headers.get("ETag")
                fresh_csrf = data.get("csrf")
                if fresh_csrf:
                    self.csrf = fresh_csrf

                return cart_id

            response.failure(f"cart create status {response.status_code}")
            return None

    def _get_cart_etag(self):
        if self.cart_id is None:
            return False

        with self.client.get(f"/v2/carts/{self.cart_id}", allow_redirects=False, catch_response=True) as response:
            if response.status_code == 200:
                etag = response.headers.get("ETag")
                if etag:
                    self.etag = etag
                return True

            response.failure(f"cart GET status {response.status_code}")
            return False

    def _patch_quantity(self):
        if not self.etag and not self._get_cart_etag():
            return False

        url = f"/v2/carts/{self.cart_id}"
        payload = {"quantity": 1}
        headers = {"X-CSRF-Token": self.csrf, "If-Match": self.etag}

        with self.client.patch(url, json=payload, headers=headers, allow_redirects=False, catch_response=True) as response:
            if response.status_code in (200, 201):
                self.etag = response.headers.get("ETag") or self.etag
                data = self._json_or_none(response)
                if data:
                    fresh_csrf = data.get("csrf")
                    if fresh_csrf:
                        self.csrf = fresh_csrf
                return True

            if response.status_code == 412:
                if self._get_cart_etag():
                    headers["If-Match"] = self.etag
                    with self.client.patch(url, json=payload, headers=headers, allow_redirects=False, catch_response=True) as retry_response:
                        if retry_response.status_code in (200, 201):
                            self.etag = retry_response.headers.get("ETag") or self.etag
                            data = self._json_or_none(retry_response)
                            if data:
                                fresh_csrf = data.get("csrf")
                                if fresh_csrf:
                                    self.csrf = fresh_csrf
                            return True

                        retry_response.failure(f"patch retry status {retry_response.status_code}")
                        return False

                response.failure("patch 412 and re-read failed")
                return False

            response.failure(f"patch status {response.status_code}")
            return False

    def _create_reservation(self):
        payload = {"cart_id": self.cart_id}
        headers = {"X-CSRF-Token": self.csrf}

        with self.client.post("/v2/reservations", json=payload, headers=headers, allow_redirects=False, catch_response=True) as response:
            if response.status_code == 202:
                data = self._json_or_none(response)
                if data is None:
                    response.failure("reservation invalid JSON")
                    return None

                fresh_csrf = data.get("csrf")
                if fresh_csrf:
                    self.csrf = fresh_csrf

                status_url = data.get("status_url")
                if not status_url:
                    response.failure("reservation missing status_url")
                    return None

                return status_url

            if response.status_code in (400, 404, 405, 409):
                return None

            response.failure(f"reservation status {response.status_code}")
            return None

    def _poll_reservation(self, status_url):
        for attempt in range(5):
            if attempt > 0:
                time.sleep(0.05)

            with self.client.get(status_url, allow_redirects=False, catch_response=True) as response:
                if response.status_code != 200:
                    response.failure(f"reservation poll status {response.status_code}")
                    return None

                data = self._json_or_none(response)
                if data is None:
                    response.failure("reservation poll invalid JSON")
                    return None

                fresh_csrf = data.get("csrf")
                if fresh_csrf:
                    self.csrf = fresh_csrf

                status = data.get("status")
                if status == "ready":
                    reservation_id = data.get("reservation_id")
                    if reservation_id is None:
                        response.failure("reservation ready missing reservation_id")
                        return None
                    return reservation_id

                if status in ("pending", "failed"):
                    if status == "failed":
                        return None
                    continue

                response.failure(f"reservation poll unknown status {status}")
                return None

        return None

    def _place_order(self, reservation_id):
        if self.idempotency_key is None:
            self.idempotency_key = str(uuid.uuid4())

        payload = {"cart_id": self.cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id

        headers = {
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": self.idempotency_key,
        }
        if self.etag:
            headers["If-Match"] = self.etag

        with self.client.post("/v2/orders", json=payload, headers=headers, allow_redirects=False, catch_response=True) as response:
            data = self._json_or_none(response)
            if data:
                fresh_csrf = data.get("csrf")
                if fresh_csrf:
                    self.csrf = fresh_csrf

            if response.status_code == 201:
                if data is None:
                    response.failure("order invalid JSON")
                    return False
                if data.get("accepted") is True:
                    return True
                response.failure("order accepted false")
                return False

            if response.status_code == 200:
                if data is None:
                    response.failure("order invalid JSON")
                    return False
                if data.get("accepted") is True:
                    return True
                response.failure("order accepted false business failure")
                return False

            response.failure(f"order status {response.status_code}")
            return False

    def _do_work(self):
        url = "/v2/work"
        headers = {"X-CSRF-Token": self.csrf}
        retries = 0

        while True:
            with self.client.post(url, json={}, headers=headers, allow_redirects=False, catch_response=True) as response:
                if response.status_code == 200:
                    data = self._json_or_none(response)
                    if data is None:
                        response.failure("work invalid JSON")
                    elif data.get("ok") is not True:
                        response.failure("work ok false")
                    return

                if response.status_code == 429:
                    if retries >= 4:
                        response.failure("work scheduled 429 after max retries")
                        return

                    retry_after = response.headers.get("Retry-After")
                    try:
                        wait = float(retry_after) if retry_after else 1.0
                    except Exception:
                        wait = 1.0

                    time.sleep(wait)
                    retries += 1
                    continue

                response.failure(f"work status {response.status_code}")
                return

    def _run_business_flow(self):
        if not self._login():
            return False

        product_id, variant_id = self._fetch_catalog_candidates()
        if product_id is None or variant_id is None:
            self._mark_no_product_failure()
            return False

        # Challenge grant is optional; a missing or failed optional claim is not itself a failure.
        self._claim_grant()

        self.cart_id = self._create_cart(product_id, variant_id)
        if self.cart_id is None:
            return False

        if not self._patch_quantity():
            return False

        reservation_id = None
        status_url = self._create_reservation()
        if status_url:
            reservation_id = self._poll_reservation(status_url)

        if not self._place_order(reservation_id):
            return False

        return True
