import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {

    private static String extractString(String json, String key) {
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*\"([^\"]*)\"");
        Matcher m = p.matcher(json);
        if (m.find()) {
            return m.group(1);
        }
        return null;
    }

    private static String extractIdValue(String json, String key) {
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*(\"([^\"]*)\"|(\\d+))");
        Matcher m = p.matcher(json);
        if (m.find()) {
            if (m.group(2) != null) {
                return m.group(2);
            }
            return m.group(3);
        }
        return null;
    }

    private static int findArrayEnd(String s, int start) {
        int depth = 0;
        boolean inString = false;
        for (int i = start; i < s.length(); i++) {
            char c = s.charAt(i);
            if (inString) {
                if (c == '\\') {
                    i++;
                } else if (c == '"') {
                    inString = false;
                }
                continue;
            }
            if (c == '"') {
                inString = true;
            } else if (c == '[') {
                depth++;
            } else if (c == ']') {
                depth--;
                if (depth == 0) {
                    return i;
                }
            }
        }
        return -1;
    }

    private static String extractFirstProductId(String json) {
        int productsIdx = json.indexOf("\"products\"");
        if (productsIdx < 0) {
            return null;
        }
        String sub = json.substring(productsIdx);
        return extractIdValue(sub, "id");
    }

    private static String findInStockVariant(String json) {
        int variantsIdx = json.indexOf("\"variants\"");
        if (variantsIdx < 0) {
            return null;
        }
        int arrayStart = json.indexOf('[', variantsIdx);
        if (arrayStart < 0) {
            return null;
        }
        int arrayEnd = findArrayEnd(json, arrayStart);
        if (arrayEnd < 0) {
            return null;
        }
        String arr = json.substring(arrayStart, arrayEnd + 1);
        Pattern objPattern = Pattern.compile("\\{[^}]*\\}");
        Matcher m = objPattern.matcher(arr);
        while (m.find()) {
            String obj = m.group();
            String id = extractIdValue(obj, "id");
            if (id != null && obj.matches(".*\"in_stock\"\\s*:\\s*true.*")) {
                return id;
            }
        }
        return null;
    }

    private static String extractNext(String json) {
        Pattern p = Pattern.compile("\"next\"\\s*:\\s*\"([^\"]*)\"");
        Matcher m = p.matcher(json);
        if (m.find()) {
            return m.group(1);
        }
        return null;
    }

    private static boolean extractBoolean(String json, String key) {
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*(true|false)");
        Matcher m = p.matcher(json);
        return m.find() && "true".equals(m.group(1));
    }

    private HttpProtocolBuilder httpProtocol = http
        .baseUrl(System.getenv("BASE_URL"))
        .disableFollowRedirect()
        .contentTypeHeader("application/json")
        .acceptHeader("application/json");

    private ChainBuilder patchAttempt(int attempt) {
        return exec(http("PATCH cart attempt " + attempt)
            .patch("/v2/carts/#{cartId}")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{currentCsrf}")
            .header("If-Match", "#{cartEtag}")
            .body(StringBody("{\"quantity\":2}"))
            .check(status().saveAs("patchStatus" + attempt))
            .check(status().is(200).or(201).or(204).or(412))
            .check(header("ETag").optional().saveAs("cartEtag"))
            .check(bodyString().saveAs("patchBody" + attempt))
        );
    }

    {
        ScenarioBuilder journey = scenario("ShopJourney")
            .exec(session -> {
                long uid = session.userId();
                if (uid < 1) {
                    uid = 1;
                }
                long profileIdx = (uid - 1) % 2;
                String username = "bench-" + ((uid % 16) == 0 ? 16 : (uid % 16));
                return session
                    .set("username", username)
                    .set("password", "bench")
                    .set("profileIndex", profileIdx)
                    .set("foundItem", false)
                    .set("catalogExhausted", false)
                    .set("catalogPageCount", 0L)
                    .set("nextCatalogUrl", "/v2/catalog/page");
            })
            .exec(http("GET login form")
                .get("/v2/login-form")
                .check(status().is(200))
                .check(css("input[name='csrf']", "value").saveAs("loginCsrf"))
            )
            .exec(http("POST login")
                .post("/v2/login")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{loginCsrf}")
                .body(StringBody("{\"username\":\"#{username}\",\"password\":\"#{password}\",\"csrf\":\"#{loginCsrf}\"}"))
                .check(status().is(200).or(302))
                .check(header("Location").optional().saveAs("loginLocation"))
                .check(bodyString().saveAs("loginBody"))
            )
            .doIf(session -> session.contains("loginLocation") && !session.getString("loginLocation").isEmpty())
                .then(
                    exec(http("GET login location")
                        .get(session -> session.getString("loginLocation"))
                        .check(status().is(200))
                        .check(bodyString().saveAs("loginBody"))
                    )
                )
            .exec(session -> {
                String body = session.getString("loginBody");
                String csrf = extractString(body, "csrf");
                if (csrf == null) {
                    throw new RuntimeException("No csrf in login response");
                }
                return session.set("authCsrf", csrf).set("currentCsrf", csrf);
            })
            .asLongAs(session ->
                    !session.getBoolean("foundItem") &&
                        !session.getBoolean("catalogExhausted") &&
                        session.getLong("catalogPageCount") < 3L,
                "catalogPageCount")
            .on(
                exec(http("GET catalog page")
                    .get(session -> session.getString("nextCatalogUrl"))
                    .check(status().is(200))
                    .check(bodyString().saveAs("catalogBody"))
                )
                    .exec(session -> {
                        String body = session.getString("catalogBody");
                        String productId = extractFirstProductId(body);
                        String variantId = findInStockVariant(body);
                        String next = extractNext(body);

                        if (productId != null && variantId != null) {
                            return session
                                .set("productId", productId)
                                .set("variantId", variantId)
                                .set("foundItem", true);
                        }

                        if (next == null) {
                            return session.set("catalogExhausted", true);
                        }

                        return session.set("nextCatalogUrl", next);
                    })
            )
            .doIf(session -> !session.getBoolean("foundItem"))
                .then(
                    exec(session -> {
                        throw new RuntimeException("No eligible in-stock item found within 3 catalog pages");
                    })
                )
            .exec(http("POST create cart")
                .post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{currentCsrf}")
                .body(StringBody("{\"product_id\":\"#{productId}\",\"variant_id\":\"#{variantId}\"}"))
                .check(status().is(201))
                .check(header("ETag").optional().saveAs("cartEtag"))
                .check(bodyString().saveAs("cartCreateBody"))
            )
            .exec(session -> {
                String body = session.getString("cartCreateBody");
                String cartId = extractIdValue(body, "id");
                String csrf = extractString(body, "csrf");
                if (cartId == null) {
                    throw new RuntimeException("Cart create response missing id");
                }
                session = session.set("cartId", cartId);
                if (csrf != null) {
                    session = session.set("currentCsrf", csrf);
                }
                return session;
            })
            .doIf(session -> !session.contains("cartEtag"))
                .then(
                    exec(http("GET cart for ETag")
                        .get("/v2/carts/#{cartId}")
                        .check(status().is(200))
                        .check(header("ETag").optional().saveAs("cartEtag"))
                    )
                )
            .exec(patchAttempt(1))
            .exec(session -> {
                String body = session.getString("patchBody1");
                String csrf = extractString(body, "csrf");
                if (csrf != null) {
                    session = session.set("currentCsrf", csrf);
                }
                int status = session.getInt("patchStatus1");
                if (status == 412) {
                    return session.set("patchRetry", true);
                }
                if (status == 200 || status == 201 || status == 204) {
                    return session.set("patchRetry", false);
                }
                throw new RuntimeException("Unexpected PATCH status " + status);
            })
            .doIf(session -> session.getBoolean("patchRetry"))
                .then(
                    exec(http("GET cart after 412")
                        .get("/v2/carts/#{cartId}")
                        .check(status().is(200))
                        .check(header("ETag").saveAs("cartEtag"))
                        .check(bodyString().saveAs("cartGetBody"))
                    )
                        .exec(session -> {
                            String body = session.getString("cartGetBody");
                            String csrf = extractString(body, "csrf");
                            if (csrf != null) {
                                session = session.set("currentCsrf", csrf);
                            }
                            return session;
                        })
                        .exec(patchAttempt(2))
                        .exec(session -> {
                            String body = session.getString("patchBody2");
                            String csrf = extractString(body, "csrf");
                            if (csrf != null) {
                                session = session.set("currentCsrf", csrf);
                            }
                            int status = session.getInt("patchStatus2");
                            if (status == 200 || status == 201 || status == 204) {
                                return session;
                            }
                            throw new RuntimeException("PATCH retry failed with status " + status);
                        })
                )
            .exec(http("POST create order")
                .post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{currentCsrf}")
                .header("Idempotency-Key", "order-#{cartId}")
                .header("If-Match", "#{cartEtag}")
                .body(StringBody("{\"cart_id\":\"#{cartId}\"}"))
                .check(status().is(201))
                .check(bodyString().saveAs("orderBody"))
            )
            .exec(session -> {
                String body = session.getString("orderBody");
                if (!extractBoolean(body, "accepted")) {
                    throw new RuntimeException("Order accepted=false: " + body);
                }
                String orderId = extractIdValue(body, "id");
                String csrf = extractString(body, "csrf");
                if (orderId == null) {
                    throw new RuntimeException("Order response missing id");
                }
                session = session.set("orderId", orderId);
                if (csrf != null) {
                    session = session.set("currentCsrf", csrf);
                }
                return session;
            });

        ScenarioBuilder scn = scenario("ModelSimulation")
            .repeat(2, "iteration")
            .on(journey);

        setUp(
            scn.injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol);
    }
}
