import http from 'k6/http';
import { sleep } from 'k6';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

let csrf = '';
let currentUsername = '';

function toAbsolute(rel) {
  if (!rel) return rel;
  if (/^https?:\/\//i.test(rel)) return rel;
  const base = BASE_URL.replace(/\/$/, '');
  if (rel.startsWith('/')) return base + rel;
  return base + '/' + rel.replace(/^\//, '');
}

function getJson(res) {
  if (!res || !res.body) return null;
  try {
    return JSON.parse(res.body);
  } catch (e) {
    return null;
  }
}

function parseNamedInput(html, name) {
  if (!html) return null;
  const tags = html.match(/<input\b[^>]*>/gi) || [];
  for (const tag of tags) {
    const m = tag.match(/name\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!m) continue;
    const attrValue = m[1] !== undefined ? m[1] : (m[2] !== undefined ? m[2] : m[3]);
    if (attrValue === name) {
      const vm = tag.match(/value\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
      return vm ? (vm[1] !== undefined ? vm[1] : (vm[2] !== undefined ? vm[2] : vm[3])) : '';
    }
  }
  return null;
}

function parseFormAction(html) {
  const m = html.match(/<form\b[^>]*>/i);
  if (!m) return null;
  const tag = m[0];
  const action = tag.match(/action\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
  if (!action) return null;
  return action[1] !== undefined ? action[1] : (action[2] !== undefined ? action[2] : action[3]);
}

function getETag(res) {
  const headers = res.headers || {};
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === 'etag') return headers[key];
  }
  return null;
}

function updateCsrf(res) {
  let token = null;
  const j = getJson(res);
  if (j && typeof j.csrf === 'string') token = j.csrf;
  if (!token) {
    const htmlToken = parseNamedInput(res.body, 'csrf');
    if (htmlToken) token = htmlToken;
  }
  if (token) csrf = token;
  return csrf;
}

function authErrorType(res) {
  const j = getJson(res);
  if (!j) return null;
  const err = j.error || (j.data && j.data.error);
  if (!err) return null;
  let s = '';
  if (typeof err === 'string') s = err;
  else if (err.code) s = String(err.code);
  else if (err.type) s = String(err.type);
  else if (err.message) s = String(err.message);
  else s = JSON.stringify(err);
  s = s.toLowerCase();
  if (s.includes('denied')) return 'denied';
  if (s.includes('expired')) return 'expired';
  if (s.includes('session')) return 'session';
  return s;
}

function postJSON(url, body, extraHeaders) {
  extraHeaders = extraHeaders || {};
  const headers = Object.assign({
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf
  }, extraHeaders);
  return http.post(url, JSON.stringify(body || {}), { redirects: 'manual', headers });
}

function login(username) {
  currentUsername = username;

  const formRes = http.get(toAbsolute('/v2/login-form'), { redirects: 'manual' });
  if (formRes.status !== 200) {
    throw new Error('login-form status ' + formRes.status);
  }

  const formCsrf = parseNamedInput(formRes.body, 'csrf');
  if (!formCsrf) {
    throw new Error('login form missing csrf');
  }
  csrf = formCsrf;

  const loginRes = http.post(toAbsolute('/v2/login'), JSON.stringify({
    username: username,
    password: 'bench',
    csrf: formCsrf
  }), {
    redirects: 'manual',
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': formCsrf
    }
  });

  if (loginRes.status === 302 || loginRes.status === 301 || loginRes.status === 303 || loginRes.status === 307 || loginRes.status === 308) {
    updateCsrf(loginRes);
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    if (!loc) {
      throw new Error('login 302 missing location');
    }
    const finalRes = http.get(toAbsolute(loc), { redirects: 'manual' });
    if (finalRes.status !== 200) {
      throw new Error('login final status ' + finalRes.status);
    }
    updateCsrf(finalRes);
    if (!csrf) {
      throw new Error('login did not provide csrf');
    }
    return;
  }

  if (loginRes.status !== 200 && loginRes.status !== 201) {
    throw new Error('login status ' + loginRes.status);
  }

  updateCsrf(loginRes);
  if (!csrf) {
    throw new Error('login did not provide csrf');
  }
}

function recoverSession(cartId, errorType) {
  if (errorType === 'session') {
    login(currentUsername);
  } else if (errorType === 'expired') {
    const renewRes = http.post(toAbsolute('/v2/session/renew'), '{}', {
      redirects: 'manual',
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf
      }
    });
    if (renewRes.status === 200) {
      updateCsrf(renewRes);
    } else if (renewRes.status === 401) {
      login(currentUsername);
    } else {
      throw new Error('session renew status ' + renewRes.status);
    }
  } else {
    throw new Error('unknown 401 error type ' + errorType);
  }

  if (cartId) {
    const recRes = http.post(toAbsolute('/v2/carts/' + cartId + '/recover'), '{}', {
      redirects: 'manual',
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf
      }
    });
    if (recRes.status !== 200 && recRes.status !== 201) {
      throw new Error('cart recover status ' + recRes.status);
    }
    updateCsrf(recRes);
  }
}

function executeWithRecovery(operation, cartId) {
  let res = operation();
  if (res.status === 401) {
    const errType = authErrorType(res);
    if (errType === 'denied') {
      throw new Error('401 denied');
    }
    if (!errType) {
      throw new Error('401 without usable error type');
    }
    recoverSession(cartId, errType);
    res = operation();
    if (res.status === 401) {
      const secondErr = authErrorType(res) || 'unknown';
      if (secondErr === 'denied') {
        throw new Error('401 denied');
      }
      throw new Error('401 after recovery: ' + secondErr);
    }
  }
  return res;
}

function isInStock(variant) {
  return variant.in_stock === true ||
    variant.in_stock === 1 ||
    variant.in_stock === 'true' ||
    variant.in_stock === '1';
}

function extractProducts(body) {
  const out = [];
  if (!body) return out;

  if (body.data && Array.isArray(body.data.products)) {
    out.push(...body.data.products);
  } else if (body.data && Array.isArray(body.data)) {
    out.push(...body.data);
  }

  if (body.data && body.data.product) out.push(body.data.product);
  if (body.products) out.push(...body.products);
  if (body.product) out.push(body.product);
  if (body.id && body.variants) out.push(body);
  if (body.data && body.data.id && body.data.variants) out.push(body.data);

  return out;
}

function extractNext(body) {
  if (!body) return null;
  if (typeof body.next === 'string') return body.next;
  if (body.data && typeof body.data.next === 'string') return body.data.next;
  return null;
}

function findEligibleProduct() {
  let rel = '/v2/catalog/page';

  for (let page = 0; page < 3; page++) {
    const full = toAbsolute(rel);
    const res = executeWithRecovery(() => http.get(full, { redirects: 'manual' }), null);
    if (res.status !== 200) {
      throw new Error('catalog page status ' + res.status);
    }

    const body = getJson(res);
    if (!body) {
      throw new Error('catalog page not JSON');
    }

    const products = extractProducts(body);
    for (const product of products) {
      if (!product || !product.id || !Array.isArray(product.variants)) continue;
      const variant = product.variants.find(v => v && v.id && isInStock(v));
      if (variant) {
        return { product_id: product.id, variant_id: variant.id };
      }
    }

    const next = extractNext(body);
    if (!next) break;
    rel = next;
  }

  throw new Error('no eligible item after at most 3 catalog pages');
}

function solveOptionalChallenge() {
  const formRes = http.get(toAbsolute('/v2/challenge-form'), { redirects: 'manual' });
  if (formRes.status === 404 || formRes.status === 405) return null;
  if (formRes.status !== 200) {
    throw new Error('challenge-form status ' + formRes.status);
  }

  updateCsrf(formRes);

  const action = parseFormAction(formRes.body);
  const challenge = parseNamedInput(formRes.body, 'challenge');
  if (!action || challenge === null) return null;

  let res = executeWithRecovery(() => http.post(toAbsolute(action), JSON.stringify({ challenge: challenge }), {
    redirects: 'manual',
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    }
  }), null);

  if (res.status === 302 || res.status === 301 || res.status === 303 || res.status === 307 || res.status === 308) {
    const loc = res.headers['Location'] || res.headers['location'];
    if (!loc) {
      throw new Error('challenge redirect missing location');
    }
    const finalRes = http.get(toAbsolute(loc), { redirects: 'manual' });
    if (finalRes.status !== 200 && finalRes.status !== 201) {
      throw new Error('challenge final status ' + finalRes.status);
    }
    res = finalRes;
  }

  if (res.status !== 200 && res.status !== 201) {
    throw new Error('challenge status ' + res.status);
  }

  const body = getJson(res);
  if (!body || !body.grant_id) {
    throw new Error('challenge success did not provide grant_id');
  }

  updateCsrf(res);
  return body.grant_id;
}

function createCart(item, grantId) {
  const payload = {
    product_id: item.product_id,
    variant_id: item.variant_id
  };
  if (grantId) payload.grant_id = grantId;

  const res = executeWithRecovery(() => postJSON(toAbsolute('/v2/carts'), payload), null);
  if (res.status !== 201) {
    throw new Error('cart create status ' + res.status);
  }

  const body = getJson(res);
  if (!body || !body.id) {
    throw new Error('cart create missing id');
  }

  updateCsrf(res);
  return body.id;
}

function getCart(cartId) {
  const res = executeWithRecovery(() => http.get(toAbsolute('/v2/carts/' + cartId), { redirects: 'manual' }), cartId);
  if (res.status !== 200) {
    throw new Error('get cart status ' + res.status);
  }

  const etag = getETag(res);
  if (!etag) {
    throw new Error('cart missing ETag');
  }

  updateCsrf(res);
  return etag;
}

function patchCart(cartId, initialEtag) {
  let etag = initialEtag;
  const payload = { quantity: 1 };

  const doPatch = () => http.patch(toAbsolute('/v2/carts/' + cartId), JSON.stringify(payload), {
    redirects: 'manual',
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag
    }
  });

  let res = executeWithRecovery(doPatch, cartId);

  if (res.status === 412) {
    etag = getCart(cartId);
    res = executeWithRecovery(() => http.patch(toAbsolute('/v2/carts/' + cartId), JSON.stringify(payload), {
      redirects: 'manual',
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
        'If-Match': etag
      }
    }), cartId);
  }

  if (res.status !== 200 && res.status !== 201 && res.status !== 204) {
    throw new Error('cart patch status ' + res.status);
  }

  updateCsrf(res);
}

function reserve(cartId) {
  let res = executeWithRecovery(() => postJSON(toAbsolute('/v2/reservations'), { cart_id: cartId }), cartId);
  if (res.status !== 202) {
    throw new Error('reservation POST status ' + res.status);
  }

  let body = getJson(res);
  if (!body) {
    throw new Error('reservation body missing');
  }
  updateCsrf(res);

  if (body.status === 'ready') {
    if (!body.reservation_id) {
      throw new Error('reservation ready without id');
    }
    return body.reservation_id;
  }
  if (body.status === 'failed') {
    throw new Error('reservation failed');
  }

  if (!body.status_url) {
    throw new Error('reservation missing status_url');
  }

  const statusUrl = body.status_url;

  for (let attempt = 0; attempt < 5; attempt++) {
    sleep(0.05);

    const pollRes = executeWithRecovery(() => http.get(toAbsolute(statusUrl), { redirects: 'manual' }), cartId);
    if (pollRes.status !== 200) {
      throw new Error('reservation poll status ' + pollRes.status);
    }

    const pollBody = getJson(pollRes);
    if (!pollBody) {
      throw new Error('reservation poll body missing');
    }
    updateCsrf(pollRes);

    if (pollBody.status === 'ready') {
      if (!pollBody.reservation_id) {
        throw new Error('reservation ready without id');
      }
      return pollBody.reservation_id;
    }
    if (pollBody.status === 'failed') {
      throw new Error('reservation failed');
    }
    if (pollBody.status !== 'pending') {
      throw new Error('unknown reservation status ' + pollBody.status);
    }
  }

  throw new Error('reservation not ready after 5 polls');
}

function placeOrder(cartId, reservationId, etag) {
  const idempotencyKey = 'order-' + cartId + '-' + Date.now();
  const payload = { cart_id: cartId };
  if (reservationId) {
    payload.reservation_id = reservationId;
  }

  const doOrder = () => {
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'Idempotency-Key': idempotencyKey
    };
    if (etag) headers['If-Match'] = etag;

    return http.post(toAbsolute('/v2/orders'), JSON.stringify(payload), {
      redirects: 'manual',
      headers: headers
    });
  };

  const res = executeWithRecovery(doOrder, cartId);

  if (res.status === 200) {
    const j = getJson(res);
    if (j && j.accepted === false) {
      throw new Error('order accepted:false business failure');
    }
    throw new Error('order success only expected 201');
  }

  if (res.status !== 201) {
    throw new Error('order status ' + res.status);
  }

  const body = getJson(res);
  if (!body || body.accepted !== true || !body.id) {
    throw new Error('order malformed');
  }

  updateCsrf(res);
  return body.id;
}

