from locust import HttpUser, LoadTestShape, task, constant

EXPECTED_USERS = 2
COMPLETED_USERS = 0


class CSRFExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.candidates = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "input":
            attrs_dict = {k.lower(): v for k, v in attrs}
            if attrs_dict.get("name") == "csrf":
                self.candidates.append(attrs_dict)

    def get_csrf(self):
        for attrs in self.candidates:
            if attrs.get("type", "").lower() == "hidden" and attrs.get("value"):
                return attrs["value"]
        for attrs in self.candidates:
            if attrs.get("value"):
                return attrs["value"]
        return None


class ChallengeFormExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.forms = []
        self._current_form = None

    def handle_starttag(self, tag, attrs):
        attrs_dict = {k.lower(): v for k, v in attrs}
        if tag.lower() == "form":
            self._current_form = {"action": attrs_dict.get("action"), "inputs": []}
            self.forms.append(self._current_form)
        elif tag.lower() == "input" and self._current_form is not None:
            self._current_form["inputs"].append(attrs_dict)

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._current_form = None


