                if attempt < 4:
                    sleep(1.0)
                    continue
                return

            if resp.status_code == 401:
                if self._handle_401(resp, None):
                    return
                resp.failure("work 401 recovery failed")
                return

            resp.failure(f"work unexpected {resp.status_code}: {resp.text[:100]}")
            return

    def login(self):
        form_resp = self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            allow_redirects=False,
            catch_response=True,
        )
        if form_resp.status_code != 200:
            form_resp.failure(f"login form: expected 200, got {form_resp.status_code}")
            return False

        csrf = self._extract_csrf(form_resp.text)
        if not csrf:
            form_resp.failure("login form missing csrf")
            return False
        self.csrf = csrf

        payload = {"username": self.username, "password": "bench", "csrf": self.csrf}
        login_resp = self.client.post(
            "/v2/login",
            json=payload,
            headers=self._auth_headers(),
            name="/v2/login",
            allow_redirects=False,
            catch_response=True,
        )
        self._update_csrf_from_response(login_resp)

        if login_resp.status_code in (301, 302, 303, 307, 308):
            location = login_resp.headers.get("Location")
            if not location:
                login_resp.failure("login redirect missing Location")
                return False
            loc_resp = self.client.get(
                self._absolute_url(location),
                name="/v2/login-location",
                allow_redirects=False,
                catch_response=True,
            )
            self._update_csrf_from_response(loc_resp)
            if loc_resp.status_code not in (200, 201):
                loc_resp.failure(f"login location: expected 200/201, got {loc_resp.status_code}")
                return False
        elif login_resp.status_code not in (200, 201):
            login_resp.failure(f"login unexpected {login_resp.status_code}: {login_resp.text[:100]}")
            return False

        return True

    def find_eligible_product(self):
        cursor = "/v2/catalog/page"
        for page_index in range(3):
            resp = self.client.get(
                cursor,
                name="/v2/catalog/page",
                allow_redirects=False,
                catch_response=True,
            )
            if resp.status_code != 200:
                resp.failure(f"catalog page {page_index}: expected 200, got {resp.status_code}: {resp.text[:100]}")
                return None, None

            payload = self._json_or_none(resp)
            if not isinstance(payload, dict):
                resp.failure("catalog page invalid JSON")
                return None, None

            products = self._extract_products(payload)
            for product in products:
                if not isinstance(product, dict):
                    continue
                pid = product.get("id")
                variants = product.get("variants")
                if not isinstance(pid, (int, str)) or not isinstance(variants, list):
                    continue
                for variant in variants:
                    if not isinstance(variant, dict):
                        continue
                    vid = variant.get("id")
                    if not isinstance(vid, (int, str)):
                        continue
                    if variant.get("in_stock"):
                        return pid, vid

            next_link = payload.get("next")
            if next_link and page_index < 2:
                cursor = self._absolute_url(next_link)
            else:
                break

        return None, None

    def solve_challenge(self):
        for attempt in range(2):
            form_resp = self.client.get(
                "/v2/challenge-form",
                name="/v2/challenge-form",
                allow_redirects=False,
                catch_response=True,
            )
            if form_resp.status_code == 404:
                return None
            if form_resp.status_code != 200:
                form_resp.failure(f"challenge form: expected 200, got {form_resp.status_code}")
                return None

            action, challenge_value = self._parse_challenge_form(form_resp.text)
            if not action:
                form_resp.failure("challenge action missing")
                return None
            if challenge_value is None:
                challenge_value = ""

            payload = {"challenge": challenge_value}
            post_resp = self.client.post(
                self._absolute_url(action),
                json=payload,
                headers=self._auth_headers(),
                name="/v2/challenges",
                allow_redirects=False,
                catch_response=True,
            )
            self._update_csrf_from_response(post_resp)

            if post_resp.status_code in (301, 302, 303, 307, 308):
                location = post_resp.headers.get("Location")
                if not location:
                    post_resp.failure("challenge redirect missing Location")
                    return None
                grant_resp = self.client.get(
                    self._absolute_url(location),
                    name="/v2/challenge-grant",
                    allow_redirects=False,
                    catch_response=True,
                )
                self._update_csrf_from_response(grant_resp)
                if grant_resp.status_code != 200:
                    grant_resp.failure(f"challenge grant: expected 200, got {grant_resp.status_code}")
                    return None
                grant_data = self._json_or_none(grant_resp)
                if isinstance(grant_data, dict) and grant_data.get("grant_id"):
                    return grant_data["grant_id"]
                grant_resp.failure("challenge grant missing grant_id")
                return None

            if post_resp.status_code in (200, 201):
                data = self._json_or_none(post_resp)
                if isinstance(data, dict) and data.get("grant_id"):
                    return data["grant_id"]
                post_resp.failure("challenge response missing grant_id")
                return None

            if post_resp.status_code == 401 and attempt == 0:
                if self._handle_401(post_resp, self.cart_id):
                    continue
                return None

            post_resp.failure(f"challenge POST unexpected {post_resp.status_code}: {post_resp.text[:100]}")
            return None

        return None

    def _parse_challenge_form(self, html):
        parser = ChallengeFormExtractor()
        parser.feed(html)
        for form in parser.forms:
            action = form.get("action")
            if not action:
                continue
            challenge_value = None
            for inp in form.get("inputs", []):
                if inp.get("name") == "challenge":
                    challenge_value = inp.get("value")
                    break
            if challenge_value is not None or "/challenges/" in action:
                return action, challenge_value
        return None, None

    def create_cart(self, product_id, variant_id, grant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id

        for attempt in range(2):
            resp = self.client.post(
                "/v2/carts",
                json=payload,
                headers=self._auth_headers(),
                name="/v2/carts",
                allow_redirects=False,
                catch_response=True,
            )
            self._update_csrf_from_response(resp)

            if resp.status_code == 201:
                data = self._json_or_none(resp)
                if not isinstance(data, dict) or not data.get("id"):
                    resp.failure("cart created but no id")
                    return False
                self.cart_id = data["id"]
                self.cart_etag = resp.headers.get("ETag")
                return True

            if resp.status_code == 401 and attempt == 0:
                if self._handle_401(resp, None):
                    continue
                return False

            resp.failure(f"cart create unexpected {resp.status_code}: {resp.text[:100]}")
            return False

        return False

    def patch_cart(self):
        if not self.cart_id:
            return False

        payload = {"quantity": 2}
        for attempt in range(2):
            headers = self._auth_headers()
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag

            resp = self.client.patch(
                f"/v2/carts/{self.cart_id}",
                json=payload,
                headers=headers,
                name=f"/v2/carts/{self.cart_id}",
                allow_redirects=False,
                catch_response=True,
            )
            self._update_csrf_from_response(resp)

            if resp.status_code in (200, 201, 204):
                self.cart_etag = resp.headers.get("ETag") or self.cart_etag
                return True

            if resp.status_code == 412 and attempt == 0:
                get_resp = self.client.get(
                    f"/v2/carts/{self.cart_id}",
                    name=f"/v2/carts/{self.cart_id}",
                    allow_redirects=False,
                    catch_response=True,
                )
                self._update_csrf_from_response(get_resp)
                if get_resp.status_code == 200:
                    self.cart_etag = get_resp.headers.get("ETag") or self.cart_etag
                    continue
                get_resp.failure(f"cart re-read for 412 failed: {get_resp.status_code}")
                return False

            if resp.status_code == 401 and attempt == 0:
                if self._handle_401(resp, self.cart_id):
                    continue
                return False

            resp.failure(f"cart patch unexpected {resp.status_code}: {resp.text[:100]}")
            return False

        return False

    def create_reservation(self):
        for attempt in range(2):
            resp = self.client.post(
                "/v2/reservations",
                json={"cart_id": self.cart_id},
                headers=self._auth_headers(),
                name="/v2/reservations",
                allow_redirects=False,
                catch_response=True,
            )
            self._update_csrf_from_response(resp)

            if resp.status_code == 202:
                data = self._json_or_none(resp)
                if not isinstance(data, dict) or not data.get("status_url"):
                    resp.failure("reservation missing status_url")
                    return None
                status_url = self._absolute_url(data["status_url"])
                return self._poll_reservation(status_url)

            if resp.status_code == 401 and attempt == 0:
                if self._handle_401(resp, self.cart_id):
                    continue
                return None

            resp.failure(f"reservation unexpected {resp.status_code}: {resp.text[:100]}")
            return None

        return None

    def _poll_reservation(self, status_url):
        for poll in range(5):
            if poll > 0:
                sleep(0.05)

            resp = self.client.get(
                status_url,
                name="/v2/reservation-status",
                allow_redirects=False,
                catch_response=True,
            )
            self._update_csrf_from_response(resp)

            if resp.status_code != 200:
                resp.failure(f"reservation poll expected 200, got {resp.status_code}: {resp.text[:100]}")
                return None

            data = self._json_or_none(resp)
            if not isinstance(data, dict):
                resp.failure("reservation poll invalid JSON")
                return None

            status = data.get("status")
            if status == "ready":
                reservation_id = data.get("reservation_id")
                if not reservation_id:
                    resp.failure("reservation ready missing reservation_id")
                    return None
                return reservation_id

            if status in ("failed", "error"):
                resp.failure("reservation status failed")
                return None

        return None

    def create_order(self, reservation_id):
        if not self.idempotency_key:
            self.idempotency_key = uuid4().hex

        payload = {"cart_id": self.cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id

        for attempt in range(2):
            headers = self._auth_headers()
            headers["Idempotency-Key"] = self.idempotency_key
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag

            resp = self.client.post(
                "/v2/orders",
                json=payload,
                headers=headers,
                name="/v2/orders",
                allow_redirects=False,
                catch_response=True,
            )
            self._update_csrf_from_response(resp)

            if resp.status_code in (200, 201):
                data = self._json_or_none(resp)
                if isinstance(data, dict) and data.get("accepted"):
                    self.order_id = data.get("id")
                    return True
                resp.failure("order accepted false")
                return False

            if resp.status_code == 401 and attempt == 0:
                if self._handle_401(resp, self.cart_id):
                    continue
                return False

            resp.failure(f"order unexpected {resp.status_code}: {resp.text[:100]}")
            return False

        return False

    def _handle_401(self, response, cart_id=None):
        try:
            error = response.json().get("error")
        except Exception:
            error = None

        if error == "denied":
            response.failure("denied")
            return False

        if error == "expired":
            renew_resp = self.client.post(
                "/v2/session/renew",
                json={},
                headers=self._auth_headers(),
                name="/v2/session/renew",
                allow_redirects=False,
                catch_response=True,
            )
            self._update_csrf_from_response(renew_resp)
            if renew_resp.status_code not in (200, 201, 204):
                renew_resp.failure(f"session renew failed: {renew_resp.status_code}")
                return False
            if cart_id:
                return self._recover_cart(cart_id)
            return True

        if error == "session":
            form_resp = self.client.get(
                "/v2/login-form",
                name="/v2/login-form",
                allow_redirects=False,
                catch_response=True,
            )
            if form_resp.status_code != 200:
                form_resp.failure("relogin form failed")
                return False

            csrf = self._extract_csrf(form_resp.text)
            if not csrf:
                form_resp.failure("relogin missing csrf")
                return False
            self.csrf = csrf

            login_resp = self.client.post(
                "/v2/login",
                json={"username": self.username, "password": "bench", "csrf": self.csrf},
                headers=self._auth_headers(),
                name="/v2/login",
                allow_redirects=False,
                catch_response=True,
            )
            self._update_csrf_from_response(login_resp)

            if login_resp.status_code in (301, 302, 303, 307, 308):
                location = login_resp.headers.get("Location")
                if location:
                    loc_resp = self.client.get(
                        self._absolute_url(location),
                        name="/v2/login-location",
                        allow_redirects=False,
                        catch_response=True,
                    )
                    self._update_csrf_from_response(loc_resp)
                    if loc_resp.status_code not in (200, 201):
                        loc_resp.failure("relogin location failed")
                        return False
            elif login_resp.status_code not in (200, 201):
                login_resp.failure(f"relogin failed: {login_resp.status_code}")
                return False

            if cart_id:
                return self._recover_cart(cart_id)
            return True

        response.failure(f"unexpected 401: {response.text[:100]}")
        return False

    def _recover_cart(self, cart_id):
        resp = self.client.post(
            f"/v2/carts/{cart_id}/recover",
            json={},
            headers=self._auth_headers(),
            name=f"/v2/carts/{cart_id}/recover",
            allow_redirects=False,
            catch_response=True,
        )
        self._update_csrf_from_response(resp)
        if resp.status_code not in (200, 201, 204):
            resp.failure(f"cart recover failed: {resp.status_code}")
            return False

        get_resp = self.client.get(
            f"/v2/carts/{cart_id}",
            name=f"/v2/carts/{cart_id}",
            allow_redirects=False,
            catch_response=True,
        )
        self._update_csrf_from_response(get_resp)
        if get_resp.status_code == 200:
            self.cart_etag = get_resp.headers.get("ETag") or self.cart_etag

        return True


class Profile1User(ShopUser):
