import java.util.Arrays;
import java.util.Collections;
import java.util.Iterator;
import java.util.Map;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  private static Session updateCsrf(Session session, String key) {
    if (session.contains(key)) {
      String value = session.getString(key);
      if (value != null && !value.isEmpty()) {
        return session.set("csrf", value);
      }
    }
    return session;
  }

  private static Session updateEtag(Session session, String key) {
    if (session.contains(key)) {
      String value = session.getString(key);
      if (value != null && !value.isEmpty()) {
        return session.set("etag", value);
      }
    }
    return session;
  }

  private static String extractCsrf(String body) {
    if (body == null) {
      return null;
    }
    int key = body.indexOf("\"csrf\"");
    if (key < 0) {
      return null;
    }
    int colon = body.indexOf(':', key);
    if (colon < 0) {
      return null;
    }
    int valueStart = body.indexOf('"', colon);
    if (valueStart < 0) {
      return null;
    }
    int valueEnd = body.indexOf('"', valueStart + 1);
    if (valueEnd < 0) {
      return null;
    }
    return body.substring(valueStart + 1, valueEnd);
  }

  {
    String baseUrl = System.getenv("BASE_URL") != null ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";

    HttpProtocolBuilder httpProtocol = http.baseUrl(baseUrl)
      .disableAutoRedirect()
      .enableCookieStore()
      .contentTypeHeader("application/json")
      .acceptHeader("application/json, text/plain, */*")
      .userAgentHeader("gatling-etag-simulation");

    Iterator<Map<String, Object>> usersFeeder = Arrays.<Map<String, Object>>asList(
      Collections.<String, Object>singletonMap("user", "bench-1"),
      Collections.<String, Object>singletonMap("user", "bench-2")
    ).iterator();

    ChainBuilder cleanup = exec(session -> session
      .remove("loginLocation")
      .remove("loginCsrf")
      .remove("locationCsrf")
      .remove("cartId")
      .remove("etag")
      .remove("productId")
      .remove("variantId")
      .remove("idemKey")
      .remove("patchStatus")
      .remove("patchEtag")
      .remove("patchCsrf")
      .remove("reReadEtag")
      .remove("reReadCsrf")
      .remove("retryEtag")
      .remove("retryCsrf")
      .remove("refreshEtag")
      .remove("refreshCsrf")
      .remove("orderCsrf")
      .remove("workAttempt")
      .remove("workDone")
      .set("patchStatus", 200)
      .set("workDone", false)
    );

    ChainBuilder login = exec(http("login_form")
      .get("/v2/login-form")
      .check(status().is(200),
        css("input[name=csrf]", "value").saveAs("csrf"))
    )
    .exec(http("login")
      .post("/v2/login")
      .header("X-CSRF-Token", "#{csrf}")
      .body(StringBody("{\"username\":\"#{user}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}"))
      .check(status().is(s -> s == 200 || s == 302),
        header("Location").optional().saveAs("loginLocation"),
        bodyString().transform(s -> extractCsrf(s)).optional().saveAs("loginCsrf"))
    )
    .doIf(session -> session.contains("loginLocation")).then(
      exec(http("login_location")
        .get(session -> session.getString("loginLocation"))
        .check(status().is(200),
          bodyString().transform(s -> extractCsrf(s)).optional().saveAs("locationCsrf"))
      )
    )
    .exec(session -> updateCsrf(session, "loginCsrf"))
    .exec(session -> updateCsrf(session, "locationCsrf"));

    ChainBuilder catalog = exec(http("catalog")
      .get("/v2/catalog")
      .header("X-CSRF-Token", "#{csrf}")
      .check(status().is(200),
        jsonPath("$.data.products[0].id").saveAs("productId"),
        jsonPath("$.data.products[0].variants[?(@.in_stock == true)].id").saveAs("variantId"))
    );

    ChainBuilder createCart = exec(http("create_cart")
      .post("/v2/carts")
      .header("X-CSRF-Token", "#{csrf}")
      .body(StringBody("{\"product_id\":\"#{productId}\",\"variant_id\":\"#{variantId}\"}"))
      .check(status().is(201),
        jsonPath("$.id").saveAs("cartId"),
        jsonPath("$.csrf").optional().saveAs("cartCsrf"),
        header("ETag").saveAs("etag"))
    )
    .exec(session -> updateCsrf(session, "cartCsrf"));

    ChainBuilder patchFirst = exec(http("patch_cart_attempt_1")
      .patch(session -> "/v2/carts/" + session.getString("cartId"))
      .header("X-CSRF-Token", "#{csrf}")
      .header("If-Match", "#{etag}")
      .body(StringBody("{\"quantity\":2}"))
      .check(status().is(s -> s == 200 || s == 412),
        status().saveAs("patchStatus"),
        header("ETag").optional().saveAs("patchEtag"),
        jsonPath("$.csrf").optional().saveAs("patchCsrf"))
    )
    .exec(session -> updateEtag(session, "patchEtag"))
    .exec(session -> updateCsrf(session, "patchCsrf"));

    ChainBuilder rereadAndRetry = exec(http("re_read_cart_after_conflict")
      .get(session -> "/v2/carts/" + session.getString("cartId"))
      .header("X-CSRF-Token", "#{csrf}")
      .check(status().is(200),
        header("ETag").saveAs("reReadEtag"),
        jsonPath("$.csrf").optional().saveAs("reReadCsrf"))
    )
    .exec(session -> updateEtag(session, "reReadEtag"))
    .exec(session -> updateCsrf(session, "reReadCsrf"))
    .exec(http("patch_cart_retry")
      .patch(session -> "/v2/carts/" + session.getString("cartId"))
      .header("X-CSRF-Token", "#{csrf}")
      .header("If-Match", "#{etag}")
      .body(StringBody("{\"quantity\":2}"))
      .check(status().is(200),
        header("ETag").saveAs("retryEtag"),
        jsonPath("$.csrf").optional().saveAs("retryCsrf"))
    )
    .exec(session -> updateEtag(session, "retryEtag"))
    .exec(session -> updateCsrf(session, "retryCsrf"));

    ChainBuilder refreshCart = exec(http("refresh_cart_etag")
      .get(session -> "/v2/carts/" + session.getString("cartId"))
      .header("X-CSRF-Token", "#{csrf}")
      .check(status().is(200),
        header("ETag").saveAs("refreshEtag"),
        jsonPath("$.csrf").optional().saveAs("refreshCsrf"))
    )
    .exec(session -> updateEtag(session, "refreshEtag"))
    .exec(session -> updateCsrf(session, "refreshCsrf"));

    ChainBuilder patchCart = exec(patchFirst)
      .doIf(session -> session.getInt("patchStatus") == 412)
        .then(rereadAndRetry)
      .exec(refreshCart);

    ChainBuilder order = exec(session -> session.set("idemKey", "order-" + session.getString("cartId")))
      .exec(http("create_order")
        .post("/v2/orders")
        .header("X-CSRF-Token", "#{csrf}")
        .header("If-Match", "#{etag}")
        .header("Idempotency-Key", "#{idemKey}")
        .body(StringBody("{\"cart_id\":\"#{cartId}\"}"))
        .check(status().is(201),
          jsonPath("$.accepted").ofBoolean().is(true),
          jsonPath("$.csrf").optional().saveAs("orderCsrf"))
      )
      .exec(session -> updateCsrf(session, "orderCsrf"));

    ChainBuilder work = exec(session -> session.set("workAttempt", 0).set("workDone", false))
      .asLongAs(session -> session.getInt("workAttempt") < 5 && !session.getBoolean("workDone"))
        .on(
          exec(session -> session.set("workAttempt", session.getInt("workAttempt") + 1))
          .exec(http("work")
            .post("/v2/work")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().is(s -> s == 200 || s == 429),
              status().saveAs("workStatus"))
          )
          .doIf(session -> session.getInt("workStatus") == 200)
            .then(exec(session -> session.set("workDone", true)))
          .doIf(session -> session.getInt("workStatus") == 429)
            .then(pause(1))
        );

    ChainBuilder journey = cleanup
      .exec(login)
      .exec(catalog)
      .exec(createCart)
      .exec(patchCart)
      .exec(order)
      .exec(work);

    ScenarioBuilder scn = scenario("etag_cart_update")
      .feed(usersFeeder)
      .repeat(2)
      .on(journey);

    setUp(scn.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
  }
}
