import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';
import { parseHTML } from 'k6/html';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const PROFILES = [
  { require_etag: true, dynamic_etag: true, etag_conflict_once: true },
  {
    require_etag: true,
    dynamic_etag: true,
    etag_conflict_once: true,
    html_layout: 1,
    reverse_catalog: true,
  },
];

export const options = {
  scenarios: {
    journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
};

const businessFailureRate = new Rate('business_failure');

function fatal(message) {
  throw new Error(message);
}

function safeJson(res) {
  try {
    if (res.body && res.body.length > 0) {
      return res.json();
    }
  } catch (e) {
    // ignore parse failures
  }
  return {};
}

function makeHeaders(csrf, extra = {}) {
  const headers = {
    'Content-Type': 'application/json',
  };
  if (csrf) {
    headers['X-CSRF-Token'] = csrf;
  }
  return Object.assign(headers, extra);
}

function absoluteUrl(base, loc) {
  if (!loc) return loc;
  if (loc.startsWith('http://') || loc.startsWith('https://')) return loc;
  return base + (loc.startsWith('/') ? loc : '/' + loc);
}

function extractCsrf(body) {
  const doc = parseHTML(body);
  const inputs = doc.find('input[name=csrf]');
  for (let i = 0; i < inputs.size(); i++) {
    const value = inputs.eq(i).attr('value');
    if (value) return value;
  }
  return '';
}

function clearCookiesIfPossible() {
  try {
    const jar = http.cookieJar();
    if (jar && typeof jar.clear === 'function') {
      jar.clear();
    }
  } catch (e) {
    // ignore
  }
}

function login(username) {
  clearCookiesIfPossible();

  let res = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    headers: { Accept: 'text/html,application/xhtml+xml,application/json' },
  });
  check(res, { 'login form loads': (r) => r.status === 200 });

  const csrf = extractCsrf(res.body);
  check(csrf, { 'login csrf extracted': (c) => c && c.length > 0 });
  if (!csrf) fatal('no login csrf extracted');

  res = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf }),
    {
      redirects: 0,
      headers: { 'Content-Type': 'application/json' },
    }
  );

  if (
    res.status === 302 ||
    res.status === 301 ||
    res.status === 303 ||
    res.status === 307 ||
    res.status === 308
  ) {
    const location = res.headers['Location'];
    if (!location) fatal('login redirect missing Location');
    res = http.get(absoluteUrl(BASE_URL, location), { redirects: 0 });
  }

  check(res, { 'login succeeds': (r) => r.status === 200 });
  const body = safeJson(res);
  if (!body.csrf && !csrf) {
    fatal('no csrf after login');
  }

  return { csrf: body.csrf || csrf, user: body.user };
}

function freshLogin() {
  return login(`bench-${__VU}`);
}

function renewSession(csrf) {
  const res = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
    redirects: 0,
    headers: makeHeaders(csrf),
  });
  const body = safeJson(res);
  if (res.status === 200) {
    return { csrf: body.csrf || csrf, renewed: true, res };
  }
  return { csrf, renewed: false, res };
}

function recoverCart(csrf, cartId) {
  const res = http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, '{}', {
    redirects: 0,
    headers: makeHeaders(csrf),
  });
  const body = safeJson(res);
  return { csrf: body.csrf || csrf, res };
}

function parseRetryAfter(res) {
  const retryAfter = res.headers['Retry-After'];
  if (!retryAfter) return 1;
  const seconds = parseFloat(retryAfter);
  return isNaN(seconds) ? 1 : Math.max(1, seconds);
}

function doBusinessWork(csrf) {
  let currentCsrf = csrf;
  let scheduledRetries = 0;
  let authRetries = 0;

  while (true) {
    const res = http.post(`${BASE_URL}/v2/work`, '{}', {
      redirects: 0,
      headers: makeHeaders(currentCsrf),
    });

    const body = safeJson(res);
    const error = body.error || '';
    const workOk = res.status === 200 && body.ok === true;
    const isExpectedExpiry = res.status === 401 && error === 'expired';
    const isScheduled429 = res.status === 429;
    const unexpected = !workOk && !isScheduled429 && !isExpectedExpiry;

    businessFailureRate.add(unexpected);

    if (workOk) {
      check(res, {
        'work ok': (r) => r.status === 200 && safeJson(r).ok === true,
      });
      return { csrf: currentCsrf, res };
    }

    if (res.status === 200) {
      fatal('work returned 200 but ok was not true');
    }

    if (isScheduled429) {
      scheduledRetries += 1;
      if (scheduledRetries > 4) {
        fatal('scheduled429 retries exhausted on /v2/work');
      }
      sleep(parseRetryAfter(res));
      continue;
    }

    if (res.status === 401) {
      if (error === 'expired') {
        if (authRetries > 0) {
          fatal('401 expired retry limit exceeded on /v2/work');
        }
        authRetries += 1;
        const renew = renewSession(currentCsrf);
        if (!renew.renewed) {
          fatal('session renew failed on work expiry');
        }
        currentCsrf = renew.csrf;
        continue;
      }

      if (error === 'session') {
        if (authRetries > 0) {
          fatal('401 session retry limit exceeded on /v2/work');
        }
        authRetries += 1;
        const loginResult = freshLogin();
        currentCsrf = loginResult.csrf;
        continue;
      }

      if (error === 'denied') {
        fatal('401 denied on /v2/work');
      }

      fatal(`unexpected 401 on /v2/work: ${error || res.body}`);
    }

    fatal(`unexpected work response ${res.status}: ${res.body}`);
  }
}

function getCatalog() {
  const res = http.get(`${BASE_URL}/v2/catalog`, {
    redirects: 0,
    headers: { Accept: 'application/json' },
  });
  check(res, { 'catalog loads': (r) => r.status === 200 });

  const body = safeJson(res);
  const products = body.data && body.data.products ? body.data.products : [];
  for (const product of products) {
    const variants = product.variants || [];
    for (const variant of variants) {
      if (variant.in_stock) {
        return { product_id: product.id, variant_id: variant.id };
      }
    }
  }

  fatal('no in-stock product found in catalog');
}

function patchCart(cartId, etag, csrf, quantity) {
  return http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({ quantity }), {
    redirects: 0,
    headers: makeHeaders(csrf, { 'If-Match': etag }),
  });
}

function performCartPatch(cartId, initialEtag, initialCsrf, quantity) {
  let currentCsrf = initialCsrf;
  let currentEtag = initialEtag;
  let res = patchCart(cartId, currentEtag, currentCsrf, quantity);
  let conflictRetried = false;
  let authRetried = false;

  while (true) {
    if (res.status === 412 && !conflictRetried) {
