import os
import re
import time

from locust import HttpUser, task, constant, StopUser, LoadTestShape

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
QUANTITY = 2
ITERATIONS = 2
USER_COUNT = 2
SPAWN_RATE = 2


class BaseShopUser(HttpUser):
    abstract = True
    host = BASE_URL
    wait_time = constant(0)
    iterations = ITERATIONS
    username = "bench"
    password = "bench"
    reverse_catalog = False
    html_layout = 0

    def on_start(self):
        self.iterations_done = 0
        self.client.allow_redirects = False
        self.csrf = ""

    @task
    def journey_task(self):
        self.iterations_done += 1
        if self.iterations_done > self.iterations:
            raise StopUser()
        self.run_journey()

    def run_journey(self):
        if not self.login():
            return
        product_variant = self.get_product_variant()
        if product_variant is None:
            return
        product_id, variant_id = product_variant
        if not self.create_cart(product_id, variant_id):
            return
        if not self.update_cart_quantity():
            return
        if not self.create_order():
            return
        self.do_work()

    def login(self):
        with self.client.get("/v2/login-form", name="login-form", catch_response=True) as r:
            if r.status_code != 200:
                r.failure(f"login form status {r.status_code}")
                return False
            csrf = self.extract_csrf_input(r.text)
            if not csrf:
                r.failure("login form missing csrf")
                return False

        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": self.password, "csrf": csrf},
            name="login",
            catch_response=True,
        ) as r:
            if r.status_code in (301, 302, 303, 307, 308):
                location = r.headers.get("Location")
                if not location:
                    r.failure("login redirect missing Location")
                    return False
                with self.client.get(location, name="login-redirect", catch_response=True) as rr:
                    if rr.status_code != 200:
                        rr.failure(f"login redirect status {rr.status_code}")
                        r.failure("login redirect failed")
                        return False
                    data = self._json(rr)
                    if not isinstance(data, dict) or "csrf" not in data:
                        rr.failure("login redirect missing csrf")
                        r.failure("login redirect missing csrf")
                        return False
                    self.csrf = data["csrf"]
                    r.success()
                return True
            elif r.status_code == 200:
                data = self._json(r)
                if not isinstance(data, dict) or "csrf" not in data:
                    r.failure("login missing csrf")
                    return False
                self.csrf = data["csrf"]
                r.success()
                return True
            else:
                r.failure(f"login status {r.status_code}")
                return False

    def extract_csrf_input(self, html):
        if not html:
            return ""
        for tag in re.findall(r"<input\b[^>]*>", html, flags=re.I):
            if re.search(r"name\s*=\s*[\"']csrf[\"']", tag, flags=re.I):
                value_match = re.search(r"value\s*=\s*[\"']([^\"']*)[\"']", tag, flags=re.I)
                if value_match:
                    return value_match.group(1)
        return ""

    def _json(self, response):
        try:
            return response.json()
        except Exception:
            return None

    def _update_csrf(self, response):
        data = self._json(response)
        if isinstance(data, dict) and "csrf" in data:
            self.csrf = data["csrf"]

    def get_product_variant(self):
        with self.client.get("/v2/catalog", name="catalog", catch_response=True) as r:
            if r.status_code != 200:
                r.failure(f"catalog status {r.status_code}")
                return None
            data = self._json(r)
            if not isinstance(data, dict):
                r.failure("catalog invalid JSON")
                return None
            products = data.get("data", {}).get("products", [])
            if not isinstance(products, list):
                r.failure("catalog products missing")
                return None
            for product in products:
                if not isinstance(product, dict):
                    continue
                product_id = product.get("id")
                variants = product.get("variants", [])
                if not isinstance(variants, list):
                    continue
                for variant in variants:
                    if (
                        isinstance(variant, dict)
                        and variant.get("in_stock")
                        and variant.get("id") is not None
                    ):
                        if product_id is not None:
                            return product_id, variant["id"]
            r.failure("catalog has no in-stock variant")
            return None

    def create_cart(self, product_id, variant_id):
        headers = {"X-CSRF-Token": self.csrf}
        payload = {"product_id": product_id, "variant_id": variant_id}
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers=headers,
            name="cart-create",
            catch_response=True,
        ) as r:
            if r.status_code != 201:
                r.failure(f"cart create status {r.status_code}")
                return False
            data = self._json(r)
            if not isinstance(data, dict) or "id" not in data:
                r.failure("cart create missing id")
                return False
            self.cart_id = data["id"]
            if "csrf" in data:
                self.csrf = data["csrf"]
            etag = r.headers.get("ETag")
            if not etag:
                r.failure("cart create missing ETag")
                return False
            self.etag = etag
            return True

    def update_cart_quantity(self):
        quantity = QUANTITY
        headers = {"X-CSRF-Token": self.csrf, "If-Match": self.etag}
        with self.client.patch(
            f"/v2/carts/{self.cart_id}",
            json={"quantity": quantity},
            headers=headers,
            name="cart-patch",
            catch_response=True,
        ) as r:
            if 200 <= r.status_code < 300:
                self._update_csrf(r)
                new_etag = r.headers.get("ETag")
                if new_etag:
                    self.etag = new_etag
                return True
            elif r.status_code == 412:
                r.success()
                return self._retry_cart_patch(quantity)
            else:
                r.failure(f"cart patch status {r.status_code}")
                return False

    def _retry_cart_patch(self, quantity):
        with self.client.get(
            f"/v2/carts/{self.cart_id}",
            name="cart-get-retry",
            catch_response=True,
        ) as r:
            if r.status_code != 200:
                r.failure(f"cart get retry status {r.status_code}")
                return False
            fresh_etag = r.headers.get("ETag")
            if not fresh_etag:
                r.failure("cart get retry missing ETag")
                return False

        headers = {"X-CSRF-Token": self.csrf, "If-Match": fresh_etag}
        with self.client.patch(
            f"/v2/carts/{self.cart_id}",
            json={"quantity": quantity},
            headers=headers,
            name="cart-patch-retry",
            catch_response=True,
        ) as r:
            if 200 <= r.status_code < 300:
                self._update_csrf(r)
                final_etag = r.headers.get("ETag")
                self.etag = final_etag or fresh_etag
                return True
            else:
                r.failure(f"cart patch retry status {r.status_code}")
                return False

    def create_order(self):
        if not self.cart_id or not self.etag:
            return False

        idempotency_key = f"bench-order-{self.cart_id}-{int(time.time() * 1000)}"
        self.order_idem_key = idempotency_key
        payload = {"cart_id": self.cart_id}
        headers = {
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": idempotency_key,
            "If-Match": self.etag,
        }

        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            name="order-create",
            catch_response=True,
        ) as r:
            if r.status_code == 201:
                data = self._json(r)
                if isinstance(data, dict) and data.get("accepted") is False:
                    r.failure("order accepted false")
                    return False
                self._update_csrf(r)
                return True
            elif r.status_code == 200:
                data = self._json(r)
                if isinstance(data, dict) and data.get("accepted") is False:
                    r.failure("order business failure 200 accepted false")
                else:
                    r.failure("order returned 200 expected 201")
                return False
            else:
                r.failure(f"order create status {r.status_code}")
                return False

    def do_work(self):
        max_attempts = 5
        for attempt in range(1, max_attempts + 1):
            with self.client.post(
                "/v2/work",
                json={},
                name="work",
                catch_response=True,
            ) as r:
                if r.status_code == 200:
                    r.success()
                    return True
                elif r.status_code == 429:
                    r.success()
                    if attempt < max_attempts:
                        retry_after = r.headers.get("Retry-After")
                        try:
                            retry_after = int(retry_after) if retry_after else 1
                        except Exception:
                            retry_after = 1
                        time.sleep(retry_after)
                        continue
                    else:
                        return True
                else:
                    r.failure(f"unexpected work status {r.status_code}")
                    return False
        return True


class ShopUser(BaseShopUser):
    weight = 1


class ShopUserLayout(BaseShopUser):
    weight = 1
    reverse_catalog = True
    html_layout = 1


class JourneyShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.spawned = False
        self.spawned_at = None
        self.max_seen = 0

    def tick(self):
        current = self.get_current_user_count()

        if not self.spawned:
            self.spawned = True
            self.spawned_at = time.time()
            self.max_seen = 0
            return (USER_COUNT, SPAWN_RATE)

        if current > self.max_seen:
            self.max_seen = current

        if self.max_seen < USER_COUNT and (time.time() - self.spawned_at) < 5:
            return (USER_COUNT, SPAWN_RATE)

        if current == 0 and (time.time() - self.spawned_at) > 3:
            return None

        return (USER_COUNT, 0)
