import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.util.UUID;

public class ModelSimulation extends Simulation {

  private static final String BASE_URL =
      System.getenv("BASE_URL") == null ? "http://127.0.0.1:8000" : System.getenv("BASE_URL");
  private static final int USERS = 2;
  private static final int ITERATIONS = 2;

  private static boolean hasString(Session session, String key) {
    String value = session.getString(key);
    return value != null && !value.isEmpty();
  }

  private static boolean isStatus(Session session, String key, int status) {
    return String.valueOf(status).equals(session.getString(key));
  }

  private static boolean isOrderExpired(Session session) {
    return "401".equals(session.getString("orderStatus"))
        && "expired".equals(session.getString("orderError"));
  }

  private static boolean isOrderRevoked(Session session) {
    return "401".equals(session.getString("orderStatus"))
        && "session".equals(session.getString("orderError"));
  }

  private static boolean isOrderDenied(Session session) {
    return "401".equals(session.getString("orderStatus"))
        && "denied".equals(session.getString("orderError"));
  }

  private static String jsonValue(String s) {
    if (s == null) return "null";
    if (s.matches("-?\\d+")) return s;
    return "\"" + s.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
  }

  private static ChainBuilder loginFlow() {
    return exec(
            http("GET login-form")
                .get("/v2/login-form")
                .check(status().is(200))
                .check(css("input[name='csrf'][value]", "value").saveAs("formCsrf")))
        .exec(
            http("POST login")
                .post("/v2/login")
                .header("X-CSRF-Token", "#{formCsrf}")
                .header("Content-Type", "application/json")
                .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{formCsrf}\"}"))
                .check(status().saveAs("loginStatus"))
                .check(header("Location").optional().saveAs("loginLocation"))
                .check(bodyString().saveAs("loginBody"))
                .check(jsonPath("$.csrf").optional().saveAs("loginCsrf"))
                .check(jsonPath("$.user").optional().saveAs("loginUser")))
        .doIf(session -> isStatus(session, "loginStatus", 302) && hasString(session, "loginLocation"))
        .then(
            exec(
                http("GET login redirect")
                    .get(session -> session.getString("loginLocation"))
                    .check(status().is(200))
                    .check(bodyString().saveAs("loginBody"))
                    .check(jsonPath("$.csrf").optional().saveAs("loginCsrf"))
                    .check(jsonPath("$.user").optional().saveAs("loginUser"))))
        .exec(
            session -> {
              if (!hasString(session, "loginCsrf")) {
                throw new RuntimeException(
                    "missing login csrf. status="
                        + session.getString("loginStatus")
                        + " body="
                        + session.getString("loginBody"));
              }
              return session.set("csrf", session.getString("loginCsrf"));
            });
  }

  private static ChainBuilder catalogFlow() {
    return exec(
        http("GET catalog")
            .get("/v2/catalog")
            .check(status().is(200))
            .check(jsonPath("$.data.products[0].id").saveAs("productId"))
            .check(
                jsonPath("$.data.products[0].variants[?(@.in_stock == true)].id")
                    .saveAs("variantId")));
  }

  private static ChainBuilder createCartFlow() {
    return exec(
            http("POST cart")
                .post("/v2/carts")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Content-Type", "application/json")
                .body(
                    StringBody(
                        session ->
                            "{\"product_id\":"
                                + jsonValue(session.getString("productId"))
                                + ",\"variant_id\":"
                                + jsonValue(session.getString("variantId"))
                                + "}"))
                .check(status().is(201))
                .check(header("ETag").optional().saveAs("cartEtag"))
                .check(jsonPath("$.id").saveAs("cartId"))
                .check(jsonPath("$.csrf").optional().saveAs("cartCsrf"))
                .check(bodyString().saveAs("cartCreateBody")))
        .exec(
            session -> {
              if (hasString(session, "cartCsrf")) {
                session = session.set("csrf", session.getString("cartCsrf"));
              }
              return session;
            });
  }

  private static ChainBuilder renewSession() {
    return exec(
        http("POST session renew")
            .post("/v2/session/renew")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Content-Type", "application/json")
            .body(StringBody("{}"))
            .check(status().is(200))
            .check(jsonPath("$.csrf").saveAs("csrf")));
  }

  private static ChainBuilder recoverCart() {
    return exec(
            http("POST recover cart")
                .post(session -> "/v2/carts/" + session.getString("cartId") + "/recover")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Content-Type", "application/json")
                .body(StringBody("{}"))
                .check(status().is(200))
                .check(header("ETag").optional().saveAs("cartEtag"))
                .check(jsonPath("$.id").optional().saveAs("recoveredCartId"))
                .check(jsonPath("$.csrf").optional().saveAs("recoveredCsrf")))
        .exec(
            session -> {
              if (hasString(session, "recoveredCartId")) {
                session = session.set("cartId", session.getString("recoveredCartId"));
              }
              if (hasString(session, "recoveredCsrf")) {
                session = session.set("csrf", session.getString("recoveredCsrf"));
              }
              return session;
            });
  }

  private static ChainBuilder orderAttempt(String name) {
    return exec(
        http(name)
            .post("/v2/orders")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Content-Type", "application/json")
            .header("Idempotency-Key", session -> session.getString("orderIdemKey"))
            .header("If-Match", session -> session.getString("cartEtag"))
            .body(
                StringBody(
                    session ->
                        "{\"cart_id\":" + jsonValue(session.getString("cartId")) + "}"))
            .check(status().saveAs("orderStatus"))
            .check(bodyString().saveAs("orderBody"))
            .check(jsonPath("$.accepted").optional().saveAs("orderAccepted"))
            .check(jsonPath("$.error").optional().saveAs("orderError"))
            .check(jsonPath("$.csrf").optional().saveAs("orderCsrf")));
  }

  private static ChainBuilder checkoutFlow() {
    return exec(session -> session.set("orderIdemKey", UUID.randomUUID().toString()))
        .exec(orderAttempt("POST order initial"))
        .doIfOrElse(session -> isOrderExpired(session))
        .then(
            renewSession()
                .exec(recoverCart())
                .exec(orderAttempt("POST order retry expired")))
        .orElse(
            doIfOrElse(session -> isOrderRevoked(session))
                .then(
                    loginFlow()
                        .exec(recoverCart())
                        .exec(orderAttempt("POST order retry revoked")))
                .orElse(
                    doIf(session -> isOrderDenied(session))
                        .then(
                            exec(
                                session -> {
                                  throw new RuntimeException(
                                      "order denied with csrf=" + session.getString("csrf"));
                                }))))
        .exec(
            session -> {
              String status = session.getString("orderStatus");
              String accepted = session.getString("orderAccepted");

              if ("201".equals(status) && "true".equals(accepted)) {
                if (hasString(session, "orderCsrf")) {
                  session = session.set("csrf", session.getString("orderCsrf"));
                }
                session = session.set("orderCommitted", true);
              } else if ("200".equals(status) && "false".equals(accepted)) {
                throw new RuntimeException(
                    "business failure: accepted=false body=" + session.getString("orderBody"));
              } else {
                throw new RuntimeException(
                    "order did not succeed status="
                        + status
                        + " error="
                        + session.getString("orderError")
                        + " body="
                        + session.getString("orderBody"));
              }
              return session;
            });
  }

  private final HttpProtocolBuilder httpProtocol =
      http.baseUrl(BASE_URL)
          .disableAutoRedirect()
          .acceptHeader("application/json, text/html, */*")
          .userAgentHeader("GatlingModel");

  public ModelSimulation() {
    ScenarioBuilder scn =
        scenario("shop-user")
            .exec(
                session -> {
                  long userId = session.userId();
                  long index = (userId % 2 == 0) ? 2 : 1;
                  return session.set("username", "bench-" + index);
                })
            .repeat(ITERATIONS)
            .on(
                exec(loginFlow())
                    .exec(catalogFlow())
                    .exec(createCartFlow())
                    .exec(checkoutFlow()));

    setUp(scn.injectOpen(atOnceUsers(USERS))).protocols(httpProtocol);
  }
}
