import http from 'k6/http';
import { sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const businessFailure = new Rate('business_failure');

export const options = {
  vus: 2,
  iterations: 2,
  maxRedirects: 0,
};

function absoluteUrl(location) {
  if (!location) return null;
  if (location.startsWith('http://') || location.startsWith('https://')) return location;
  return BASE_URL + (location.startsWith('/') ? location : '/' + location);
}

function parseJsonSafely(text) {
  try {
    return JSON.parse(text);
  } catch (e) {
    return null;
  }
}

function extractCsrfFromHtml(html) {
  if (!html) return null;
  const inputRegex = /<input[^>]*>/gi;
  let match;
  while ((match = inputRegex.exec(html)) !== null) {
    const tag = match[0];
    if (/name\s*=\s*["']?csrf["']?/i.test(tag)) {
      const valueMatch =
        tag.match(/value\s*=\s*["']([^"']*)["']/i) ||
        tag.match(/value\s*=\s*([^\s>]+)/i);
      if (valueMatch) return valueMatch[1];
    }
  }
  return null;
}

function extractCsrfFromResponse(resp) {
  const body = parseJsonSafely(resp.body);
  if (body && body.csrf) return body.csrf;
  return extractCsrfFromHtml(resp.body);
}

function parseError(body) {
  if (!body) return null;
  const json = parseJsonSafely(body);
  if (json && json.error) return json.error;
  const m = String(body).match(/error["']?\s*[:=]\s*["']?([^"'\s,}]+)/i);
  return m ? m[1] : null;
}

function freshLogin() {
  const formResp = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  if (formResp.status !== 200) {
    throw new Error(`login-form status ${formResp.status}`);
  }
  const formCsrf = extractCsrfFromHtml(formResp.body);
  if (!formCsrf) {
    throw new Error('no csrf in login form');
  }

  const username = `bench-${__VU}`;
  const loginResp = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf: formCsrf }),
    {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': formCsrf },
      redirects: 0,
    }
  );

  if (loginResp.status === 302) {
    const loc = loginResp.headers['Location'];
    if (!loc) throw new Error('login 302 without Location');
    const finalResp = http.get(absoluteUrl(loc), { redirects: 0 });
    return extractCsrfFromResponse(finalResp) || formCsrf;
  }

  if (loginResp.status === 200) {
    return extractCsrfFromResponse(loginResp) || formCsrf;
  }

  throw new Error(`login status ${loginResp.status} body ${loginResp.body}`);
}

function renewSession(csrf) {
  const resp = http.post(
    `${BASE_URL}/v2/session/renew`,
    '{}',
    {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      redirects: 0,
    }
  );
  if (resp.status !== 200) {
    throw new Error(`session renew status ${resp.status} body ${resp.body}`);
  }
  return extractCsrfFromResponse(resp) || csrf;
}

function getCatalogProduct(csrf) {
  const firstResp = http.get(`${BASE_URL}/v2/catalog`, {
    headers: { 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  if (firstResp.status !== 200) {
    throw new Error(`catalog status ${firstResp.status}`);
  }
  const firstBody = parseJsonSafely(firstResp.body);
  if (firstBody && firstBody.data && Array.isArray(firstBody.data.products)) {
    for (const product of firstBody.data.products) {
      const variant = (product.variants || []).find(v => v.in_stock === true);
      if (variant) return { productId: product.id, variantId: variant.id };
    }
  }

  let next = '/v2/catalog/page';
  for (let i = 0; i < 3; i++) {
    const pageResp = http.get(`${BASE_URL}${next}`, {
      headers: { 'X-CSRF-Token': csrf },
      redirects: 0,
    });
    if (pageResp.status !== 200) {
      throw new Error(`catalog page status ${pageResp.status}`);
    }
    const pageBody = parseJsonSafely(pageResp.body);
    if (pageBody && pageBody.data) {
      if (Array.isArray(pageBody.data.products)) {
        for (const product of pageBody.data.products) {
          const variant = (product.variants || []).find(v => v.in_stock === true);
          if (variant) return { productId: product.id, variantId: variant.id };
        }
      } else if (pageBody.data.product) {
        const product = pageBody.data.product;
        const variant = (product.variants || []).find(v => v.in_stock === true);
        if (variant) return { productId: product.id, variantId: variant.id };
      }
    }
    if (pageBody && pageBody.next) {
      next = pageBody.next.startsWith('/') ? pageBody.next : '/' + pageBody.next;
    } else {
      break;
    }
  }
  throw new Error('no in-stock product found');
}

function createCart(productId, variantId, csrf) {
  const body = JSON.stringify({ product_id: productId, variant_id: variantId });
  const resp = http.post(`${BASE_URL}/v2/carts`, body, {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  if (resp.status !== 201) {
    throw new Error(`create cart status ${resp.status} body ${resp.body}`);
  }
  const json = parseJsonSafely(resp.body);
  return {
    cartId: json && json.id,
    csrf: (json && json.csrf) || csrf,
    etag: resp.headers['ETag'] || resp.headers['Etag'] || null,
  };
}

function generateIdempotencyKey() {
  return `idem-${__VU}-${__ITER}-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
}

function postOrder(cartId, idemKey, csrf, etag) {
  const body = JSON.stringify({ cart_id: cartId });
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idemKey,
  };
  if (etag) {
    headers['If-Match'] = etag;
  }
  return http.post(`${BASE_URL}/v2/orders`, body, {
    headers: headers,
    redirects: 0,
  });
}

function checkoutWithRecovery(cartId, idemKey, csrf, etag) {
  let response = postOrder(cartId, idemKey, csrf, etag);
  let recovered = false;
  let preconditionRetried = false;

  while (true) {
    if (response.status === 201) {
      const body = parseJsonSafely(response.body);
      if (body && body.accepted === true) {
        csrf = body.csrf || csrf;
        return { success: true, csrf };
      }
      return { success: false, csrf, message: 'order accepted:false' };
    }

    if (response.status === 401) {
      const error = parseError(response.body);
      if (error === 'expired' || error === 'session') {
        if (recovered) {
          return { success: false, csrf, message: `already recovered once, error=${error}` };
        }
        recovered = true;

        if (error === 'expired') {
          csrf = renewSession(csrf);
        } else {
          csrf = freshLogin();
        }

        const recoverResp = http.post(
          `${BASE_URL}/v2/carts/${cartId}/recover`,
          '{}',
          {
            headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
            redirects: 0,
          }
        );
        if (recoverResp.status !== 200) {
          return { success: false, csrf, message: `recover status ${recoverResp.status}` };
        }
        csrf = extractCsrfFromResponse(recoverResp) || csrf;
        if (recoverResp.headers['ETag'] || recoverResp.headers['Etag']) {
          etag = recoverResp.headers['ETag'] || recoverResp.headers['Etag'];
        }

        response = postOrder(cartId, idemKey, csrf, etag);
        continue;
      }

      // error=denied or unknown
      return { success: false, csrf, message: `401 error=${error}` };
    }

    if (response.status === 412) {
      if (preconditionRetried) {
        return { success: false, csrf, message: '412 already retried' };
      }
      preconditionRetried = true;

      const cartResp = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
        headers: { 'X-CSRF-Token': csrf },
        redirects: 0,
      });
      if (cartResp.status !== 200) {
        return { success: false, csrf, message: `GET cart status ${cartResp.status}` };
      }
      if (cartResp.headers['ETag'] || cartResp.headers['Etag']) {
        etag = cartResp.headers['ETag'] || cartResp.headers['Etag'];
      }

      response = postOrder(cartId, idemKey, csrf, etag);
      continue;
    }

    return { success: false, csrf, message: `unexpected status ${response.status}` };
  }
}

function recordBusinessResponse(resp) {
  let isFailure = false;
  if (resp.status !== 200 && !(resp.status === 429 && resp.headers['Retry-After'])) {
    isFailure = true;
  } else if (resp.status === 200) {
    const body = parseJsonSafely(resp.body);
    if (!body || body.ok !== true) {
      isFailure = true;
    }
  }
  businessFailure.add(isFailure);
}

function performBusinessWork(csrf) {
  const maxRetries = 4;
  let attempt = 0;
  let hadRetryAfterSleep = false;

  while (attempt <= maxRetries) {
    const resp = http.post(
      `${BASE_URL}/v2/work`,
      '{}',
      {
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
        redirects: 0,
      }
    );

    recordBusinessResponse(resp);

    if (resp.status === 200) {
      const body = parseJsonSafely(resp.body);
      if (body && body.ok === true) {
        return { csrf, hadRetryAfterSleep };
      }
      return { csrf, hadRetryAfterSleep }; // failure already recorded
    }

    if (resp.status === 429 && resp.headers['Retry-After']) {
      const retryAfter = parseInt(resp.headers['Retry-After'], 10) || 1;
      sleep(retryAfter);
      hadRetryAfterSleep = true;
      attempt++;
      continue;
    }

    // unexpected failure already recorded
    return { csrf, hadRetryAfterSleep };
  }

  businessFailure.add(true); // exhausted retries
  return { csrf, hadRetryAfterSleep };
}

export default function () {
  http.cookieJar().clear();

  let csrf = freshLogin();

  // Workload before the deliberate expiry window
  const workResult = performBusinessWork(csrf);
  csrf = workResult.csrf;
  if (workResult.hadRetryAfterSleep) {
    // Refresh session if we slept during 429 retries to avoid unexpected expiry on catalog/cart
    csrf = renewSession(csrf);
  }

  // Obtain an in-stock product/variant
  const { productId, variantId } = getCatalogProduct(csrf);

  // Create exactly one cart
  const cart = createCart(productId, variantId, csrf);
  csrf = cart.csrf;
  const cartId = cart.cartId;
  let etag = cart.etag;

  // Let the session expire (expire_after=2s)
  sleep(2.5);

  // Attempt checkout; expect 401 expired, then recover and retry once
  const idemKey = generateIdempotencyKey();
  const checkoutResult = checkoutWithRecovery(cartId, idemKey, csrf, etag);

  if (!checkoutResult.success) {
    throw new Error(`checkout failed: ${checkoutResult.message}`);
  }

  // Exactly one committed order per journey; no further business work is required.
}
