import re
import uuid

from gevent import sleep
from locust import HttpUser, LoadTestShape, task, constant
from locust.exception import StopUser


def extract_input_value(html, name):
    m = re.search(
        r'<input\b[^>]*\sname\s*=\s*["\']?' + re.escape(name) + r'["\']?[^>]*>',
        html,
        re.I,
    )
    if not m:
        return None
    tag = m.group(0)
    v = re.search(r'\svalue\s*=\s*["\']([^"\']*)["\']', tag, re.I)
    if v:
        return v.group(1)
    return ""


class ShopUser(HttpUser):
    wait_time = constant(0)

    def on_start(self):
        self.client.allow_redirects = False
        idx = (uuid.uuid4().int % 16) + 1
        self.username = f"bench-{idx}"
        self.password = "bench"
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.idempotency_key = None

    def _parse_error(self, response):
        try:
            return response.json().get("error")
        except Exception:
            return None

    def do_login(self):
        with self.client.get("/v2/login-form", catch_response=True, name="/v2/login-form") as r:
            if r.status_code != 200:
                r.failure(f"login form status {r.status_code}")
                return False
            csrf = extract_input_value(r.text, "csrf")
            if not csrf:
                r.failure("login form missing csrf")
                return False

        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": self.password, "csrf": csrf},
            headers={"X-CSRF-Token": csrf},
            allow_redirects=False,
            catch_response=True,
            name="/v2/login",
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("login 302 missing Location")
                    return False
                with self.client.get(
                    loc,
                    allow_redirects=False,
                    catch_response=True,
                    name="/v2/login-redirect",
                ) as rr:
                    if rr.status_code != 200:
                        rr.failure(f"login redirect status {rr.status_code}")
                        return False
                    data = rr.json()
                    self.csrf = data.get("csrf", csrf)
                    return True

            if r.status_code == 200:
                data = r.json()
                self.csrf = data.get("csrf", csrf)
                return True

            r.failure(f"login status {r.status_code}: {r.text[:200]}")
            return False

    def get_catalog_product(self):
        with self.client.get("/v2/catalog", catch_response=True, name="/v2/catalog") as r:
            if r.status_code != 200:
                r.failure(f"catalog status {r.status_code}")
                return None
            data = r.json().get("data", {})
            products = data.get("products", []) if isinstance(data, dict) else []
            for p in products:
                p_id = p.get("id")
                for v in p.get("variants", []):
                    if v.get("in_stock") and p_id is not None:
                        return p_id, v.get("id")

        next_url = "/v2/catalog/page"
        for i in range(3):
            with self.client.get(
                next_url, catch_response=True, name="/v2/catalog/page"
            ) as r:
                if r.status_code != 200:
                    r.failure(f"catalog page status {r.status_code}")
                    return None
                payload = r.json()
                product = payload.get("data") or payload.get("product") or payload
                if product:
                    p_id = product.get("id")
                    for v in product.get("variants", []):
                        if v.get("in_stock") and p_id is not None:
                            return p_id, v.get("id")
                next_url = payload.get("next")
                if not next_url or i == 2:
                    r.failure("no in-stock product found in catalog/page")
                    return None
        return None

    def get_challenge_grant(self):
        with self.client.get(
            "/v2/challenge-form", catch_response=True, name="/v2/challenge-form"
        ) as r:
            if r.status_code != 200:
                r.failure(f"challenge form status {r.status_code}")
                return None
            action_match = re.search(
                r'<form\b[^>]*\saction\s*=\s*["\']([^"\']+)["\']', r.text, re.I
            )
            if not action_match:
                r.failure("challenge form action missing")
                return None
            challenge = extract_input_value(r.text, "challenge")
            if not challenge:
                r.failure("challenge input missing")
                return None
            action = action_match.group(1)

        with self.client.post(
            action,
            json={"challenge": challenge},
            headers={"X-CSRF-Token": self.csrf},
            allow_redirects=False,
            catch_response=True,
            name="/v2/challenges/submit",
        ) as r:
            if r.status_code != 302:
                r.failure(f"challenge submit status {r.status_code}: {r.text[:200]}")
                return None
            loc = r.headers.get("Location")
            if not loc:
                r.failure("challenge submit missing Location")
                return None

        with self.client.get(
            loc,
            allow_redirects=False,
            catch_response=True,
            name="/v2/challenge/claim",
        ) as rr:
            if rr.status_code != 200:
                rr.failure(f"challenge claim status {rr.status_code}")
                return None
            data = rr.json()
            if "csrf" in data:
                self.csrf = data["csrf"]
            grant_id = data.get("grant_id")
            if not grant_id:
                rr.failure("grant_id missing")
                return None
            return grant_id

    def create_cart(self, product_id, variant_id, grant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id

        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/carts",
        ) as r:
            if r.status_code != 201:
                r.failure(f"create cart status {r.status_code}: {r.text[:200]}")
                return False
            data = r.json()
            if "id" not in data:
                r.failure("create cart missing id")
                return False
            self.cart_id = data["id"]
            if "csrf" in data:
                self.csrf = data["csrf"]
            etag = r.headers.get("ETag")
            if etag:
                self.cart_etag = etag
            return True

    def refresh_cart_etag(self):
        with self.client.get(
            f"/v2/carts/{self.cart_id}",
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/carts/get",
        ) as r:
            if r.status_code == 200:
                etag = r.headers.get("ETag")
                if etag:
                    self.cart_etag = etag
                data = r.json()
                if "csrf" in data:
                    self.csrf = data["csrf"]
                return True
            r.failure(f"get cart status {r.status_code}: {r.text[:200]}")
            return False

    def recover_cart(self):
        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/carts/recover",
        ) as r:
            if r.status_code in (200, 201):
                data = r.json()
                if "csrf" in data:
                    self.csrf = data["csrf"]
                etag = r.headers.get("ETag")
                if etag:
                    self.cart_etag = etag
                return True
            r.failure(f"recover cart status {r.status_code}: {r.text[:200]}")
            return False

    def recover_session(self, reason):
        if reason == "revoked":
            if not self.do_login():
                return False
        else:
            with self.client.post(
                "/v2/session/renew",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                catch_response=True,
                name="/v2/session/renew",
            ) as r:
                if r.status_code == 200:
                    data = r.json()
                    if "csrf" in data:
                        self.csrf = data["csrf"]
                elif r.status_code == 401:
                    err = self._parse_error(r)
                    if err == "session":
                        if not self.do_login():
                            return False
                    else:
                        r.failure(f"renew 401 {err}")
                        return False
                else:
                    r.failure(f"renew status {r.status_code}: {r.text[:200]}")
                    return False
        return self.recover_cart()

    def attempt_order(self, name="order_attempt"):
        headers = {
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": self.idempotency_key,
        }
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag

        with self.client.post(
            "/v2/orders",
            json={"cart_id": self.cart_id},
            headers=headers,
            catch_response=True,
            name=name,
        ) as r:
            if r.status_code == 201:
                data = r.json()
                if data.get("accepted") is True:
                    if "csrf" in data:
                        self.csrf = data["csrf"]
                    return "success"
                r.failure("order 201 accepted not true")
                return None

            if r.status_code == 401:
                err = self._parse_error(r)
                if err == "expired":
                    return "expired"
                if err == "session":
                    return "revoked"
                if err == "denied":
                    r.failure("order denied (not expiry)")
                    return None
                r.failure(f"order 401 {err}")
                return None

            if r.status_code == 412:
                return "412"

            r.failure(f"order status {r.status_code}: {r.text[:200]}")
            return None

    def run_journey(self):
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.idempotency_key = str(uuid.uuid4())

        if not self.do_login():
            return False

        product = self.get_catalog_product()
        if not product:
            return False
        product_id, variant_id = product

        grant_id = self.get_challenge_grant()
        if not grant_id:
            return False

        if not self.create_cart(product_id, variant_id, grant_id):
            return False

        if not self.cart_etag:
            if not self.refresh_cart_etag():
                return False

        # Expire the session before checkout.
        sleep(3.0)

        status = self.attempt_order("order_initial")
        if status == "success":
            return True

        if status in ("expired", "revoked"):
            if not self.recover_session(status):
                return False
            if not self.refresh_cart_etag():
                return False
            final = self.attempt_order("order_retry")
            return final == "success"

        return False

    @task
    def journey(self):
        iterations = 2
        for _ in range(iterations):
            try:
                self.run_journey()
            except Exception:
                # No stdout evidence; fail only truthfully inside response handlers.
                pass
        raise StopUser()


class Shape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self._started = False
        self._seen_users = False

    def tick(self):
        if not self._started:
            self._started = True
            return (2, 2)

        current = 0
        if self.runner is not None:
            current = self.runner.user_count

        if current > 0:
            self._seen_users = True

        if self._seen_users and current == 0:
            return None

        if not self._seen_users:
            return (2, 2)

        return (current, 2)
