import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static String username(Session session) {
        long userId = Math.abs(session.userId());
        return "bench-" + (userId % 16 + 1);
    }

    private ChainBuilder login() {
        return exec(
                http("login form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(css("input[name=csrf]", "value").saveAs("csrf"))
        ).exec(
                http("login")
                        .post("/v2/login")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session ->
                                "{\"username\":\"" + username(session) +
                                        "\",\"password\":\"bench\",\"csrf\":\"" +
                                        session.getString("csrf") + "\"}"
                        )).asJson()
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("login_location"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
        ).doIf(session -> session.getString("login_location") != null).then(
                http("login follow")
                        .get(session -> session.getString("login_location"))
                        .check(status().is(200))
                        .check(jsonPath("$.csrf").saveAs("csrf"))
        ).exec(session -> session.remove("login_location"))
                .exec(exitHereIfFailed());
    }

    private ChainBuilder challenge() {
        return exec(
                http("challenge form")
                        .get("/v2/challenge-form")
                        .check(status().is(200))
                        .check(css("form", "action").saveAs("challenge_action"))
                        .check(css("input[name=challenge]", "value").saveAs("challenge_value"))
        ).exec(
                http("challenge submit")
                        .post(session -> session.getString("challenge_action"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session ->
                                "{\"challenge\":\"" + session.getString("challenge_value") + "\"}"
                        )).asJson()
                        .check(status().is(302))
                        .check(header("Location").saveAs("challenge_location"))
        ).exec(
                http("challenge follow")
                        .get(session -> session.getString("challenge_location"))
                        .check(status().is(200))
                        .check(jsonPath("$.grant_id").saveAs("grant_id"))
                        .check(jsonPath("$.csrf").saveAs("csrf"))
        ).exec(exitHereIfFailed());
    }

    private ChainBuilder catalog() {
        return exec(
                http("catalog")
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(jsonPath("$.data.products[0].id").saveAs("product_id"))
                        .check(jsonPath("$.data.products[0].variants[?(@.in_stock == true)].id")
                                .find().saveAs("variant_id"))
        ).exec(exitHereIfFailed());
    }

    private ChainBuilder createCart() {
        return exec(
                http("create cart")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> {
                            StringBuilder sb = new StringBuilder();
                            sb.append("{\"product_id\":\"").append(session.getString("product_id"))
                                    .append("\",\"variant_id\":\"").append(session.getString("variant_id"))
                                    .append("\"");
                            if (session.getString("grant_id") != null) {
                                sb.append(",\"grant_id\":\"").append(session.getString("grant_id")).append("\"");
                            }
                            sb.append("}");
                            return sb.toString();
                        })).asJson()
                        .check(status().is(201))
                        .check(jsonPath("$.id").saveAs("cart_id"))
                        .check(jsonPath("$.csrf").saveAs("csrf"))
                        .check(header("ETag").saveAs("cart_etag"))
        ).exec(session -> session.set("idempotency_key", "idem-" + session.getString("cart_id")))
                .exec(exitHereIfFailed());
    }

    private ChainBuilder reserveAndPoll(int maxPolls, long pollIntervalMillis) {
        ChainBuilder createReservation = exec(
                http("create reservation")
                        .post("/v2/reservations")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session ->
                                "{\"cart_id\":\"" + session.getString("cart_id") + "\"}"
                        )).asJson()
                        .check(status().is(202))
                        .check(jsonPath("$.status_url").saveAs("status_url"))
                        .check(jsonPath("$.csrf").saveAs("csrf"))
        ).exec(session -> session.set("poll_count", 0)
                .set("reservation_status", "pending")
                .remove("reservation_id"));

        ChainBuilder poll = exec(
                http("reservation status")
                        .get(session -> session.getString("status_url"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .check(status().is(200))
                        .check(jsonPath("$.status").saveAs("reservation_status"))
                        .check(jsonPath("$.reservation_id").optional().saveAs("reservation_id"))
        ).exec(session -> session.set("poll_count", session.getInt("poll_count") + 1))
                .pause(Duration.ofMillis(pollIntervalMillis));

        ChainBuilder pollLoop = asLongAs(session ->
                session.getInt("poll_count") < maxPolls &&
                        "pending".equals(session.getString("reservation_status"))
        ).on(poll);

        ChainBuilder validation = doIf(session ->
                !"ready".equals(session.getString("reservation_status")) ||
                        session.getString("reservation_id") == null ||
                        session.getString("reservation_id").isEmpty()
        ).then(exec(session -> session.markAsFailed()))
                .exec(exitHereIfFailed());

        return exec(createReservation)
                .exec(exitHereIfFailed())
                .exec(pollLoop)
                .exec(validation);
    }

    private ChainBuilder createOrder() {
        return exec(
                http("create order")
                        .post("/v2/orders")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("Idempotency-Key", session -> session.getString("idempotency_key"))
                        .header("If-Match", session -> session.getString("cart_etag"))
                        .body(StringBody(session ->
                                "{\"cart_id\":\"" + session.getString("cart_id") +
                                        "\",\"reservation_id\":\"" + session.getString("reservation_id") + "\"}"
                        )).asJson()
                        .check(status().is(201))
                        .check(jsonPath("$.accepted").ofBoolean().is(true))
                        .check(jsonPath("$.id").saveAs("order_id"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
        ).exec(exitHereIfFailed());
    }

    private ScenarioBuilder reservationScenario(String name, int maxPolls, long pollIntervalMillis) {
        ChainBuilder journey = exec(login())
                .exec(challenge())
                .exec(catalog())
                .exec(createCart())
                .exec(reserveAndPoll(maxPolls, pollIntervalMillis))
                .exec(createOrder());

        return scenario(name).exec(repeat(2).on(journey));
    }

    {
        long pollInterval = Math.max(50L, Math.round(0.02 * 1000));

        ScenarioBuilder profile0 = reservationScenario("reservation-profile-0", 2, pollInterval);
        ScenarioBuilder profile1 = reservationScenario("reservation-profile-1", 3, pollInterval);

        HttpProtocolBuilder httpProtocol = http
                .baseUrl(System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000"))
                .disableAutoRedirect()
                .acceptHeader("application/json")
                .contentTypeHeader("application/json")
                .userAgentHeader("ModelSimulation/1.0");

        setUp(
                profile0.injectOpen(atOnceUsers(1)),
                profile1.injectOpen(atOnceUsers(1))
        ).protocols(httpProtocol);
    }
}
