```javascript
import http from 'k6/http';
import { sleep } from 'k6';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
const POLL_INTERVAL_SEC = 0.05;
const MAX_POLLS = 5;

export const options = {
  redirects: 0,
  scenarios: {
    reservation: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
};

let csrfToken = '';
let currentCartId = null;
let currentUser = '';

function extractCsrf(html) {
  const inputRegex = /<\s*input[^>]*>/gi;
  let m;
  while ((m = inputRegex.exec(html)) !== null) {
    const tag = m[0];
    if (/(?:^|\s)name\s*=\s*["']csrf["']/i.test(tag)) {
      const valMatch = tag.match(/value\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'`>]+))/i);
      return valMatch ? (valMatch[1] || valMatch[2] || valMatch[3] || '') : '';
    }
  }
  return null;
}

function json(res) {
  try {
    return res.json();
  } catch (e) {
    throw new Error(`non-JSON response ${res.status}: ${res.body}`);
  }
}

function ensureStatus(res, expected, message) {
  if (!expected.includes(res.status)) {
    throw new Error(`${message}: expected ${expected} got ${res.status} body=${res.body}`);
  }
}

function freshLogin() {
  let formRes = http.get(`${BASE}/v2/login-form`);
  ensureStatus(formRes, [200], 'login form');
  let loginCsrf = extractCsrf(formRes.body);
  if (!loginCsrf) throw new Error('login csrf not found');

  let loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({
    username: currentUser,
    password: 'bench',
    csrf: loginCsrf,
  }), {headers: {'Content-Type': 'application/json'}});

  if (loginRes.status === 302) {
    let loc = loginRes.headers['Location'];
    if (!loc) throw new Error('login 302 without Location');
    if (!loc.startsWith('http')) loc = BASE + (loc.startsWith('/') ? loc : '/' + loc);
    loginRes = http.get(loc);
  }

  ensureStatus(loginRes, [200, 201], 'login');
  let payload = json(loginRes);
  if (payload && payload.csrf) {
    csrfToken = payload.csrf;
  } else {
    throw new Error('login did not return csrf');
  }
}

function renewSession() {
  let res = http.post(`${BASE}/v2/session/renew`, '{}', {headers: {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrfToken,
  }});
  if (res.status === 200) {
    let payload = json(res);
    if (payload && payload.csrf) csrfToken = payload.csrf;
    return true;
  }
  return false;
}

function recoverCart() {
  if (!currentCartId) return;
  let res = http.post(`${BASE}/v2/carts/${currentCartId}/recover`, '{}', {headers: {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrfToken,
  }});
  if (res.status === 200 || res.status === 201) {
    let payload = json(res);
    if (payload && payload.csrf) csrfToken = payload.csrf;
  }
}

function sendRequest(method, url, body, headers = {}) {
  const isMutation = method !== 'GET' && method !== 'HEAD';
  const reqHeaders = Object.assign({}, headers);
  if (body && typeof body === 'string' && !reqHeaders['Content-Type']) {
    reqHeaders['Content-Type'] = 'application/json';
  }
  if (isMutation) {
    reqHeaders['X-CSRF-Token'] = csrfToken;
  }

  let res = http.request(method, url, body, {headers: reqHeaders});

  if (res.status === 401) {
    let error = null;
    try { error = res.json().error; } catch (e) {}

    if (error === 'denied') {
      throw new Error('401 denied');
    }

    if (error === 'expired') {
      if (!renewSession()) {
        freshLogin();
      }
      if (currentCartId) recoverCart();
      if (isMutation) reqHeaders['X-CSRF-Token'] = csrfToken;
      res = http.request(method, url, body, {headers: reqHeaders});
    } else if (error === 'session') {
      freshLogin();
      if (currentCartId) recoverCart();
      if (isMutation) reqHeaders['X-CSRF-Token'] = csrfToken;
      res = http.request(method, url, body, {headers: reqHeaders});
    } else {
      throw new Error(`401 unknown: ${res.body}`);
    }
  }

  return res;
}

function getCatalogProduct() {
  let res = sendRequest('GET', `${BASE}/v2/catalog`, null, {});
  ensureStatus(res, [200], 'catalog');
  let payload = json(res);
  let products = (payload.data && payload.data.products) || [];

  if (products.length === 0) {
    let next = '/v2/catalog/page';
    for (let i = 0; i < 3 && products.length === 0; i++) {
      let pageUrl = BASE + (next.startsWith('/') ? next : '/' + next);
      res = sendRequest('GET', pageUrl, null, {});
      ensureStatus(res, [200], 'catalog page');
      payload = json(res);

      let product = payload.data;
      if (product && product.id) {
        products = [product];
      } else if (payload.data && payload.data.products) {
        products = payload.data.products;
      }

      next = payload.next;
      if (!next) break;
    }
  }

  if (!products.length) throw new Error('no products');
  let product = products[0];
  if (!product.variants || !product.variants.length) throw new Error('no variants');
  let variant = product.variants.find(v => v.in_stock);
  if (!variant) throw new Error('no in-stock variant');

  return { product_id: product.id, variant_id: variant.id };
}

function getEtag(res) {
  return res.headers['ETag'] || res.headers['etag'] || res.headers['Etag'] || null;
}

function reReadCart(cartId) {
  let res = sendRequest('GET', `${BASE}/v2/carts/${cartId}`, null, {});
  ensureStatus(res, [200], 'get cart');
  let payload = json(res);
  if (payload && payload.csrf) csrfToken = payload.csrf;
  return { etag: getEtag(res), payload: payload };
}

function patchCart(cartId, quantity, etag) {
  const body = JSON.stringify({quantity: quantity});
  let headers = {'Content-Type': 'application/json'};
  if (etag) headers['If-Match'] = etag;

  let res = sendRequest('PATCH', `${BASE}/v2/carts/${cartId}`, body, headers);

  if (res.status === 412) {
    let read = reReadCart(cartId);
    etag = read.etag;
    if (!etag) throw new Error('no etag after 412');
    res = sendRequest('PATCH', `${BASE}/v2/carts/${cartId}`, body, {
      'Content-Type': 'application/json',
      'If-Match': etag,
    });
  }

  ensureStatus(res, [200, 201], 'patch cart');
  let payload = json(res);
  if (payload && payload.csrf) csrfToken = payload.csrf;

  let read = reReadCart(cartId);
  return read.etag || getEtag(res) || etag;
}

function pollReservation(cartId) {
  let reserveRes = sendRequest('POST', `${BASE}/v2/reservations`, JSON.stringify({cart_id: cartId}), {
    'Content-Type': 'application/json',
  });
  ensureStatus(reserveRes, [202], 'create reservation');

  let reservePayload = json(reserveRes);
  if (reservePayload && reservePayload.csrf) csrfToken = reservePayload.csrf;

  let statusUrl = reservePayload.status_url;
  if (!statusUrl) throw new Error('no reservation status_url');
  if (!statusUrl.startsWith('http')) {
    statusUrl = BASE + (statusUrl.startsWith('/') ? statusUrl : '/' + statusUrl);
  }

  let reservationId = null;
  for (let i = 0; i < MAX_POLLS; i++) {
    sleep(POLL_INTERVAL_SEC);
    let statusRes = sendRequest('GET', statusUrl, null, {});
    ensureStatus(statusRes, [200], 'reservation status');
    let statusPayload = json(statusRes);
    if (statusPayload && statusPayload.csrf) csrfToken = statusPayload.csrf;

    if (statusPayload && statusPayload.status === 'ready' && statusPayload.reservation_id) {
      reservationId = statusPayload.reservation_id;
      break;
    }
    if (statusPayload && statusPayload.status === 'failed') {
      throw new Error('reservation failed');
    }
  }

  if (!reservationId) throw new Error('reservation not ready after max polls');
  return reservationId;
}

function placeOrder(cartId, reservationId, etag) {
  const body = JSON.stringify({cart_id: cartId, reservation_id: reservationId});
  const orderKey = `order-${cartId}`;

  let headers = {
    'Content-Type': 'application/json',
    'Idempotency-Key': orderKey,
  };
  if (etag) headers['If-Match'] = etag;

  let res = sendRequest('POST', `${BASE}/v2/orders`, body, headers);

  if (res.status === 412) {
    let read = reReadCart(cartId);
    etag = read.etag;
    if (!etag) throw new Error('no etag for order retry');
    res = sendRequest('POST', `${BASE}/v2/orders`, body, {
      'Content-Type': 'application/json',
      'Idempotency-Key': orderKey,
      'If-Match': etag,
    });
  }

  let payload = json(res);
  if (payload && payload.csrf) csrfToken = payload.csrf;

  if (res.status === 201 && payload && payload.accepted === true) return payload;
  if (res.status === 200 && payload && payload.accepted === true) return payload;
  if (res.status === 200 && payload && payload.accepted === false) throw new Error('order accepted:false');
  throw new Error(`order status ${res.status}`);
}

export default function () {
  currentCartId = null;
  csrfToken = '';
  currentUser = `bench-${__VU}`;

  freshLogin();

  const catalog = getCatalogProduct();
  let cartRes = sendRequest('POST', `${BASE}/v2/carts`, JSON.stringify({
    product_id: catalog.product_id,
    variant_id: catalog.variant_id,
  }), {'Content-Type': 'application/json'});

  ensureStatus(cartRes, [201], 'create cart');
  let cartPayload = json(cartRes);
  if (cartPayload && cartPayload.csrf) csrfToken = cartPayload.csrf;
  if (!cartPayload || !cartPayload.id) throw new Error('cart id missing');

  currentCartId = cartPayload.id;

  let cartEtag = getEtag(cartRes);
  if (!cartEtag) {
    let read = reReadCart(currentCartId);
    cartEtag = read.etag;
  }

  cartEtag = patchCart(currentCartId, 1, cartEtag);
  const reservationId = pollReservation(currentCartId);
  const orderPayload = placeOrder(currentCartId, reservationId, cartEtag);
  if (orderPayload && orderPayload.csrf) csrfToken = orderPayload.csrf;
}
