import time
import re
import uuid
from html import unescape

from locust import HttpUser, task, constant, StopUser, LoadTestShape


def extract_csrf_from_html(html_text):
    for tag in re.findall(r"<input\b[^>]*>", html_text, re.IGNORECASE):
        if re.search(r"\bname\s*=\s*[\"']csrf[\"']", tag, re.IGNORECASE):
            m = re.search(r"\bvalue\s*=\s*[\"']([^\"']*)[\"']", tag, re.IGNORECASE)
            if not m:
                m = re.search(r"\bvalue\s*=\s*([^\s>]+)", tag, re.IGNORECASE)
            if m:
                return unescape(m.group(1))
    return None


class BaseReservationUser(HttpUser):
    abstract = True
    wait_time = constant(0)

    username = None
    job_polls = 2
    poll_interval = 0.05
    iterations = 2
    html_layout = 0
    reverse_catalog = False

    def on_start(self):
        self.csrf = ""
        self.cart_etag = None
        self.idem_key = None
        self.iteration_count = 0

    @task
    def perform(self):
        if self.iteration_count >= self.iterations:
            raise StopUser()
        self.iteration_count += 1
        self.cart_etag = None
        self.idem_key = None
        self.run_journey()

    def _safe_json(self, resp):
        try:
            return resp.json()
        except Exception:
            return {}

    def _update_csrf_from_response(self, resp):
        data = self._safe_json(resp)
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]

    def _recover_cart(self, cart_id):
        if not cart_id:
            return True
        resp = self.client.post(
            f"/v2/carts/{cart_id}/recover",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            name="/v2/carts/id/recover",
            allow_redirects=False,
            catch_response=True,
        )
        self._update_csrf_from_response(resp)
        if resp.status_code not in (200, 201, 204):
            resp.failure(f"cart recover status {resp.status_code}")
            return False
        etag = resp.headers.get("ETag")
        if etag:
            self.cart_etag = etag
        return True

    def _renew_session(self, cart_id=None):
        if not self.csrf:
            return False
        resp = self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            name="/v2/session/renew",
            allow_redirects=False,
            catch_response=True,
        )
        self._update_csrf_from_response(resp)
        if resp.status_code != 200:
            resp.failure(f"session renew status {resp.status_code}")
            return False
        if cart_id:
            return self._recover_cart(cart_id)
        return True

    def login(self):
        resp = self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            allow_redirects=False,
            catch_response=True,
        )
        if resp.status_code != 200:
            resp.failure(f"login-form status {resp.status_code}")
            return False

        self.csrf = extract_csrf_from_html(resp.text)
        if not self.csrf:
            resp.failure("login-form missing csrf")
            return False

        resp = self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": self.csrf},
            headers={"X-CSRF-Token": self.csrf},
            name="/v2/login",
            allow_redirects=False,
            catch_response=True,
        )
        self._update_csrf_from_response(resp)

        if resp.status_code in (301, 302, 303, 307, 308):
            loc = resp.headers.get("Location")
            if not loc:
                resp.failure("login redirect missing Location")
                return False

            resp2 = self.client.get(
                loc,
                name="/v2/login/redirect",
                allow_redirects=False,
                catch_response=True,
            )
            self._update_csrf_from_response(resp2)
            if resp2.status_code != 200:
                resp2.failure(f"login redirect GET status {resp2.status_code}")
                return False
        elif resp.status_code != 200:
            resp.failure(f"login status {resp.status_code}")
