        self.idem_key = None

    @task
    def perform(self):
        if self.iteration_count >= self.iterations:
            raise StopUser()
        self.iteration_count += 1
        self.cart_etag = None
        self.idem_key = None
        self.run_journey()

    def _safe_json(self, resp):
        try:
            return resp.json()
        except Exception:
            return {}

    def _update_csrf_from_response(self, resp):
        data = self._safe_json(resp)
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]

    def _recover_cart(self, cart_id):
        if not cart_id:
            return True

        resp = self.client.post(
            f"/v2/carts/{cart_id}/recover",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            name="/v2/carts/id/recover",
            allow_redirects=False,
            catch_response=True,
        )
        self._update_csrf_from_response(resp)

        if resp.status_code not in (200, 201, 204):
            resp.failure(f"cart recover status {resp.status_code}")
            return False

        etag = resp.headers.get("ETag")
        if etag:
            self.cart_etag = etag
        return True

    def _renew_session(self, cart_id=None):
        if not self.csrf:
            return False

        resp = self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            name="/v2/session/renew",
            allow_redirects=False,
            catch_response=True,
        )
        self._update_csrf_from_response(resp)

        if resp.status_code != 200:
            resp.failure(f"session renew status {resp.status_code}")
            return False

        if cart_id:
            return self._recover_cart(cart_id)
        return True

    def login(self):
        resp = self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            allow_redirects=False,
            catch_response=True,
        )
        if resp.status_code != 200:
            resp.failure(f"login-form status {resp.status_code}")
            return False

        self.csrf = _extract_csrf(resp.text)
        if not self.csrf:
            resp.failure("login-form missing csrf")
            return False

        resp = self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": self.csrf},
            headers={"X-CSRF-Token": self.csrf},
            name="/v2/login",
            allow_redirects=False,
            catch_response=True,
        )
        self._update_csrf_from_response(resp)

        if resp.status_code in (301, 302, 303, 307, 308):
            loc = resp.headers.get("Location")
            if not loc:
                resp.failure("login redirect missing Location")
                return False

            resp2 = self.client.get(
                loc,
                name="/v2/login/redirect",
                allow_redirects=False,
                catch_response=True,
            )
            self._update_csrf_from_response(resp2)

            if resp2.status_code != 200:
                resp2.failure(f"login redirect GET status {resp2.status_code}")
                return False
        elif resp.status_code != 200:
            resp.failure(f"login status {resp.status_code}")
            return False

        return True

    def _relogin_session(self, cart_id=None):
        if not self.login():
            return False
        if cart_id:
            return self._recover_cart(cart_id)
        return True

    def _call_mutation(
        self,
        method,
        url,
        payload,
        name,
        cart_id=None,
        idem_key=None,
        use_if_match=False,
        retried=False,
    ):
        headers = {"X-CSRF-Token": self.csrf}
        if idem_key:
            headers["Idempotency-Key"] = idem_key
        if use_if_match and self.cart_etag:
            headers["If-Match"] = self.cart_etag

        if method == "POST":
            resp = self.client.post(
                url,
                json=payload,
                headers=headers,
                name=name,
                allow_redirects=False,
                catch_response=True,
            )
        elif method == "PATCH":
            resp = self.client.patch(
                url,
                json=payload,
                headers=headers,
                name=name,
                allow_redirects=False,
                catch_response=True,
            )
        else:
            raise ValueError(f"unsupported method {method}")

        self._update_csrf_from_response(resp)

        if resp.status_code == 401 and not retried:
            data = self._safe_json(resp)
            error = data.get("error") if isinstance(data, dict) else None

            if error == "expired":
                if not self._renew_session(cart_id):
                    resp.failure("session renew failed")
                    return resp
                resp.success()
                return self._call_mutation(
                    method,
                    url,
                    payload,
                    name,
                    cart_id=cart_id,
                    idem_key=idem_key,
                    use_if_match=use_if_match,
                    retried=True,
                )

            if error == "session":
                if not self._relogin_session(cart_id):
                    resp.failure("session re-login failed")
                    return resp
                resp.success()
                return self._call_mutation(
                    method,
                    url,
                    payload,
                    name,
                    cart_id=cart_id,
                    idem_key=idem_key,
                    use_if_match=use_if_match,
                    retried=True,
                )

            if error == "denied":
                resp.failure("401 denied")
                return resp

            resp.failure(f"unexpected 401 error={error}")
            return resp

        return resp

    def _find_variant_in_product(self, product):
        if not isinstance(product, dict):
            return None
        product_id = product.get("id")
        if not product_id:
            return None
        for variant in product.get("variants", []) or []:
            if isinstance(variant, dict) and variant.get("in_stock"):
                variant_id = variant.get("id")
                if variant_id:
                    return product_id, variant_id
        return None

    def _find_variant_in_products(self, products):
        if not isinstance(products, list):
            return None
        for product in products:
            pair = self._find_variant_in_product(product)
            if pair:
                return pair
        return None

    def get_product(self):
        resp = self.client.get(
            "/v2/catalog",
            name="/v2/catalog",
            allow_redirects=False,
            catch_response=True,
