        data = self._safe_json(resp)
        data_block = data.get("data") if isinstance(data, dict) else None
        products = data_block.get("products", []) if isinstance(data_block, dict) else []
        pair = self._find_variant_in_products(products)
        if pair:
            return pair

        page_path = "/v2/catalog/page"
        last_resp = None

        for _ in range(3):
            resp = self.client.get(
                page_path,
                name="/v2/catalog/page",
                allow_redirects=False,
                catch_response=True,
            )
            last_resp = resp

            if resp.status_code != 200:
                resp.failure(f"catalog page status {resp.status_code}")
                return None

            data = self._safe_json(resp)
            product = None
            if isinstance(data.get("data"), dict):
                product = data["data"].get("product")
            if not product:
                product = data.get("product")

            pair = self._find_variant_in_product(product)
            if pair:
                return pair

            next_url = None
            if isinstance(data.get("data"), dict):
                next_url = data["data"].get("next")
            if not next_url:
                next_url = data.get("next")

            if next_url:
                if next_url.startswith("/"):
                    page_path = next_url
                elif next_url.startswith("http"):
