    def create_cart(self, product_pair):
        payload = {"product_id": product_pair[0], "variant_id": product_pair[1]}
        resp = self._call_mutation("POST", "/v2/carts", payload, "/v2/carts")

        if resp.status_code != 201:
            resp.failure(f"cart creation status {resp.status_code}")
            return None

        data = self._safe_json(resp)
        cart_id = data.get("id")
        if not cart_id:
