    def patch_cart(self, cart_id):
        resp = self._call_mutation(
            "PATCH",
            f"/v2/carts/{cart_id}",
            {"quantity": 1},
            "/v2/carts/id",
            cart_id=cart_id,
            use_if_match=True,
        )

        if resp.status_code == 412:
            get_resp = self.client.get(
                f"/v2/carts/{cart_id}",
                name="/v2/carts/id",
                allow_redirects=False,
                catch_response=True,
            )
            self._update_csrf_from_response(get_resp)

            if get_resp.status_code != 200:
                get_resp.failure(f"cart re-read status {get_resp.status_code}")
                return False

            self.cart_etag = get_resp.headers.get("ETag", self.cart_etag)

            resp = self._call_mutation(
                "PATCH",
                f"/v2/carts/{cart_id}",
                {"quantity": 1},
                "/v2/carts/id",
                cart_id=cart_id,
                use_if_match=True,
            )

        if resp.status_code not in (200, 201, 204):
            resp.failure(f"PATCH status {resp.status_code}")
            return False

        etag = resp.headers.get("ETag")
        if etag:
            self.cart_etag = etag
        return True

    def create_reservation(self, cart_id):
        resp = self._call_mutation(
            "POST",
            "/v2/reservations",
            {"cart_id": cart_id},
            "/v2/reservations",
            cart_id=cart_id,
        )

        if resp.status_code != 202:
            resp.failure(f"reservation create status {resp.status_code}")
            return None

        data = self._safe_json(resp)
        status_url = data.get("status_url")
        if not status_url:
            resp.failure("reservation missing status_url")
            return None

        poll_count = 0
        while poll_count < self.job_polls:
            poll_count += 1
            if poll_count > 1:
                time.sleep(max(self.poll_interval, 0.05))

            status_resp = self.client.get(
                status_url,
                name="/v2/reservations/status",
                allow_redirects=False,
                catch_response=True,
            )
            self._update_csrf_from_response(status_resp)

            if status_resp.status_code != 200:
                status_resp.failure(f"reservation status HTTP {status_resp.status_code}")
                return None

            data = self._safe_json(status_resp)
            status = data.get("status")

            if status == "ready":
                reservation_id = data.get("reservation_id")
                if not reservation_id:
                    status_resp.failure("ready status missing reservation_id")
                    return None
                return reservation_id

            if status == "failed":
                status_resp.failure("reservation job failed")
                return None

            if status == "pending":
                if poll_count >= self.job_polls:
                    status_resp.failure(
