        if resp.status_code == 200:
            data = self._safe_json(resp)
            if data.get("accepted") is True:
                return True
            resp.failure("200 order accepted:false")
            return False

        resp.failure(f"order status {resp.status_code}")
        return False

    def do_work(self):
        retries_429 = 0
        recovered_401 = False

        while True:
            resp = self.client.post(
                "/v2/work",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                name="/v2/work",
                allow_redirects=False,
                catch_response=True,
            )
            self._update_csrf_from_response(resp)

            if resp.status_code == 429:
                if retries_429 >= 4:
