                        resp.failure("session renew failed for /v2/work")
                        return False
                    resp.success()
                    recovered_401 = True
                    continue

                if error == "denied":
                    resp.failure("401 denied")
                    return False

                resp.failure(f"unexpected 401 error={error}")
                return False

            if resp.status_code != 200:
                resp.failure(f"/v2/work status {resp.status_code}")
                return False

            data = self._safe_json(resp)
            if data.get("ok") is True:
                return True

            resp.failure("/v2/work ok != true")
            return False

    def run_journey(self):
        if not self.login():
            return

        product_pair = self.get_product()
        if not product_pair:
            return

        cart_id = self.create_cart(product_pair)
        if not cart_id:
            return

        if not self.patch_cart(cart_id):
            return

