import http from 'k6/http';
import { check } from 'k6';

const baseUrl = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
};

const session = {
  csrf: 'MISSING',
  cartId: 'MISSING',
  etag: 'MISSING',
  hasCart: false,
  grant: 'MISSING',
};

function clearCookies() {
  try {
    http.cookieJar().clear(baseUrl);
  } catch (e) {
  }
}

function resolveUrl(path) {
  if (/^https?:\/\//i.test(path)) return path;
  return path.startsWith('/') ? baseUrl + path : `${baseUrl}/${path}`;
}

function makeRequest(method, path, body, headers = {}) {
  const params = {
    headers: Object.assign({}, headers),
    redirects: 0,
    timeout: '5s',
  };
  const url = resolveUrl(path);
  if (method === 'GET') return http.get(url, params);
  if (method === 'POST') return http.post(url, body ? JSON.stringify(body) : null, params);
  return http.request(method, url, body ? JSON.stringify(body) : null, params);
}

function getJson(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function parseError(res) {
  try {
    const m = res.body.match(/"error"\s*:\s*"(expired|session|denied)"/);
    return m ? m[1] : null;
  } catch (e) {
    return null;
  }
}

function extractCsrfFromHtml(html) {
  const inputRe = /<input\b[^>]*>/gi;
  let match;
  while ((match = inputRe.exec(html)) !== null) {
    const tag = match[0];
    if (/(?:^|\s)name\s*=\s*(?:"csrf"|'csrf'|csrf)(?=\s|/?>)/i.test(tag)) {
      const valueMatch = tag.match(/(?:^|\s)value\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+?)(?=\s|/?>))/i);
      if (valueMatch) {
        if (valueMatch[1] !== undefined) return valueMatch[1];
        if (valueMatch[2] !== undefined) return valueMatch[2];
        if (valueMatch[3] !== undefined) return valueMatch[3];
      }
      return '';
    }
  }
  return null;
}

function getLoginForm() {
  const res = makeRequest('GET', '/v2/login-form', null);
  check(res, { 'login form status': (r) => r.status === 200 });
  const csrf = extractCsrfFromHtml(res.body);
  if (csrf === null) {
    throw new Error('login csrf not found');
  }
  return csrf;
}

function postLogin(formCsrf) {
  const username = `bench-${__VU}`;
  const payload = {
    username: username,
    password: 'bench',
    csrf: formCsrf,
  };
  const res = makeRequest('POST', '/v2/login', payload, { 'Content-Type': 'application/json' });
  check(res, {
    'login status': (r) => r.status === 200 || r.status === 302,
    'login csrf body': (r) => /"csrf"\s*:/.test(r.body),
  });

  const loginJson = getJson(res);
  if (loginJson && loginJson.csrf) session.csrf = loginJson.csrf;

  const location = res.headers['Location'] || res.headers['location'];
  if (location) {
    const cleanLocation = String(location).trim();
    const locRes = makeRequest('GET', cleanLocation, null, { 'Content-Type': 'application/json' });
    check(locRes, { 'login redirect status': (r) => r.status === 200 });
    const json = getJson(locRes);
    if (json) {
      if (json.csrf) session.csrf = json.csrf;
      if (json.grant_id) session.grant = json.grant_id;
    }
  }

  if (!session.csrf || session.csrf === 'MISSING') {
    throw new Error('login did not return csrf');
  }
}

function renewSession() {
  const res = makeRequest('POST', '/v2/session/renew', {}, {
    'Content-Type': 'application/json',
    'X-CSRF-Token': session.csrf,
  });
  const json = getJson(res);
  if (res.status >= 200 && res.status < 400) {
    if (json && json.csrf) session.csrf = json.csrf;
    return true;
  }
  return false;
}

function freshLoginSession() {
  try {
    const formCsrf = getLoginForm();
    postLogin(formCsrf);
    return session.csrf !== 'MISSING';
  } catch (e) {
    return false;
  }
}

function recoverCart() {
  if (!session.hasCart || session.cartId === 'MISSING') return false;
  const res = makeRequest('POST', `/v2/carts/${session.cartId}/recover`, {}, {
    'Content-Type': 'application/json',
    'X-CSRF-Token': session.csrf,
  });
  const json = getJson(res);
  if (res.status >= 200 && res.status < 400) {
    if (json && json.csrf) session.csrf = json.csrf;
    const etagHeader = res.headers['ETag'] || res.headers['etag'];
    if (etagHeader && String(etagHeader).trim()) session.etag = String(etagHeader).trim();
    return true;
  }
  return false;
}

function authRequest(method, path, body, extraHeaders = {}) {
  function buildHeaders() {
    const headers = typeof extraHeaders === 'function' ? extraHeaders() : extraHeaders;
    return Object.assign({
      'Content-Type': 'application/json',
      'X-CSRF-Token': session.csrf,
    }, headers);
  }

  let res = makeRequest(method, path, body, buildHeaders());

  if (res.status === 401) {
    const err = parseError(res);
    if (err === 'expired') {
      if (renewSession()) {
        if (session.hasCart && session.cartId !== 'MISSING') recoverCart();
        res = makeRequest(method, path, body, buildHeaders());
      }
    } else if (err === 'session') {
      if (freshLoginSession()) {
        if (session.hasCart && session.cartId !== 'MISSING') recoverCart();
        res = makeRequest(method, path, body, buildHeaders());
      }
    } else if (err === 'denied') {
      check(null, { 'denied assertion': () => false });
    }
  }

  return res;
}

function chooseProduct() {
  const res = makeRequest('GET', '/v2/catalog', null);
  check(res, { 'catalog status': (r) => r.status === 200 });
  const json = getJson(res);
  if (!json || !json.data || !json.data.products || json.data.products.length === 0) {
    throw new Error('catalog missing products');
  }
  const chosen = json.data.products.find(p => p.variants && p.variants.length > 0 && p.variants[0].in_stock === true);
  if (!chosen) {
    throw new Error('no in-stock product');
  }
  return {
    product: chosen.id,
    variant: chosen.variants[0].id,
  };
}

function createCart(productId, variantId) {
  const payload = {
    product_id: String(productId),
    variant_id: String(variantId),
  };
  if (session.grant !== 'MISSING') {
    payload.grant_id = String(session.grant);
  }

  const res = authRequest('POST', '/v2/carts', payload);
  check(res, { 'cart status': (r) => r.status === 201 });
  check(res.body, { 'cart id present': (b) => /"id"\s*:\s*"cart-/.test(b) });

  const json = getJson(res);
  if (!json || !json.id) {
    throw new Error('cart id missing');
  }
  session.cartId = json.id;
  session.hasCart = true;
  if (json.csrf) session.csrf = json.csrf;

  const etagHeader = res.headers['ETag'] || res.headers['etag'];
  if (etagHeader && String(etagHeader).trim()) session.etag = String(etagHeader).trim();
}

function placeOrder() {
  const payload = {
    cart_id: String(session.cartId),
  };

  function buildOrderHeaders() {
    const headers = {
      'Idempotency-Key': session.cartId,
    };
    if (session.etag !== 'MISSING') {
      headers['If-Match'] = session.etag;
    }
    return headers;
  }

  const res = authRequest('POST', '/v2/orders', payload, buildOrderHeaders);
  const json = getJson(res);
  const accepted = res.status === 201 && json && json.accepted === true;
  check(res, { 'order accepted': () => accepted });
  if (!accepted) {
    throw new Error('order not accepted');
  }
  if (json && json.csrf) session.csrf = json.csrf;
}

export default function () {
  session.csrf = 'MISSING';
  session.cartId = 'MISSING';
  session.etag = 'MISSING';
  session.hasCart = false;
  session.grant = 'MISSING';

  clearCookies();

  const formCsrf = getLoginForm();
  postLogin(formCsrf);

  const { product, variant } = chooseProduct();
  createCart(product, variant);
  placeOrder();
}

