import os
import re
from locust import HttpUser, task, LoadTestShape, constant
from locust.exception import StopUser

BASE_URL = os.environ["BASE_URL"]

spawned_users = 0
finished_users = 0


def _json_or_none(resp):
    try:
        return resp.json()
    except Exception:
        return None


def _extract_error(resp):
    if not resp.text:
        return None
    m = re.search(r'"error"\s*:\s*"(expired|session|denied|)"', resp.text)
    if m:
        return m.group(1) or None
    return None


def _extract_csrf_from_html(html):
    for m in re.finditer(r'<input\b[^>]*>', html, re.I | re.S):
        tag = m.group(0)
        name_m = re.search(r'\bname\s*=\s*(["\'])(.*?)\1', tag, re.I)
        if not name_m or name_m.group(2) != 'csrf':
            continue
        value_m = re.search(r'\bvalue\s*=\s*(["\'])(.*?)\1', tag, re.I)
        if value_m:
            return value_m.group(2)
    return None


class BaseShopUser(HttpUser):
    abstract = True
    host = BASE_URL
    wait_time = constant(0)

    username = "bench"
    html_layout = 0
    reverse_catalog = False

    def on_start(self):
        global spawned_users
        spawned_users += 1

    def _start_journey(self):
        self.client.cookies.clear()
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.product_id = None
        self.variant_id = None
        self.reservation_id = None

    def _update_csrf_from_resp(self, resp):
        data = _json_or_none(resp)
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]

    def _make_headers(self, include_csrf=True, include_etag=False, idem=None):
        headers = {}
        if include_csrf and self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        if include_etag and self.etag:
            headers["If-Match"] = self.etag
        if idem:
            headers["Idempotency-Key"] = idem
        return headers

    def _get_login_form_csrf(self):
        with self.client.get(
            "/v2/login-form",
            headers={"Content-Type": "application/json"},
            allow_redirects=False,
            timeout=3,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login-form unexpected status {resp.status_code}: {resp.text[:200]}")
                return None
            csrf = _extract_csrf_from_html(resp.text)
            if not csrf:
                resp.failure("login-form missing csrf input")
                return None
            return csrf

    def _do_login(self, form_csrf):
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": form_csrf},
            headers={"Content-Type": "application/json"},
            allow_redirects=False,
            timeout=3,
            catch_response=True,
        ) as resp:
            self._update_csrf_from_resp(resp)

            if resp.status_code not in (200, 302):
                resp.failure(f"login unexpected status {resp.status_code}: {resp.text[:200]}")
                return False

            if resp.status_code == 200 and not re.search(r'"csrf"\s*:', resp.text):
                resp.failure("login response missing csrf")
                return False

            if resp.headers.get("Location"):
                loc = resp.headers["Location"]
                with self.client.get(
                    loc,
                    headers=self._make_headers(include_csrf=True),
                    allow_redirects=False,
                    timeout=3,
                    catch_response=True,
                ) as r2:
                    self._update_csrf_from_resp(r2)
                    if r2.status_code != 200:
                        r2.failure(f"login redirect GET unexpected status {r2.status_code}: {r2.text[:200]}")
                        return False
                    data = _json_or_none(r2)
                    if isinstance(data, dict) and data.get("grant_id"):
                        self.grant_id = data["grant_id"]

            if not self.csrf:
                data = _json_or_none(resp)
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]

            if not self.csrf:
                resp.failure("login did not yield csrf")
                return False

            return True

    def _renew_session(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=self._make_headers(include_csrf=True),
            allow_redirects=False,
            timeout=3,
            catch_response=True,
        ) as resp:
            self._update_csrf_from_resp(resp)
            if resp.status_code in (200, 201):
                return True
            resp.failure(f"renew session unexpected status {resp.status_code}: {resp.text[:200]}")
            return False

    def _fresh_login_for_recovery(self):
        self.client.cookies.clear()
        self.csrf = None
        form_csrf = self._get_login_form_csrf()
        if not form_csrf:
            return False
        return self._do_login(form_csrf)

    def _recover_cart(self):
        if not self.cart_id:
            return True
        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers=self._make_headers(include_csrf=True),
            allow_redirects=False,
            timeout=3,
            catch_response=True,
        ) as resp:
            self._update_csrf_from_resp(resp)
            if resp.headers.get("ETag"):
                self.etag = resp.headers["ETag"]
            if resp.status_code in (200, 201):
                return True
            resp.failure(f"recover cart unexpected status {resp.status_code}: {resp.text[:200]}")
            return False

    def _request(
        self,
        method,
        url,
        expected_statuses=(200,),
        operation="request",
        json_body=None,
        headers=None,
        include_csrf=True,
        include_etag=False,
        idem=None,
    ):
        base_headers = {}
        if headers:
            base_headers.update(headers)
        if json_body is not None:
            base_headers.setdefault("Content-Type", "application/json")

        for attempt in range(2):
            request_headers = dict(base_headers)
            if include_csrf and self.csrf:
                request_headers.setdefault("X-CSRF-Token", self.csrf)
            if include_etag and self.etag:
                request_headers.setdefault("If-Match", self.etag)
            if idem:
                request_headers.setdefault("Idempotency-Key", idem)

            with self.client.request(
                method,
                url,
                headers=request_headers,
                json=json_body,
                allow_redirects=False,
                timeout=3,
                catch_response=True,
            ) as resp:
                self._update_csrf_from_resp(resp)
                if resp.headers.get("ETag"):
                    self.etag = resp.headers["ETag"]

                if resp.status_code in expected_statuses:
                    return resp

                if resp.status_code == 401:
                    err = _extract_error(resp)
                    if attempt == 0 and err in ("expired", "session"):
                        if err == "expired":
                            if not self._renew_session():
                                resp.failure("401 expired: renew failed")
                                return resp
                            if self.cart_id and not self._recover_cart():
                                resp.failure("401 expired: recover cart failed")
                                return resp
                        else:
                            if not self._fresh_login_for_recovery():
                                resp.failure("401 session: fresh login failed")
                                return resp
                            if self.cart_id and not self._recover_cart():
                                resp.failure("401 session: recover cart failed")
                                return resp
                        continue

                    resp.failure(f"{operation} 401 {err or 'unknown'}: {resp.text[:200]}")
                    return resp

                resp.failure(f"{operation} unexpected status {resp.status_code}: {resp.text[:200]}")
                return resp

        return None

    def _extract_products(self, resp):
        data = _json_or_none(resp)
        if not isinstance(data, dict):
            return []
        data_obj = data.get("data", {})
        if not isinstance(data_obj, dict):
            return []
        products = data_obj.get("products", [])
        if not isinstance(products, list):
            return []
        if self.reverse_catalog:
            products = list(reversed(products))
        return products

    def _pick_product(self, products):
        for prod in products:
            if not isinstance(prod, dict):
                continue
            variants = prod.get("variants", [])
            if (
                isinstance(variants, list)
                and variants
                and isinstance(variants[0], dict)
                and variants[0].get("in_stock") is True
            ):
                return prod.get("id"), variants[0].get("id")
        return None, None

    def _perform_journey(self):
        self._start_journey()

        form_csrf = self._get_login_form_csrf()
        if not form_csrf:
            return
        if not self._do_login(form_csrf):
            return

        catalog_resp = self._request(
            "GET",
            "/v2/catalog",
            expected_statuses=(200,),
            operation="catalog",
        )
        if not catalog_resp or catalog_resp.status_code != 200:
            return

        products = self._extract_products(catalog_resp)
        product_id, variant_id = self._pick_product(products)
        if product_id is None or variant_id is None:
            catalog_resp.failure("catalog missing in-stock product")
            return

        self.product_id = product_id
        self.variant_id = variant_id

        cart_payload = {"product_id": self.product_id, "variant_id": self.variant_id}
        if self.grant_id:
            cart_payload["grant_id"] = self.grant_id

        cart_resp = self._request(
            "POST",
            "/v2/carts",
            json_body=cart_payload,
            expected_statuses=(201,),
            operation="create cart",
            include_csrf=True,
            headers={"Content-Type": "application/json"},
        )
        if not cart_resp or cart_resp.status_code != 201:
            return

        cart_data = _json_or_none(cart_resp)
        if not isinstance(cart_data, dict) or not cart_data.get("id"):
            cart_resp.failure("create cart missing id")
            return

        self.cart_id = cart_data["id"]
        self.etag = cart_resp.headers.get("ETag") or cart_resp.headers.get("Etag")

        if not re.match(r"^cart-", str(self.cart_id)):
            cart_resp.failure("cart id does not look like cart-*")
            return

        order_resp = self._request(
            "POST",
            "/v2/orders",
            json_body={"cart_id": self.cart_id},
            expected_statuses=(200, 201),
            operation="order",
            include_csrf=True,
            include_etag=True,
            idem=str(self.cart_id),
            headers={"Content-Type": "application/json"},
        )
        if not order_resp:
            return

        if order_resp.status_code == 201:
            data = _json_or_none(order_resp)
            if not isinstance(data, dict) or data.get("accepted") is not True:
                order_resp.failure("order 201 missing accepted:true")
                return
        elif order_resp.status_code == 200:
            data = _json_or_none(order_resp)
            if not (isinstance(data, dict) and data.get("accepted") is True):
                order_resp.failure("order accepted:false")
                return

    @task
    def run_flow(self):
        for _ in range(2):
            try:
                self._perform_journey()
            except Exception:
                pass

        global finished_users
        finished_users += 1
        raise StopUser()


class Variant1ShopUser(BaseShopUser):
    username = "bench-1"
    html_layout = 0
    reverse_catalog = False
    weight = 1


class Variant2ShopUser(BaseShopUser):
    username = "bench-2"
    html_layout = 1
    reverse_catalog = True
    weight = 1


class ShopShape(LoadTestShape):
    def tick(self):
        if spawned_users < 2:
            return (2, 2)

        if finished_users >= 2:
            return None

        runner = getattr(self, "runner", None)
        current = runner.user_count if runner else 0
        return (current, 0)
