import http from 'k6/http';
import { fail } from 'k6';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
const accounts = JSON.parse(open('/fixtures/accounts.json'));

export const options = {
  scenarios: {
    main: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
};

function resolveUrl(url) {
  if (/^https?:\/\//i.test(url)) return url;
  return BASE_URL + (url.startsWith('/') ? url : '/' + url);
}

function parseJsonSafely(text) {
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch (e) {
    return null;
  }
}

function getHeader(res, name) {
  const headers = res.headers || {};
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === name.toLowerCase()) return headers[key];
  }
  return null;
}

function extractETag(res) {
  return getHeader(res, 'ETag');
}

function updateCsrf(res, fallback) {
  const j = parseJsonSafely(res.body);
  if (j && typeof j.csrf === 'string' && j.csrf) return j.csrf;
  return fallback;
}

function extractErrorCode(res) {
  const j = parseJsonSafely(res.body);
  if (j && typeof j.error === 'string') return j.error;
  return null;
}

function extractInputValue(html, name) {
  const inputRe = /<input\b[^>]*>/gi;
  let m;
  while ((m = inputRe.exec(html)) !== null) {
    const tag = m[0];
    const nameMatch = tag.match(/\bname\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!nameMatch) continue;
    const nameValue = nameMatch[1] !== undefined ? nameMatch[1] : (nameMatch[2] !== undefined ? nameMatch[2] : nameMatch[3]);
    if (nameValue !== name) continue;

    const valueMatch = tag.match(/\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!valueMatch) return '';
    return valueMatch[1] !== undefined ? valueMatch[1] : (valueMatch[2] !== undefined ? valueMatch[2] : valueMatch[3]);
  }
  return null;
}

function performLogin(username, password) {
  let res = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  if (res.status !== 200) {
    throw new Error(`GET /v2/login-form unexpected status ${res.status} ${res.body}`);
  }

  const form = extractInputValue(res.body, 'csrf');
  if (form === null || form === undefined) {
    throw new Error('login form missing csrf input');
  }

  res = http.post(`${BASE_URL}/v2/login`, JSON.stringify({ username, password, csrf: form }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });

  if (res.status === 302) {
    const location = getHeader(res, 'Location');
    if (!location) {
      throw new Error('login 302 missing Location header');
    }
    res = http.get(resolveUrl(location), { redirects: 0 });
  }

  if (res.status !== 200 && res.status !== 201 && res.status !== 204) {
    throw new Error(`POST /v2/login unexpected status ${res.status} ${res.body}`);
  }

  const j = parseJsonSafely(res.body);
  const csrf = (j && typeof j.csrf === 'string') ? j.csrf : form;
  const grant = (j && typeof j.grant_id === 'string') ? j.grant_id : null;
  return { csrf, grant };
}

function extractCatalogData(res) {
  const j = parseJsonSafely(res.body);
  if (!j) return { data: null, next: null };
  const data = j.data || j;
  const next = j.next || (j.data && j.data.next) || null;
  return { data, next };
}

function findInStockProduct(data) {
  if (!data) return null;
  let products = null;

  if (Array.isArray(data.products)) {
    products = data.products;
  } else if (data.product) {
    products = [data.product];
  } else if (Array.isArray(data.variants)) {
    products = [data];
  } else if (Array.isArray(data)) {
    products = data;
  }

  if (!products) return null;

  for (const p of products) {
    if (!p || p.id === undefined || p.id === null) continue;
    const variants = Array.isArray(p.variants) ? p.variants : [];
    const variant = variants.find((v) => v && v.in_stock === true && v.id !== undefined && v.id !== null);
    if (variant) {
      return { productId: p.id, variantId: variant.id };
    }
  }
  return null;
}

function freshLoginRecover(cartId, etag, username, password) {
  const login = performLogin(username, password);
  let newCsrf = login.csrf;
  let newEtag = etag;
  const grant = login.grant;

  if (cartId) {
    const recRes = http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, '{}', {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': newCsrf },
      redirects: 0,
    });
    if (recRes.status >= 400) {
      throw new Error(`POST /v2/carts/${cartId}/recover after fresh login unexpected status ${recRes.status} ${recRes.body}`);
    }
    newCsrf = updateCsrf(recRes, newCsrf);
    newEtag = extractETag(recRes) || newEtag;
  }

  return { csrf: newCsrf, etag: newEtag, grant };
}

function recoverFrom401(errorCode, csrf, cartId, etag, username, password) {
  if (errorCode === 'expired') {
    const renewRes = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      redirects: 0,
    });

    if (renewRes.status === 200 || renewRes.status === 201 || renewRes.status === 204) {
      let newCsrf = updateCsrf(renewRes, csrf);
      let newEtag = etag;

      if (cartId) {
        const recRes = http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, '{}', {
          headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': newCsrf },
          redirects: 0,
        });
        if (recRes.status >= 400) {
          throw new Error(`POST /v2/carts/${cartId}/recover unexpected status ${recRes.status} ${recRes.body}`);
        }
        newCsrf = updateCsrf(recRes, newCsrf);
        newEtag = extractETag(recRes) || newEtag;
      }

      return { csrf: newCsrf, etag: newEtag, grant: null };
    }

    if (renewRes.status === 401 && extractErrorCode(renewRes) === 'session') {
      return freshLoginRecover(cartId, etag, username, password);
    }

    throw new Error(`POST /v2/session/renew unexpected status ${renewRes.status} ${renewRes.body}`);
  }

  if (errorCode === 'session') {
    return freshLoginRecover(cartId, etag, username, password);
  }

  fail(`unexpected recovery error code ${errorCode}`);
}

function chooseProduct(csrf, username, password) {
  let res = http.get(`${BASE_URL}/v2/catalog`, { redirects: 0 });

  if (res.status === 401) {
    const code = extractErrorCode(res);
    if (code === 'expired' || code === 'session') {
      const rec = recoverFrom401(code, csrf, null, null, username, password);
      csrf = rec.csrf;
      res = http.get(`${BASE_URL}/v2/catalog`, { redirects: 0 });
    } else if (code === 'denied') {
      fail('GET /v2/catalog 401 denied');
    }
  }

  if (res.status !== 200) {
    throw new Error(`GET /v2/catalog unexpected status ${res.status} ${res.body}`);
  }

  let catalog = extractCatalogData(res);
  let selection = findInStockProduct(catalog.data);
  let next = catalog.next;
  csrf = updateCsrf(res, csrf);

  if (!selection) {
    let pagePath = '/v2/catalog/page';
    for (let i = 0; i < 3 && !selection; i++) {
      let pageRes = http.get(resolveUrl(pagePath), { redirects: 0 });

      if (pageRes.status === 401) {
        const code = extractErrorCode(pageRes);
        if (code === 'expired' || code === 'session') {
          const rec = recoverFrom401(code, csrf, null, null, username, password);
          csrf = rec.csrf;
          pageRes = http.get(resolveUrl(pagePath), { redirects: 0 });
        } else if (code === 'denied') {
          fail('GET /v2/catalog/page 401 denied');
        }
      }

      if (pageRes.status !== 200) {
        throw new Error(`GET /v2/catalog/page unexpected status ${pageRes.status} ${pageRes.body}`);
      }

      const pageCatalog = extractCatalogData(pageRes);
      selection = findInStockProduct(pageCatalog.data);
      next = pageCatalog.next;
      csrf = updateCsrf(pageRes, csrf);

      if (!selection && next) {
        pagePath = next;
      } else {
        break;
      }
    }
  }

  if (!selection) {
    throw new Error('no in-stock product found in catalog');
  }

  return { productId: selection.productId, variantId: selection.variantId, csrf };
}

function createCart(csrf, initialGrant, productId, variantId, username, password) {
  let currentGrant = initialGrant;
  const url = `${BASE_URL}/v2/carts`;

  const buildPayload = () => {
    const payload = { product_id: productId, variant_id: variantId };
    if (currentGrant) payload.grant_id = currentGrant;
    return JSON.stringify(payload);
  };

  let res = http.post(url, buildPayload(), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });

  if (res.status === 401) {
    const code = extractErrorCode(res);
    if (code === 'expired' || code === 'session') {
      const rec = recoverFrom401(code, csrf, null, null, username, password);
      csrf = rec.csrf;
      if (rec.grant) currentGrant = rec.grant;
      res = http.post(url, buildPayload(), {
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
        redirects: 0,
      });
    } else if (code === 'denied') {
      fail('POST /v2/carts 401 denied');
    }
  }

  if (res.status !== 201) {
    throw new Error(`POST /v2/carts unexpected status ${res.status} ${res.body}`);
  }

  const j = parseJsonSafely(res.body);
  if (!j || typeof j.id !== 'string') {
    throw new Error('POST /v2/carts response missing id');
  }

  csrf = updateCsrf(res, csrf);
  let etag = extractETag(res);

  if (!etag) {
    const cartUrl = `${BASE_URL}/v2/carts/${j.id}`;
    let getRes = http.get(cartUrl, { redirects: 0 });

    if (getRes.status === 401) {
      const code = extractErrorCode(getRes);
      if (code === 'expired' || code === 'session') {
        const rec = recoverFrom401(code, csrf, j.id, etag, username, password);
        csrf = rec.csrf;
        etag = rec.etag;
        getRes = http.get(cartUrl, { redirects: 0 });
      } else if (code === 'denied') {
        fail('GET /v2/carts/{id} 401 denied');
      }
    }

    if (getRes.status !== 200) {
      throw new Error(`GET /v2/carts/${j.id} unexpected status ${getRes.status} ${getRes.body}`);
    }

    etag = extractETag(getRes) || etag;
    csrf = updateCsrf(getRes, csrf);
  }

  if (!etag) {
    throw new Error('cart ETag missing after cart creation');
  }

  return { cartId: j.id, etag, csrf };
}

function patchCart(csrf, cartId, etag, quantity, username, password) {
  const url = `${BASE_URL}/v2/carts/${cartId}`;
  const payload = JSON.stringify({ quantity });

  const makeHeaders = (c, e) => {
    const headers = { 'Content-Type': 'application/json', 'X-CSRF-Token': c };
    if (e) headers['If-Match'] = e;
    return headers;
  };

  let res = http.patch(url, payload, { headers: makeHeaders(csrf, etag), redirects: 0 });

  if (res.status === 412) {
    let getRes = http.get(url, { redirects: 0 });

    if (getRes.status === 401) {
      const code = extractErrorCode(getRes);
      if (code === 'expired' || code === 'session') {
        const rec = recoverFrom401(code, csrf, cartId, etag, username, password);
        csrf = rec.csrf;
        etag = rec.etag;
        getRes = http.get(url, { redirects: 0 });
      } else if (code === 'denied') {
        fail(`GET ${url} 401 denied`);
      }
    }

    if (getRes.status !== 200) {
      throw new Error(`GET ${url} after 412 unexpected status ${getRes.status} ${getRes.body}`);
    }

    etag = extractETag(getRes) || etag;
    csrf = updateCsrf(getRes, csrf);

    res = http.patch(url, payload, { headers: makeHeaders(csrf, etag), redirects: 0 });
  }

  if (res.status === 401) {
    const code = extractErrorCode(res);
    if (code === 'expired' || code === 'session') {
      const rec = recoverFrom401(code, csrf, cartId, etag, username, password);
      csrf = rec.csrf;
      etag = rec.etag;
      res = http.patch(url, payload, { headers: makeHeaders(csrf, etag), redirects: 0 });
    } else if (code === 'denied') {
      fail(`PATCH ${url} 401 denied`);
    }
  }

  if (res.status < 200 || res.status >= 300) {
    throw new Error(`PATCH ${url} unexpected status ${res.status} ${res.body}`);
  }

  csrf = updateCsrf(res, csrf);
  etag = extractETag(res) || etag;
  return { csrf, etag };
}

function placeOrder(csrf, cartId, etag, username, password) {
  const url = `${BASE_URL}/v2/orders`;
  const payload = JSON.stringify({ cart_id: cartId });

  const makeHeaders = (c, e) => {
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': c,
      'Idempotency-Key': cartId,
    };
    if (e) headers['If-Match'] = e;
    return headers;
  };

  let res = http.post(url, payload, { headers: makeHeaders(csrf, etag), redirects: 0 });

  if (res.status === 401) {
    const code = extractErrorCode(res);
    if (code === 'expired' || code === 'session') {
      const rec = recoverFrom401(code, csrf, cartId, etag, username, password);
      csrf = rec.csrf;
      etag = rec.etag;
      res = http.post(url, payload, { headers: makeHeaders(csrf, etag), redirects: 0 });
    } else if (code === 'denied') {
      fail('POST /v2/orders 401 denied');
    }
  }

  if (res.status === 201) {
    const j = parseJsonSafely(res.body);
    if (!j || j.accepted !== true) {
      fail('POST /v2/orders 201 did not accept true');
    }
