  }

  if (res.status === 200) {
    const j = parseJsonSafely(res.body);
    if (j && j.accepted === false) {
      fail('POST /v2/orders business failure accepted false');
    }
    return;
  }

  throw new Error(`POST /v2/orders unexpected status ${res.status} ${res.body}`);
}

export default function () {
  const accountIndex = (__VU - 1) % accounts.length;
  const account = accounts[accountIndex];
  if (!account) {
    fail(`no account row for VU ${__VU}`);
  }

  const username = account.username;
  const password = account.password || 'bench';
  const quantity = Number(account.quantity);

  if (!Number.isInteger(quantity) || quantity < 1 || quantity > 20) {
    fail(`invalid quantity for ${username}: ${account.quantity}`);
  }

  const login = performLogin(username, password);
  let csrf = login.csrf;
  const grant = login.grant;

  const selection = chooseProduct(csrf, username, password);
