  const cart = createCart(csrf, grant, selection.productId, selection.variantId, username, password);
  csrf = cart.csrf;

  const patched = patchCart(csrf, cart.cartId, cart.etag, quantity, username, password);
  csrf = patched.csrf;

  placeOrder(csrf, cart.cartId, patched.etag, username, password);
}

