import json
import re
import itertools
import threading
from pathlib import Path

from locust import HttpUser, task, LoadTestShape, constant, StopUser

USERS = 2
ITERATIONS = 2

def _load_accounts():
    for path in ("/fixtures/accounts.json", "/fixtures/m04-accounts.json"):
        try:
            return json.loads(Path(path).read_text())
        except Exception:
            pass
    raise RuntimeError("accounts fixture not found")

ACCOUNTS = _load_accounts()

_ROW_ITER = itertools.count()
_ROW_LOCK = threading.Lock()
_DONE_LOCK = threading.Lock()
DONE_JOURNEYS = 0


def _next_account():
    with _ROW_LOCK:
        idx = next(_ROW_ITER)
    return ACCOUNTS[idx % len(ACCOUNTS)]


class ShopUser(HttpUser):
    wait_time = constant(0)

    def on_start(self):
        self.account = _next_account()
        self.username = self.account["username"]
        self.quantity = int(self.account["quantity"])
        self.iterations_left = ITERATIONS

        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.idempotency_key = None

        self.client.max_redirects = 0

    @task
    def journey(self):
        if self.iterations_left <= 0:
            raise StopUser()

        self.client.cookies.clear()
        try:
            self._run_journey()
        finally:
            self.iterations_left -= 1
            global DONE_JOURNEYS
            with _DONE_LOCK:
                DONE_JOURNEYS += 1
            if self.iterations_left <= 0:
                raise StopUser()

    @staticmethod
    def _parse_json(r):
