                with self.client.get(
                    location, allow_redirects=False, catch_response=True
                ) as r2:
                    if r2.status_code != 200:
                        r2.failure(f"login redirect GET status {r2.status_code}")
                        return False
                    data = self._parse_json(r2)
                    if not isinstance(data, dict) or "csrf" not in data:
                        r2.failure("login redirect response missing csrf")
                        return False
                    self.csrf = data["csrf"]
                    self.grant_id = data.get("grant_id")
                    return True

            r.failure(f"login status {r.status_code}")
            return False

    @staticmethod
    def _product_from_data(data):
        if not isinstance(data, dict):
            return None

        items = []
        if isinstance(data.get("data"), dict):
            if data["data"].get("products"):
                items = data["data"]["products"]
            elif data["data"].get("product"):
                items = [data["data"]["product"]]
        else:
            if data.get("products"):
                items = data["products"]
            elif data.get("product"):
                items = [data["product"]]

        for product in items:
            if not isinstance(product, dict):
                continue
            variants = product.get("variants")
            if isinstance(variants, list) and variants:
                first = variants[0]
                if isinstance(first, dict) and first.get("in_stock") is True:
                    return str(product.get("id")), str(first.get("id"))
        return None

    def _find_in_stock_product(self):
        page_url = "/v2/catalog"
        for _ in range(3):
            with self.client.get(
                page_url, allow_redirects=False, catch_response=True
            ) as r:
                if r.status_code != 200:
                    r.failure(f"catalog status {r.status_code}")
                    return None

                self._maybe_update_csrf_json(r)
                data = self._parse_json(r)
                if not isinstance(data, dict):
                    r.failure("catalog invalid json")
                    return None

                found = self._product_from_data(data)
                if found:
                    return found

                next_url = None
                if isinstance(data.get("data"), dict):
                    next_url = data["data"].get("next")
                elif data.get("next") is not None:
                    next_url = data.get("next")

                if not next_url:
                    break
                page_url = next_url
        return None

    def _read_cart(self):
        if not self.cart_id:
            return False

        with self.client.get(
            f"/v2/carts/{self.cart_id}", allow_redirects=False, catch_response=True
        ) as r:
            if r.status_code == 200:
                self._maybe_update_etag(r)
                self._maybe_update_csrf_json(r)
                return True
            r.failure(f"cart GET status {r.status_code}")
            return False

    def _renew_session(self):
        headers = {"Content-Type": "application/json"}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf

        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if 200 <= r.status_code < 300:
                self._maybe_update_csrf_json(r)
                self._maybe_update_etag(r)
                return True
            if r.status_code == 401:
                return False
            r.failure(f"session renew status {r.status_code}")
            return False

    def _recover_cart(self):
        if not self.cart_id:
            return True

        headers = {"Content-Type": "application/json"}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf

        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if 200 <= r.status_code < 300:
                self._maybe_update_csrf_json(r)
                self._maybe_update_etag(r)
                return True
            r.failure(f"cart recover status {r.status_code}")
            return False

    def _handle_401(self, r):
        err = self._extract_error(r)
        if err == "denied":
            return False

        if err == "expired":
            if not self._renew_session():
                return False
            return self._recover_cart()

        if err == "session":
            if self._renew_session():
                return self._recover_cart()
            if self._login():
                return self._recover_cart()
            return False

        return False

    def _create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id

        for attempt in range(2):
            headers = {"Content-Type": "application/json"}
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf

            with self.client.post(
                "/v2/carts",
                json=payload,
                headers=headers,
                allow_redirects=False,
                catch_response=True,
            ) as r:
                if r.status_code == 201:
                    data = self._parse_json(r)
                    if not isinstance(data, dict) or "id" not in data:
                        r.failure("cart creation missing id")
                        return False

                    self.cart_id = data["id"]
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    self.etag = r.headers.get("ETag")

                    if not self.etag:
                        if not self._read_cart():
                            return False
                        if not self.etag:
                            r.failure("cart creation did not return ETag")
                            return False

                    self.idempotency_key = self.cart_id
                    return True

                if r.status_code == 401 and attempt == 0:
                    if self._handle_401(r):
                        continue
                    r.failure("cart creation 401 recovery failed")
                    return False

                r.failure(f"cart creation status {r.status_code}")
                return False
        return False

    def _patch_cart(self):
        if not self.cart_id:
            return False

        for attempt in range(2):
            headers = {"Content-Type": "application/json"}
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf
            if self.etag:
                headers["If-Match"] = self.etag

            with self.client.patch(
                f"/v2/carts/{self.cart_id}",
                json={"quantity": self.quantity},
                headers=headers,
                allow_redirects=False,
                catch_response=True,
            ) as r:
                if r.status_code in (200, 201, 204):
                    self._maybe_update_csrf_json(r)
                    self._maybe_update_etag(r)
                    return True

                if r.status_code == 412 and attempt == 0:
                    if self._read_cart():
                        continue
                    r.failure("cart patch 412 re-read failed")
                    return False

                if r.status_code == 401 and attempt == 0:
                    if self._handle_401(r):
                        continue
                    r.failure("cart patch 401 recovery failed")
                    return False

                r.failure(f"cart patch status {r.status_code}")
                return False
        return False

    def _place_order(self):
        if not self.cart_id:
            return False

        for attempt in range(2):
            headers = {
                "Content-Type": "application/json",
                "Idempotency-Key": self.cart_id,
            }
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf
            if self.etag:
                headers["If-Match"] = self.etag

            with self.client.post(
                "/v2/orders",
                json={"cart_id": self.cart_id},
                headers=headers,
                allow_redirects=False,
                catch_response=True,
            ) as r:
                if r.status_code == 201:
                    data = self._parse_json(r)
                    if (
                        not isinstance(data, dict)
                        or data.get("accepted") is not True
                        or "id" not in data
                    ):
                        r.failure("order validation failed")
                        return False

                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    return True

                if r.status_code == 401 and attempt == 0:
                    if self._handle_401(r):
                        continue
                    r.failure("order 401 recovery failed")
                    return False

                r.failure(f"order status {r.status_code}")
                return False
        return False

    def _run_journey(self):
        if not self._login():
            return

        found = self._find_in_stock_product()
        if not found:
            return

        product_id, variant_id = found
        if not self._create_cart(product_id, variant_id):
            return

        if not self._patch_cart():
            return

        if not self._place_order():
            return


class JourneyShape(LoadTestShape):
    _spawned = False

    def tick(self):
        if not self._spawned:
            self._spawned = True
            return (USERS, USERS)

        global _completed_journeys
        if _completed_journeys >= USERS * ITERATIONS:
            return None

        return (USERS, 0)

