import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.concurrent.atomic.AtomicInteger;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  private static final AtomicInteger USER_SEQUENCE = new AtomicInteger(0);

  private static final String BASE_URL =
      System.getenv("BASE_URL") == null ? "http://127.0.0.1:8000" : System.getenv("BASE_URL");

  private static final String CSRF_REGEX =
      "<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>";

  private static final HttpProtocolBuilder httpProtocol =
      http
          .baseUrl(BASE_URL)
          .disableFollowRedirect();

  private static final ChainBuilder loginForm =
      exec(session -> session.set("csrf", "MISSING")
              .set("cart", "MISSING")
              .set("etag", "MISSING")
              .set("grant", "MISSING")
              .set("location", null)
              .set("product", null)
              .set("variant", null))
          .exec(http("Login Form")
              .get("/v2/login-form")
              .check(regex(CSRF_REGEX).saveAs("form")));

  private static final ChainBuilder login =
      exec(http("Login")
          .post("/v2/login")
          .header("Content-Type", "application/json")
          .header("X-CSRF-Token", "#{form}")
          .body(StringBody("{\"username\":\"bench-${userNum}\",\"password\":\"bench\",\"csrf\":\"${form}\"}"))
          .check(header("Location").optional().saveAs("location"))
          .check(jsonPath("$.csrf").optional().saveAs("csrf")))
          .exec(doIf(session -> session.get("location") != null).then(
              exec(http("Login Redirect")
                  .get("#{location}")
                  .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                  .check(jsonPath("$.grant_id").optional().saveAs("grant")))));

  private static final ChainBuilder catalog =
      exec(http("Catalog")
          .get("/v2/catalog")
          .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id").saveAs("product"))
          .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id").saveAs("variant")))
          .exec(session -> session.set("product", String.valueOf(session.get("product")))
              .set("variant", String.valueOf(session.get("variant"))));

  private static final ChainBuilder createCart =
      exec(http("Create Cart")
          .post("/v2/carts")
          .header("Content-Type", "application/json")
          .header("X-CSRF-Token", "#{csrf}")
          .body(StringBody(session -> {
              String product = session.getString("product");
              String variant = session.getString("variant");
              String grant = session.getString("grant");

              StringBuilder body = new StringBuilder();
              body.append("{\"product_id\":\"").append(product)
                  .append("\",\"variant_id\":\"").append(variant).append("\"");

              if (grant != null && !grant.equals("MISSING") && !grant.isEmpty()) {
                  body.append(",\"grant_id\":\"").append(grant).append("\"");
              }

              body.append("}");
              return body.toString();
          }))
          .check(status().is(201))
          .check(jsonPath("$.csrf").optional().saveAs("csrf"))
          .check(jsonPath("$.id").saveAs("cart"))
          .check(header("ETag").optional().saveAs("etag")))
          .exec(session -> session.set("cart", String.valueOf(session.get("cart"))));

  private static final ChainBuilder checkout =
      exec(http("Checkout")
          .post("/v2/orders")
          .header("Content-Type", "application/json")
          .header("X-CSRF-Token", "#{csrf}")
          .header("Idempotency-Key", "#{cart}")
          .body(StringBody("{\"cart_id\":\"${cart}\"}"))
          .check(status().is(201))
          .check(regex("\"accepted\"\\s*:\\s*true").exists())
          .check(jsonPath("$.csrf").optional().saveAs("csrf")));

  private static final ChainBuilder journey =
      loginForm
          .exec(login)
          .exec(catalog)
          .exec(createCart)
          .exec(checkout);

  private static final ScenarioBuilder scenario =
      scenario("Model")
          .exec(session -> {
              int seq = USER_SEQUENCE.getAndIncrement();
              return session.set("userNum", (seq % 16) + 1)
                      .set("initialDelay", (seq % 4) * 500L);
          })
          .exec(pause(session -> Duration.ofMillis(session.getLong("initialDelay"))))
          .exec(forever().on(
              pace(Duration.ofSeconds(2)),
              journey
          ));

  {
      setUp(
          scenario.injectOpen(atOnceUsers(4))
      ).protocols(httpProtocol)
       .maxDuration(Duration.ofSeconds(38));
  }
}
