const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const CHECKOUT_OFFSET_MS = 1000;
const TARGET_INTERVAL_MS = 500;
const START_TIME = Date.now();

function absoluteUrl(path) {
  if (!path) return null;
  if (/^https?:\/\//i.test(path)) return path;
  return `${BASE_URL}${path.startsWith('/') ? '' : '/'}${path}`;
}

function extractCsrf(html) {
  if (!html) return 'MISSING';
  const tags = html.match(/<input\b[^>]*>/gi) || [];
  for (const tag of tags) {
    if (/name\s*=\s*["']csrf["']/i.test(tag)) {
      const valueMatch = tag.match(/value\s*=\s*["']([^"']*)["']/i);
      if (valueMatch) {
        return valueMatch[1];
      }
    }
  }
  return 'MISSING';
}

function getLocation(res) {
  return res.headers && (res.headers['Location'] || res.headers['location']);
}

function safeJson(text) {
  try {
    return JSON.parse(text);
  } catch (e) {
    return null;
  }
}

function makeHeaders(csrf, extra) {
  return Object.assign({ 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }, extra || {});
}

function findInStockProduct(products) {
  if (!Array.isArray(products)) return null;
  for (const product of products) {
    if (product && Array.isArray(product.variants)) {
      const variant = product.variants.find(v => v && (v.in_stock === true || v.in_stock === 'true'));
      if (variant) {
        return { product_id: product.id, variant_id: variant.id };
      }
    }
  }
  return null;
}

export function journey() {
  const cookieJar = http.cookieJar();
  cookieJar.clear(BASE_URL);

  let csrf = 'MISSING';
  let formCsrf = 'MISSING';
  let grant = 'MISSING';
  let product_id = 'MISSING';
  let variant_id = 'MISSING';
  let cart_id = 'MISSING';
  let etag = 'MISSING';
