    redirects: 0,
    headers: makeHeaders(csrf),
  });

  let loginSucceeded = false;
  if (res.status === 200) {
    const data = safeJson(res.body);
    if (data) {
      if (data.csrf) csrf = data.csrf;
      if (data.grant_id) grant = data.grant_id;
    }
    loginSucceeded = true;
  } else if (res.status === 302) {
    const location = getLocation(res);
    if (location) {
      res = http.get(absoluteUrl(location), { redirects: 0, headers: { 'X-CSRF-Token': csrf } });
      check(res, {'login redirect 200': (r) => r.status === 200});
      const data = safeJson(res.body);
      if (data) {
        if (data.csrf) csrf = data.csrf;
        if (data.grant_id) grant = data.grant_id;
      }
      loginSucceeded = res.status === 200;
    }
  }
  if (!loginSucceeded) {
    throw new Error(`Login failed: ${res.status}`);
  }

  // 3. Catalog selection
  let found = null;
  let nextPath = null;
  for (let page = 0; page <= 3 && !found; page++) {
    let catRes;
    if (page === 0) {
      catRes = http.get(`${BASE_URL}/v2/catalog`, { redirects: 0, headers: { 'X-CSRF-Token': csrf } });
    } else if (nextPath) {
