  if (res.status !== 201) {
    throw new Error(`Cart creation failed: ${res.status}`);
  }
  const cartData = safeJson(res.body);
  if (!cartData || !cartData.id) {
    throw new Error('Cart response missing id');
  }
  cart_id = cartData.id;
  if (cartData.csrf) csrf = cartData.csrf;
  etag = res.headers['ETag'] || res.headers['etag'] || 'MISSING';

  // 5. Checkout at scheduled slot
  const iterationIndex = (exec.scenario && typeof exec.scenario.iterationInTest === 'number') ? exec.scenario.iterationInTest : __ITER;
  const targetTime = START_TIME + CHECKOUT_OFFSET_MS + (iterationIndex * TARGET_INTERVAL_MS);
  const delay = targetTime - Date.now();
  if (delay > 0) {
    sleep(delay / 1000);
  }

  const orderHeaders = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': cart_id,
    'If-Match': etag,
  };
  res = http.post(`${BASE_URL}/v2/orders`, JSON.stringify({ cart_id }), { redirects: 0, headers: orderHeaders });

  let orderData = safeJson(res.body);
  let committed = res.status === 201 && orderData && orderData.accepted === true;
  check(res, {'order accepted': () => committed});

  if (!committed && res.status === 401 && orderData && orderData.error === 'expired') {
