    const renewData = safeJson(renewRes.body);
    if (renewData && renewData.csrf) csrf = renewData.csrf;

    http.post(`${BASE_URL}/v2/carts/${cart_id}/recover`, '{}', { redirects: 0, headers: makeHeaders(csrf) });

    const retryHeaders = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'Idempotency-Key': cart_id,
      'If-Match': etag,
    };
    res = http.post(`${BASE_URL}/v2/orders`, JSON.stringify({ cart_id }), { redirects: 0, headers: retryHeaders });
    orderData = safeJson(res.body);
    committed = res.status === 201 && orderData && orderData.accepted === true;
