import os
import json
import re
import time
import itertools

from locust import HttpUser, task, LoadTestShape
from locust.wait_time import constant_pacing
from locust.exception import StopUser

BASE_URL = os.environ["BASE_URL"]

FIRST_CHECKOUT_TIME = None
SHAPE_START_TIME = None

ACCOUNTS = [f"bench-{i}" for i in range(1, 17)] + ["bench"]
_ACCOUNT_CYCLE = itertools.cycle(ACCOUNTS)


def parse_form_csrf(html: str):
    if not html:
        return None
    m = re.search(
        r"""<input\b(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>""",
        html,
        re.I | re.S,
    )
    if not m:
        m = re.search(
            r"""<input[^>]+name=["']csrf["'][^>]+value=["']([^"']+)["']""",
            html,
            re.I | re.S,
        )
    if not m:
        m = re.search(
            r"""<input[^>]+value=["']([^"']+)["'][^>]+name=["']csrf["']""",
            html,
            re.I | re.S,
        )
    return m.group(1) if m else None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant_pacing(2.0)

    def on_start(self):
        self.account = next(_ACCOUNT_CYCLE)
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.form = None
        self.redirect_location = None
        self.journey_failed = False
        self.product_id = None
        self.variant_id = None

    @task
    def run_journey(self):
        global FIRST_CHECKOUT_TIME
        if FIRST_CHECKOUT_TIME is not None and time.time() > FIRST_CHECKOUT_TIME + 40:
            raise StopUser()
        self.journey_failed = False
        self.journey()

    def _fail(self, response, message):
        response.failure(message)
        self.journey_failed = True

    def journey(self):
        self.client.cookies.clear()
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.form = None
        self.redirect_location = None
        self.product_id = None
        self.variant_id = None

        # GET login form
        with self.client.get(
            "/v2/login-form",
            allow_redirects=False,
            catch_response=True,
            name="/v2/login-form",
        ) as r:
            if r.status_code != 200:
                self._fail(r, f"login-form status {r.status_code}")
                return
            form_csrf = parse_form_csrf(r.text)
            if not form_csrf:
                self._fail(r, "login-form csrf not found")
                return
            self.form = form_csrf
            self.csrf = form_csrf

        # POST login
        login_body = json.dumps(
            {"username": self.account, "password": "bench", "csrf": self.form}
        )
        with self.client.post(
            "/v2/login",
            data=login_body,
            headers={"Content-Type": "application/json", "X-CSRF-Token": self.csrf},
            allow_redirects=False,
            catch_response=True,
            name="/v2/login",
        ) as r:
            if r.status_code == 401:
                self._fail(r, "login 401")
                return
            if r.status_code in (301, 302, 303, 307, 308):
                loc = r.headers.get("Location")
                if not loc:
                    self._fail(r, "login redirect missing Location")
                    return
                self.redirect_location = loc
            elif r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    self._fail(r, "login non-json")
                    return
                if not isinstance(data, dict) or "csrf" not in data:
                    self._fail(r, "login missing csrf")
                    return
                self.csrf = data.get("csrf", self.csrf)
                loc = r.headers.get("Location")
                if loc:
                    self.redirect_location = loc
            else:
                self._fail(r, f"login status {r.status_code}")
                return

        # Follow redirect exactly once if present
        if self.redirect_location:
            with self.client.get(
                self.redirect_location,
                allow_redirects=False,
                catch_response=True,
                name="/v2/login-redirect",
            ) as r:
                if r.status_code != 200:
                    self._fail(r, f"redirect status {r.status_code}")
                    return
                try:
                    data = r.json()
                except Exception:
                    self._fail(r, "redirect non-json")
                    return
                if isinstance(data, dict):
                    self.csrf = data.get("csrf", self.csrf)
                    self.grant_id = data.get("grant_id")
                else:
                    self._fail(r, "redirect json not object")
                    return

