    def _extract_product(self, data):
        if not isinstance(data, dict):
            return None, None
        data_wrapper = data.get("data", data)
        products = None
        if isinstance(data_wrapper, dict):
            if "products" in data_wrapper:
                products = data_wrapper["products"]
            elif "product" in data_wrapper:
                products = [data_wrapper["product"]]
        if not products:
            return None, None

        for prod in products:
            if not isinstance(prod, dict):
                continue
            for var in prod.get("variants", []):
                if isinstance(var, dict) and var.get("in_stock") is True:
                    return prod.get("id"), var.get("id")
        return None, None

    def _fetch_catalog_product(self):
        # First attempt: broad catalog
        with self.client.get(
            "/v2/catalog",
            allow_redirects=False,
            catch_response=True,
            name="/v2/catalog",
        ) as r:
            if r.status_code != 200:
                self._fail(r, f"catalog status {r.status_code}")
                return False
            try:
                data = r.json()
            except Exception:
                self._fail(r, "catalog non-json")
                return False
            product_id, variant_id = self._extract_product(data)
            if product_id and variant_id:
                self.product_id = product_id
                self.variant_id = variant_id
                return True

        # Fallback: traverse catalog/page at most 3 times
        next_path = "/v2/catalog/page"
        last_r = r
        for _ in range(3):
            if not next_path:
                break
            with self.client.get(
                next_path,
                allow_redirects=False,
                catch_response=True,
                name="/v2/catalog/page",
            ) as r:
                last_r = r
                if r.status_code != 200:
                    self._fail(r, f"catalog page status {r.status_code}")
                    return False
                try:
                    data = r.json()
                except Exception:
                    self._fail(r, "catalog page non-json")
                    return False
                product_id, variant_id = self._extract_product(data)
                if product_id and variant_id:
                    self.product_id = product_id
                    self.variant_id = variant_id
                    return True
                next_path = None
                if isinstance(data, dict):
                    data_wrapper = data.get("data", data)
                    if isinstance(data_wrapper, dict):
                        next_path = data_wrapper.get("next")

        self._fail(last_r, "no in-stock product found")
        return False

    def _post_cart(self):
        body = {"product_id": self.product_id, "variant_id": self.variant_id}
        if self.grant_id and str(self.grant_id) != "MISSING":
            body["grant_id"] = self.grant_id

        headers = {
            "Content-Type": "application/json",
            "X-CSRF-Token": self.csrf,
        }
        with self.client.post(
            "/v2/carts",
            data=json.dumps(body),
            headers=headers,
            allow_redirects=False,
            catch_response=True,
