            return False

    def _post_order(self):
        if not self.cart_id:
            return

        if not reserve_checkout_slot():
            raise StopUser()

        headers = {
            "Content-Type": "application/json",
            "X-CSRF-Token": self.csrf or "",
            "Idempotency-Key": self.cart_id,
        }
        if self.etag:
            headers["If-Match"] = self.etag

        body = {"cart_id": self.cart_id}
        self._post_order_once(headers, body, 0)

    def _post_order_once(self, headers, body, attempt):
        request_start = time.monotonic()

        with self.client.post(
            "/v2/orders",
            data=json.dumps(body),
            headers=headers,
            allow_redirects=False,
            catch_response=True,
            name="/v2/orders",
        ) as r:
            if r.status_code == 201:
                try:
                    data = r.json()
                except Exception:
                    r.failure("order non-json")
                    return False

                if data.get("accepted") is True and data.get("id"):
                    self.csrf = data.get("csrf", self.csrf)
                    global FIRST_CHECKOUT_TIME
                    if FIRST_CHECKOUT_TIME is None:
                        FIRST_CHECKOUT_TIME = request_start
                    return True

                r.failure(f"order accepted false: {r.text}")
                return False

            if r.status_code == 401:
                err = self._parse_error(r)
                if err in ("expired", "session") and attempt == 0:
                    if self._recover_from_401(err):
                        new_headers = {
                            "Content-Type": "application/json",
                            "X-CSRF-Token": self.csrf or "",
                            "Idempotency-Key": self.cart_id,
                        }
                        if self.etag:
                            new_headers["If-Match"] = self.etag
                        return self._post_order_once(new_headers, body, attempt + 1)
                    r.failure(f"order recovery failed for {err}")
                    return False
                r.failure(f"order 401 denied: {err}")
                return False

            r.failure(f"order status {r.status_code}")
            return False

    def _parse_error(self, response):
        try:
            data = response.json()
        except Exception:
            return ""
        if isinstance(data, dict):
            return str(data.get("error", ""))
        return ""

    def _recover_from_401(self, err):
        if err == "expired":
            return self._recover_expired()
        if err == "session":
            return self._recover_session()
        return False

    def _renew_session(self):
        with self.client.post(
            "/v2/session/renew",
            data="{}",
            headers={"Content-Type": "application/json", "X-CSRF-Token": self.csrf or ""},
            allow_redirects=False,
            catch_response=True,
            name="/v2/session/renew",
        ) as r:
            if r.status_code != 200:
                r.failure(f"session renew status {r.status_code}")
                return False
            try:
                data = r.json()
            except Exception:
                r.failure("session renew non-json")
                return False
            if isinstance(data, dict):
                self.csrf = data.get("csrf", self.csrf)
            return True

    def _recover_cart(self):
        if not self.cart_id:
            return True

        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            data="{}",
            headers={"Content-Type": "application/json", "X-CSRF-Token": self.csrf or ""},
            allow_redirects=False,
            catch_response=True,
            name="/v2/carts/recover",
        ) as r:
            if r.status_code not in (200, 201):
                r.failure(f"cart recover status {r.status_code}")
                return False
            self.etag = r.headers.get("ETag") or r.headers.get("etag") or self.etag
            try:
                data = r.json()
                if isinstance(data, dict):
                    self.csrf = data.get("csrf", self.csrf)
            except Exception:
                pass
            return True

    def _recover_expired(self):
        if not self._renew_session():
            return False
        if self.cart_id:
            if not self._recover_cart():
                return False
        return True

    def _recover_session(self):
        try:
            self.client.cookies.clear()

            with self.client.get(
                "/v2/login-form",
                allow_redirects=False,
                catch_response=True,
                name="/v2/login-form",
            ) as r:
                if r.status_code != 200:
                    r.failure(f"session recovery login-form status {r.status_code}")
                    return False
                form_csrf = parse_form_csrf(r.text)
                if not form_csrf:
                    r.failure("session recovery login-form csrf not found")
                    return False

            login_body = json.dumps(
                {"username": self.account, "password": "bench", "csrf": form_csrf}
            )
            with self.client.post(
                "/v2/login",
                data=login_body,
                headers={"Content-Type": "application/json", "X-CSRF-Token": form_csrf},
                allow_redirects=False,
                catch_response=True,
                name="/v2/login",
            ) as r:
                if r.status_code in (301, 302, 303, 307, 308):
                    location = r.headers.get("Location")
                    if not location:
                        r.failure("session recovery login redirect missing Location")
                        return False
                    if not self._follow_login_redirect(location):
                        return False
                elif r.status_code == 200:
                    try:
                        data = r.json()
                    except Exception:
                        r.failure("session recovery login non-json")
                        return False
                    if not isinstance(data, dict) or "csrf" not in data:
                        r.failure("session recovery login missing csrf")
                        return False
                    self.csrf = data.get("csrf", self.csrf)
                    location = r.headers.get("Location")
                    if location:
                        if not self._follow_login_redirect(location):
                            return False
                else:
                    r.failure(f"session recovery login status {r.status_code}")
                    return False

            if self.cart_id:
                return self._recover_cart()
            return True
        except Exception:
            return False


class ShopShape(LoadTestShape):
    def tick(self):
        global SHAPE_START_TIME

        if SHAPE_START_TIME is None:
            SHAPE_START_TIME = time.monotonic()

        now = time.monotonic()

        if FIRST_CHECKOUT_TIME is None:
            if now - SHAPE_START_TIME < 12.0:
                return (4, 4)
            return None

        if now < FIRST_CHECKOUT_TIME + 35.0:
            return (4, 4)

        return None
