                        if (grant != null && !grant.equals("MISSING") && !grant.isEmpty()) {
                            json.append(",\"grant_id\":\"").append(grant).append("\"");
                        }
                        json.append("}");
                        return json.toString();
                    }))
                    .check(status().is(201))
                    .check(regex("\"id\"\\s*:\\s*\"cart-").exists())
                    .check(jsonPath("$.id").saveAs("cart"))
                    .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                    .check(header("ETag").optional().saveAs("etag"))
            )
            .exec(session -> {
                if (session.getString("etag") == null) {
                    return session.set("etag", "MISSING");
                }
                return session;
            })
            .exec(http("POST /v2/orders")
                    .post("/v2/orders")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .header("Idempotency-Key", session -> session.getString("cart"))
                    .header("If-Match", session -> session.getString("etag"))
                    .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
                    .check(status().is(201))
                    .check(regex("\"accepted\"\\s*:\\s*true").exists())
                    .check(jsonPath("$.csrf").optional().saveAs("csrf"))
            );

    ScenarioBuilder scn = scenario("shop-journey")
            .exec(repeat(2).on(journey));

    {
        setUp(scn.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
    }
}
