let csrf = '';
let cart = '';
let grant = '';
const base = __ENV.BASE_URL;

function body(r) {
  try {
    return r.json();
  } catch (_) {
    return {};
  }
}

function targetUrl(path) {
  if (/^https?:\/\//i.test(path)) return path;
  return base.replace(/\/$/, '') + path;
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const res = http.request(method, targetUrl(path), data === null ? null : JSON.stringify(data), {
    headers: Object.assign({'Content-Type': 'application/json', 'X-CSRF-Token': csrf}, extra),
    redirects: 0,
    timeout: '3s',
  });
  const b = body(res);
  if (b.csrf) csrf = b.csrf;
  if (path === '/v2/work') {
    const unexpectedFailure = res.status >= 400 && !(res.status === 401 && b.error === 'expired') && res.status !== 429;
    failure.add(unexpectedFailure);
  }
  return res;
}

function csrfFromHtml(r) {
  const el = r.html().find('input[name="csrf"]').first();
  return el ? el.attr('value') || '' : '';
}

function getEtag(r) {
  return r.headers.Etag || r.headers.ETag || r.headers.etag || '';
