        if (body.contains("\"error\":\"expired\"") || body.contains("\"error\": \"expired\"")) return "expired";
        if (body.contains("\"error\":\"session\"") || body.contains("\"error\": \"session\"")) return "session";
        if (body.contains("\"error\":\"denied\"") || body.contains("\"error\": \"denied\"")) return "denied";
        return "";
    }

    private static ChainBuilder login() {
        return exec(session -> session.set("csrf", "").set("grant", "").remove("location")
                .remove("product").remove("variant").remove("nextPage").remove("cart").remove("etag")
                .remove("pollUrl").remove("reservation").remove("jobState").remove("patchStatus")
                .remove("catalogStatus").remove("challengeHtml").remove("challengeAction")
                .remove("challengeToken"))
            .exec(http("login form").get("/v2/login-form")
                .check(regex("<input(?=[^>]*\\bname=[\\\"']csrf[\\\"'])(?=[^>]*\\bvalue=[\\\"']([^\\\"']+)[\\\"'])[^>]*>")
                    .saveAs("formCsrf")))
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> "{\"username\":\"" + username(session) + "\",\"password\":\""
                    + password(session) + "\",\"csrf\":\"" + session.getString("formCsrf") + "\"}"))
                .check(status().in(200, 302), jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.grant_id").optional().saveAs("grant"),
                    header("Location").optional().saveAs("location")))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect").get("#{location}").header("X-CSRF-Token", "#{csrf}")
                    .check(jsonPath("$.grant_id").optional().saveAs("grant"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static ChainBuilder challenge() {
        return exec(http("challenge form").get("/v2/challenge-form").header("X-CSRF-Token", "#{csrf}")
                .check(bodyString().saveAs("challengeHtml")))
            .exec(session -> {
                String html = session.getString("challengeHtml");
                Matcher action = Pattern.compile("(?i)<form[^>]*\\baction=[\\\"']([^\\\"']+)[\\\"']")
                    .matcher(html);
                Matcher token = Pattern.compile("(?i)<input(?=[^>]*\\bname=[\\\"']challenge[\\\"'])"
                    + "(?=[^>]*\\bvalue=[\\\"']([^\\\"']+)[\\\"'])[^>]*>").matcher(html);
                return action.find() && token.find()
                    ? session.set("challengeAction", action.group(1)).set("challengeToken", token.group(1))
                    : session;
            })
            .exec(http("challenge submit").post("#{challengeAction}")
                .disableFollowRedirect()
                .header("Content-Type", "application/json").header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(session -> "{\"challenge\":\"" + session.getString("challengeToken") + "\"}"))
                .check(status().in(200, 302), header("Location").optional().saveAs("location"),
                    jsonPath("$.grant_id").optional().saveAs("grant"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("challenge redirect").get("#{location}").header("X-CSRF-Token", "#{csrf}")
                    .check(jsonPath("$.grant_id").optional().saveAs("grant"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static Duration retryDelay(Session session) {
        try {
            return Duration.ofMillis(Math.max(10,
                (long) (Double.parseDouble(session.getString("retryAfter")) * 1000 + 10)));
        } catch (RuntimeException error) {
            return Duration.ofMillis(20);
        }
    }

    private static ChainBuilder withRecovery(ChainBuilder request, Set<Integer> allowedStatuses) {
        return exec(session -> session.set("opStatus", -1).set("opBody", "").set("opError", "")
                .set("recoveryCart", session.contains("cart") ? session.getString("cart") : "")
                .set("recoveryEtag", session.contains("etag") ? session.getString("etag") : ""))
            .exec(request)
            .exec(session -> session.set("opError", errorCode(session.getString("opBody"))))
            .exec(doIf(session -> session.getInt("opStatus") == 401 && "expired".equals(session.getString("opError"))).then(
                exec(http("renew expired").post("/v2/session/renew")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .check(status().is(200), jsonPath("$.csrf").optional().saveAs("csrf")))
                .exec(doIf(session -> session.contains("cart") && !session.getString("cart").isEmpty()).then(
                    exec(http("recover cart expired").post("/v2/carts/#{cart}/recover")
                        .header("Content-Type", "application/json")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}"))
                        .check(status().is(200), header("ETag").optional().saveAs("etag"),
                            jsonPath("$.csrf").optional().saveAs("csrf")))))
                .exec(request)))
            .exec(doIf(session -> session.getInt("opStatus") == 401 && "session".equals(session.getString("opError"))).then(
                exec(session -> session.set("recoveryCart", session.contains("cart") ? session.getString("cart") : "")
                    .set("recoveryEtag", session.contains("etag") ? session.getString("etag") : ""))
                .exec(login())
                .exec(session -> {
                    String cart = session.getString("recoveryCart");
                    if (cart != null && !cart.isEmpty()) {
                        return session.set("cart", cart).set("etag", session.getString("recoveryEtag"));
                    }
                    return session.remove("cart").remove("etag");
                })
                .exec(doIf(session -> session.contains("cart") && !session.getString("cart").isEmpty()).then(
                    exec(http("recover cart session").post("/v2/carts/#{cart}/recover")
                        .header("Content-Type", "application/json")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}"))
                        .check(status().is(200), header("ETag").optional().saveAs("etag"),
                            jsonPath("$.csrf").optional().saveAs("csrf")))))
                .exec(request)))
            .exec(session -> {
                if (!allowedStatuses.contains(session.getInt("opStatus"))) {
                    return session.markAsFailed();
                }
                return session;
            });
    }

    private static ChainBuilder catalogRequest(String path) {
        return exec(http("catalog").get(path)
            .header("X-CSRF-Token", "#{csrf}")
            .check(status().saveAs("opStatus"),
                bodyString().saveAs("opBody"),
                bodyString().transform(ModelSimulation::assertNotDenied),
                jsonPath("$.csrf").optional().saveAs("csrf"),
                jsonPath("$.next").optional().saveAs("nextPage")));
    }

    private static ChainBuilder catalogNextRequest() {
        return exec(http("catalog next").get("#{nextPage}")
            .header("X-CSRF-Token", "#{csrf}")
            .check(status().saveAs("opStatus"),
                bodyString().saveAs("opBody"),
                bodyString().transform(ModelSimulation::assertNotDenied),
                jsonPath("$.csrf").optional().saveAs("csrf"),
                jsonPath("$.next").optional().saveAs("nextPage")));
    }

    private static ChainBuilder cartRequest() {
        return exec(http("cart").post("/v2/carts")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody(session -> {
                String product = session.getString("product");
                String variant = session.getString("variant");
                String grant = session.contains("grant") && !session.getString("grant").isEmpty()
                    ? session.getString("grant") : null;
                StringBuilder body = new StringBuilder("{\"product_id\":\"" + product + "\",\"variant_id\":\"" + variant + "\"");
                if (grant != null) body.append(",\"grant_id\":\"").append(grant).append("\"");
                body.append("}");
                return body.toString();
            }))
            .check(status().saveAs("opStatus"),
                bodyString().saveAs("opBody"),
                bodyString().transform(ModelSimulation::assertNotDenied),
                jsonPath("$.id").optional().saveAs("cart"),
                header("ETag").optional().saveAs("etag"),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder cartReadRequest() {
        return exec(http("cart read").get("/v2/carts/#{cart}")
            .header("X-CSRF-Token", "#{csrf}")
            .check(status().saveAs("opStatus"),
                bodyString().saveAs("opBody"),
                bodyString().transform(ModelSimulation::assertNotDenied),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder checkoutRequest() {
        return exec(http("commit").post("/v2/orders")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Idempotency-Key", "#{cart}")
            .header("If-Match", "#{etag}")
            .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cart") + "\""
                + ("reservation".equals(MODE) && session.contains("reservation")
                    ? ",\"reservation_id\":\"" + session.getString("reservation") + "\"" : "")
                + "}"))
            .check(status().saveAs("opStatus"),
                bodyString().saveAs("opBody"),
                bodyString().transform(ModelSimulation::assertNotDenied),
                jsonPath("$.csrf").optional().saveAs("csrf"),
                jsonPath("$.accepted").optional().saveAs("accepted")));
    }

    private static Session selectProduct(Session session) {
        try {
            JsonNode products = JSON.readTree(session.getString("catalogBody"))
                .path("data").path("products");
            for (JsonNode product : products) {
                for (JsonNode variant : product.path("variants")) {
                    if (variant.path("in_stock").asBoolean()) {
                        return session.set("product", product.path("id").asText())
                            .set("variant", variant.path("id").asText());
                    }
                }
            }
        } catch (IOException error) {
            return session;
        }
        return session;
    }

    private static ChainBuilder flow() {
        ChainBuilder chain = exec(flushCookieJar()).exec(login());
        if (MODE.equals("challenge")) chain = chain.exec(challenge());
        if (MODE.equals("ownership")) {
            chain = chain.exec(doIf(session -> session.userId() != 1).then(pause(Duration.ofMillis(500))));
        }
        if (MODE.equals("expiry")) chain = chain.exec(pause(Duration.ofMillis(2100)));
        String catalogPath = MODE.equals("pagination") ? "/v2/catalog/page" : "/v2/catalog";

        chain = chain.exec(withRecovery(catalogRequest(catalogPath), ok(200, 201)))
            .exec(session -> session.set("catalogBody", session.getString("opBody")))
            .exec(session -> selectProduct(session));

        if (MODE.equals("pagination")) {
            for (int page = 0; page < 2; page++) {
                chain = chain.exec(doIf(session -> !session.contains("product")
                    && session.contains("nextPage")).then(
                    exec(withRecovery(catalogNextRequest(), ok(200)))
                        .exec(session -> session.set("catalogBody", session.getString("opBody")))
                        .exec(session -> selectProduct(session))));
            }
        }

        chain = chain.exec(withRecovery(cartRequest(), ok(201)));

        if (MODE.equals("expiry") || MODE.equals("denial") || MODE.equals("ownership")) {
            chain = chain.exec(doIf(session -> MODE.equals("ownership") && session.userId() == 1)
                    .then(pause(Duration.ofMillis(300))))
                .exec(doIf(session -> MODE.equals("ownership") && session.userId() != 1)
                    .then(pause(Duration.ofMillis(500))))
                .exec(withRecovery(cartReadRequest(), ok(200, 201)));
        }

        return chain.exec(doIf(session -> !MODE.equals("reservation")
                || "ready".equals(session.getString("jobState"))).then(
            exec(withRecovery(checkoutRequest(), ok(201)))
                .exec(doIf(session -> session.getInt("opStatus") == 201).then(
                    exec(session -> {
                        if (!"true".equals(session.getString("accepted"))) {
                            return session.markAsFailed();
                        }
                        return session;
                    })))));
    }

    public ModelSimulation() {
        setUp(scenario("matrix").exec(repeat(2).on(flow())).injectOpen(atOnceUsers(2)))
            .assertions(MODE.equals("threshold")
                ? details("checkout").responseTime().percentile3().lt(250)
                : global().failedRequests().count().is(0L))
            .protocols(HTTP);
    }
}
