  { username: 'bench-13', password: 'bench', quantity: 14 },
  { username: 'bench-14', password: 'bench', quantity: 15 },
  { username: 'bench-15', password: 'bench', quantity: 16 },
  { username: 'bench-16', password: 'bench', quantity: 17 },
];

const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
let csrf = '';
let cart = '';
let grant = '';
let etag = '';

function body(r) {
  try {
    return r.json();
  } catch (_) {
    return {};
  }
}

function extractCsrf(r) {
  try {
    const value = r.html().find('input[name="csrf"]').first().attr('value');
    if (value) return value;
  } catch (_) {}

  const html = r.body || '';
  const re = /<input[^>]+name=["']csrf["'][^>]*>/gi;
  let match;
  while ((match = re.exec(html)) !== null) {
    const val = match[0].match(/value=["']([^"']+)["']/i);
    if (val) return val[1];
  }
  return '';
}

function raw(pathOrUrl, method = 'GET', data = null, extra = {}) {
  const url = /^https?:\/\//.test(pathOrUrl) ? pathOrUrl : base + pathOrUrl;
  const headers = Object.assign(
    { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    extra
  );

  const r = http.request(method, url, data === null ? null : JSON.stringify(data), {
    headers,
    redirects: 0,
    timeout: '3s',
  });

  const b = body(r);
  if (b.csrf) csrf = b.csrf;

  if (pathOrUrl === '/v2/work') {
    businessFailure.add(
      r.status >= 400 &&
      !(r.status === 401 && b.error === 'expired') &&
      r.status !== 429
    );
  }

  return r;
}

function login() {
  let r = raw('/v2/login-form');
  const token = extractCsrf(r);
  const row = rows[(__VU - 1) % rows.length];

