    {"username": "bench-14", "password": "bench", "quantity": 15},
    {"username": "bench-15", "password": "bench", "quantity": 16},
    {"username": "bench-16", "password": "bench", "quantity": 17},
]


class MatrixUser(HttpUser):
    wait_time = lambda self: 0

    SERIAL = 0
    SPAWNED = 0
    ACTIVE_USERS = 0
    LOCK = Semaphore()

    def on_start(self):
        with MatrixUser.LOCK:
            MatrixUser.SERIAL += 1
            MatrixUser.SPAWNED += 1
            MatrixUser.ACTIVE_USERS += 1
            number = MatrixUser.SERIAL

        self.row = ROWS[(number - 1) % len(ROWS)]
        self.username = 'bench-' + str((number - 1) % 16 + 1)
        self.password = self.row.get('password', 'bench')
        self.csrf = ''
        self.cart = ''
        self.etag = ''
        self.grant = ''
        self.iteration = 0

    def on_stop(self):
        with MatrixUser.LOCK:
            MatrixUser.ACTIVE_USERS -= 1

    def raw(self, path, method='GET', data=None, headers=None, name=None):
        request_headers = {'Content-Type': 'application/json'}
        if self.csrf:
            request_headers['X-CSRF-Token'] = self.csrf
        request_headers.update(headers or {})

        with self.client.request(
            method,
            path,
            json=data,
            headers=request_headers,
            name=name,
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            try:
                body = response.json()
                if not isinstance(body, dict):
                    body = {}
            except ValueError:
                body = {}

            allowed = response.status_code < 400

            if response.status_code == 401:
                allowed = body.get('error') == 'expired'

            if (
                path.split('?', 1)[0] == '/v2/orders'
                and method == 'POST'
                and response.status_code < 400
                and body.get('accepted') is not True
            ):
                allowed = False

            if (
                path.split('?', 1)[0] in ('/v2/work', '/v2/browse')
                and response.status_code == 429
            ):
                allowed = True

            if name == 'checkout' and response.elapsed.total_seconds() * 1000 >= 250:
                allowed = False

            if allowed:
                response.success()
            else:
                response.failure('request assertion failed')

            if body.get('csrf'):
                self.csrf = body['csrf']

            return response, body

    def request(self, path, method='GET', data=None, headers=None, name=None):
        response, body = self.raw(path, method, data, headers, name)

        if response.status_code == 401 and body.get('error') in ('expired', 'session'):
            if body.get('error') == 'expired':
                renewed, _ = self.raw('/v2/session/renew', 'POST', {})
                if renewed.status_code == 200:
                    if self.cart:
                        recovered, _ = self.raw(
                            '/v2/carts/' + self.cart + '/recover', 'POST', {}
                        )
                        self.etag = recovered.headers.get('ETag', self.etag)

                    retry_headers = dict(headers or {})
                    if 'If-Match' in retry_headers:
                        retry_headers['If-Match'] = self.etag or retry_headers['If-Match']
                    return self.raw(path, method, data, retry_headers, name)

            self.login()
            if self.cart:
                recovered, _ = self.raw('/v2/carts/' + self.cart + '/recover', 'POST', {})
                self.etag = recovered.headers.get('ETag', self.etag)

            retry_headers = dict(headers or {})
            if 'If-Match' in retry_headers:
                retry_headers['If-Match'] = self.etag or retry_headers['If-Match']
            return self.raw(path, method, data, retry_headers, name)

        return response, body

    def login(self):
        self.client.cookies.clear()
        self.csrf = ''

        form, _ = self.raw('/v2/login-form')
        token = re.search(
            r'<input(?=[^>]*\bname=["\']csrf["\'])(?=[^>]*\bvalue=["\']([^"\']+)["\'])[^>]*>',
            form.text,
            re.IGNORECASE,
        )
        if not token:
            return

        response, body = self.raw(
            '/v2/login',
            'POST',
            {
                'username': self.username,
                'password': self.password,
                'csrf': token.group(1),
            },
        )

        if response.status_code == 302:
            location = response.headers.get('Location')
            if location:
                _, body = self.raw(location)

        self.grant = body.get('grant_id', '')

    def flow(self):
        self.client.cookies.clear()
        self.cart = ''
        self.etag = ''
        self.grant = ''
        self.login()

        _, body = self.request('/v2/catalog')
        products = body.get('data', {}).get('products', [])
        product = next(
            (
                item
                for item in products
                if any(variant.get('in_stock') for variant in item.get('variants', []))
            ),
            None,
        )
        if not product:
            return

        variant = next(item for item in product['variants'] if item.get('in_stock'))

        response, body = self.request(
            '/v2/carts',
            'POST',
            {
                'product_id': product['id'],
                'variant_id': variant['id'],
                'grant_id': self.grant,
            },
        )
        self.cart = body.get('id', '')
        self.etag = response.headers.get('ETag', '')
        if not self.cart:
            return

        headers = {'Idempotency-Key': self.cart, 'If-Match': self.etag}
        self.request(
            '/v2/orders',
            'POST',
            {'cart_id': self.cart},
            headers,
            'checkout' if MODE == 'threshold' else None,
        )

    def work(self, path='/v2/work'):
        if not self.csrf:
            self.login()

        for _ in range(5):
            response, _ = self.request(path, 'POST', {})
            if response.status_code != 429:
                return
            sleep(float(response.headers.get('Retry-After', 0.01)) + 0.01)

    @task
    def run_scenario(self):
        if MODE == 'errors':
            self.login()
            for _ in range(4):
                self.work()
        else:
            self.flow()

        self.iteration += 1
        if self.iteration >= CFG.get('iterations', 2):
            raise StopUser()


class MatrixShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.first_tick = True

    def tick(self):
        users = CFG.get('users', 2)

        if self.first_tick:
            self.first_tick = False
            return users, max(1, users)

        if MatrixUser.SPAWNED < users and self.get_run_time() < 10:
            return users, max(1, users)

        if MatrixUser.ACTIVE_USERS == 0:
            return None

        return MatrixUser.ACTIVE_USERS, max(1, MatrixUser.ACTIVE_USERS)
