import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
const users = [
  'bench-1', 'bench-2', 'bench-3', 'bench-4',
  'bench-5', 'bench-6', 'bench-7', 'bench-8',
  'bench-9', 'bench-10', 'bench-11', 'bench-12',
  'bench-13', 'bench-14', 'bench-15', 'bench-16'
];

const failure = new Rate('business_failure');

let csrf = '';
let authed = false;

function resolveUrl(pathOrUrl) {
  if (/^https?:\/\//i.test(pathOrUrl)) return pathOrUrl;
  return base + (pathOrUrl.startsWith('/') ? pathOrUrl : '/' + pathOrUrl);
}

function jsonBody(r) {
  try { return r.json(); } catch (_) { return {}; }
}

function extractCsrf(r) {
  const inputs = r.html().find('input[name="csrf"]').toArray();
  for (const el of inputs) {
    const v = el.getAttribute('value');
    if (v && v.length > 0) return v;
  }

  let m = r.body.match(/<input[^>]+name=["']csrf["'][^>]+value=["']([^"']+)["']/i);
  if (m) return m[1];
  m = r.body.match(/<input[^>]+value=["']([^"']+)["'][^>]+name=["']csrf["']/i);
  return m ? m[1] : '';
}

function request(pathOrUrl, method = 'GET', data = null, extra = {}) {
  const headers = Object.assign({}, extra);
  if (method !== 'GET') headers['X-CSRF-Token'] = csrf;
  if (data !== null) headers['Content-Type'] = 'application/json';

  const r = http.request(method, resolveUrl(pathOrUrl), data === null ? null : JSON.stringify(data), {
    headers,
    redirects: 0,
    timeout: '5s'
  });

  const b = jsonBody(r);
  if (b.csrf) csrf = b.csrf;

  if (pathOrUrl === '/v2/work' || pathOrUrl.endsWith('/v2/work')) {
    const ok = r.status === 200 && b.ok === true;
    const expectedThrottle = r.status === 429;
    const expectedAuth = r.status === 401 && ['expired', 'session'].indexOf(b.error) >= 0;
    failure.add(!ok && !expectedThrottle && !expectedAuth);
  }

  return r;
}

function login() {
  csrf = '';
  authed = false;

  let r = request('/v2/login-form');
  const token = extractCsrf(r);
  const username = users[(__VU - 1) % users.length];

  r = request('/v2/login', 'POST', { username, password: 'bench', csrf: token });
  if (r.status === 302) {
    r = request(r.headers.Location);
    const b = jsonBody(r);
    if (b.csrf) csrf = b.csrf;
  }

  if (r.status === 200) authed = true;
  check(r, { 'login': (r) => r.status === 200 });
}

function ensureSession() {
  if (!authed || !csrf) login();
}

function work() {
  ensureSession();

  let r = request('/v2/work', 'POST', {});
  for (let n = 0; n < 4 && r.status === 429; n++) {
    const retryAfter = Number(r.headers['Retry-After']) || 1;
    sleep(retryAfter + 0.01);
    r = request('/v2/work', 'POST', {});
  }

  if (r.status === 401) {
    const b = jsonBody(r);
    if (['expired', 'session'].indexOf(b.error) >= 0) {
      const renewed = request('/v2/session/renew', 'POST', {});
      if (renewed.status !== 200) login();

      r = request('/v2/work', 'POST', {});
      for (let n = 0; n < 4 && r.status === 429; n++) {
        const retryAfter = Number(r.headers['Retry-After']) || 1;
        sleep(retryAfter + 0.01);
        r = request('/v2/work', 'POST', {});
      }
    }
  }

  check(r, {
    'work': (r) => (r.status === 200 && jsonBody(r).ok === true) || r.status === 429
  });
}

export const options = {
  scenarios: {
    phase0: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '40s',
      startTime: '0s',
      preAllocatedVUs: 10,
      maxVUs: 32,
      gracefulStop: '5s'
    }
  },
  thresholds: {
    checks: ['rate>=0.99'],
    business_failure: ['rate<=0.01']
  },
  noCookiesReset: true
};

export default work;
