let csrf = '';
let cart = '';
let grant = '';

function body(r) { try { return r.json(); } catch (_) { return {}; } }

function resolveUrl(u) {
  if (!u) return base + '/';
  if (/^https?:\/\//i.test(u)) return u;
  return base + (u.indexOf('/') === 0 ? u : '/' + u);
}

function raw(urlOrPath, method='GET', data=null, extra={}) {
  const url = resolveUrl(urlOrPath);
  const headers = {'X-CSRF-Token': csrf};
  if (extra) {
    for (const key of Object.keys(extra)) {
      const value = extra[key];
      if (value !== undefined && value !== null) headers[key] = value;
    }
  }
  if (data !== null) headers['Content-Type'] = 'application/json';
  const r = http.request(method, url, data === null ? null : JSON.stringify(data), {
    headers: headers,
    redirects: 0,
    timeout: '3s'
