    failure.add(r.status >= 400 && !(r.status === 401 && b.error === 'expired') && r.status !== 429);
  }
  return r;
}

function login(account) {
  let r = raw('/v2/login-form');
  const token = r.html().find('input[name="csrf"]').first().attr('value');
  if (!token) {
    check(false, {'login csrf token found': x => x});
    return false;
  }
  r = raw('/v2/login', 'POST', {username: account.username, password: account.password, csrf: token});
  if (r.status === 302) {
    r = raw(r.headers.Location);
    const b = body(r);
    if (b.grant_id) grant = b.grant_id;
  }
  check(r, {'login': r => r.status === 200});
  return r.status === 200;
}

