import csv
import json
import os
import re

from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

CFG = {'users': 2, 'iterations': 2, 'mode': 'partition'}

JSON_FIXTURE_PATHS = (
    '/fixtures/accounts.json',
    '/fixtures/r10-accounts.json',
)
CSV_FIXTURE_GROUPS = (
    ('/fixtures/account-1.csv', '/fixtures/account-2.csv'),
    ('/fixtures/r10-account-1.csv', '/fixtures/r10-account-2.csv'),
)


def _pad_rows(rows):
    while len(rows) < CFG.get('users', 2):
        candidate = 'bench-%d' % (len(rows) + 1)
        if any(row.get('username') == candidate for row in rows):
            candidate = 'bench-%d' % (len(rows) + 2)
        rows.append({'username': candidate, 'password': 'bench',
                     'quantity': 2, 'delay': 0})
    return rows


def load_account_rows():
    for path in JSON_FIXTURE_PATHS:
        if os.path.exists(path):
            with open(path, encoding='utf-8') as f:
                data = json.load(f)
            if isinstance(data, list) and data:
                return _pad_rows(data)

    rows = []
    for path1, path2 in CSV_FIXTURE_GROUPS:
        if not os.path.exists(path1) and not os.path.exists(path2):
            continue
        for path in (path1, path2):
            if os.path.exists(path):
                with open(path, encoding='utf-8', newline='') as f:
                    for row in csv.DictReader(f):
                        if row:
                            rows.append(row)
        if rows:
            return _pad_rows(rows)

    rows = [
        {'username': 'bench-1', 'password': 'bench', 'quantity': 2, 'delay': 0},
        {'username': 'bench-2', 'password': 'bench', 'quantity': 3, 'delay': 500},
    ]
    return _pad_rows(rows)


ROWS = load_account_rows()


class MatrixUser(HttpUser):
    wait_time = lambda self: 0

    def on_start(self):
        worker_id = getattr(self, '_p95_worker_id', '')
        try:
            number = int(worker_id.rsplit('-', 1)[1])
        except Exception:
            number = self.environment.runner.user_count

        self.row = ROWS[(number - 1) % len(ROWS)]
        self.username = self.row.get('username') or ('bench-%d' % number)
        self.password = self.row.get('password', 'bench')
        self.csrf = ''
        self.cart = ''
        self.etag = ''
        self.grant = ''
        self.iteration = 0

    def raw(self, path, method='GET', data=None, headers=None, name=None):
        request_headers = {'Content-Type': 'application/json'}
        if self.csrf:
            request_headers['X-CSRF-Token'] = self.csrf
        request_headers.update(headers or {})

        with self.client.request(method, path, json=data, headers=request_headers,
                                 name=name, catch_response=True, allow_redirects=False,
                                 timeout=3) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}

            error = body.get('error')
            allowed = (
                response.status_code < 400
                or response.status_code == 401 and error in ('expired', 'session')
                or response.status_code == 412 and error in ('etag', 'etag_conflict')
                or response.status_code == 429 and path.split('?', 1)[0] == '/v2/work'
            )

            if (
                (
                    path.startswith('/v2/jobs/')
                    and response.status_code < 400
                    and body.get('status') == 'failed'
                )
                or (
                    path.split('?', 1)[0] == '/v2/orders'
                    and method == 'POST'
                    and response.status_code < 400
                    and body.get('accepted') is not True
                )
            ):
                allowed = False

            if name == 'checkout' and response.elapsed.total_seconds() * 1000 >= 250:
                allowed = False

            if allowed:
                response.success()
            else:
                response.failure('request assertion failed')
                self.environment.process_exit_code = 99

            if body.get('csrf'):
                self.csrf = body['csrf']

            return response, body

    def login(self):
        self.csrf = ''
        form, _ = self.raw('/v2/login-form')
        token = re.search(
            r'<input(?=[^>]*\bname=["\']csrf["\'])(?=[^>]*\bvalue=["\']([^"\']+)["\'])[^>]*>',
            form.text,
            re.IGNORECASE,
        )
        if not token:
            self.environment.process_exit_code = 99
            return

        response, body = self.raw(
            '/v2/login',
            'POST',
            {'username': self.username, 'password': self.password, 'csrf': token.group(1)},
        )
        if response.status_code == 302:
            location = response.headers.get('Location')
            if location:
                _, body = self.request(location)
        self.grant = body.get('grant_id', '')

    def recover(self):
        renewed, _ = self.raw('/v2/session/renew', 'POST', {})
        if renewed.status_code != 200:
            self.login()
            if not self.csrf:
                return
        if self.cart:
            response, _ = self.raw('/v2/carts/' + self.cart + '/recover', 'POST', {})
            self.etag = response.headers.get('ETag', self.etag)

    def request(self, path, method='GET', data=None, headers=None, name=None):
        for _ in range(2):
            response, body = self.raw(path, method, data, headers, name)
            if response.status_code == 401 and body.get('error') in ('expired', 'session'):
                self.recover()
                continue
            return response, body
        return response, body

    def flow(self):
        self.client.cookies.clear()
        self.cart = ''
        self.etag = ''
        self.grant = ''
        self.login()
        if not self.csrf:
            return

        page = '/v2/catalog'
        product = None
        for _ in range(3):
            _, body = self.request(page)
            products = body.get('data', {}).get('products', [])
            product = next(
                (
                    item
                    for item in products
                    if any(variant.get('in_stock') for variant in item.get('variants', []))
                ),
                None,
            )
            if product:
                break
            page = body.get('next')
            if not page:
                break

        if not product:
            self.environment.process_exit_code = 99
            return

        variant = next(item for item in product['variants'] if item.get('in_stock'))
        cart_payload = {'product_id': product['id'], 'variant_id': variant['id']}
        if self.grant:
            cart_payload['grant_id'] = self.grant

        response, body = self.request('/v2/carts', 'POST', cart_payload)
        self.cart = body.get('id', '')
        self.etag = response.headers.get('ETag', '')
        if not self.cart:
            self.environment.process_exit_code = 99
            return

        order_payload = {'cart_id': self.cart}
        order_headers = {'Idempotency-Key': self.cart, 'If-Match': self.etag}
        response, _ = self.request('/v2/orders', 'POST', order_payload, order_headers)

        if response.status_code == 412:
            response, _ = self.request('/v2/carts/' + self.cart)
            self.etag = response.headers.get('ETag', self.etag)
            self.request(
                '/v2/orders',
                'POST',
                order_payload,
                {'Idempotency-Key': self.cart, 'If-Match': self.etag},
            )

    @task
    def run_scenario(self):
        self.flow()
        self.iteration += 1
        if self.iteration >= CFG.get('iterations', 2):
            raise StopUser()


class MatrixShape(LoadTestShape):
