import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const cfg = { users: 2, iterations: 2, mode: 'errors' };
const rows = Array.from({ length: 16 }, (_, i) => ({
  username: `bench-${i + 1}`,
  password: 'bench',
}));

const failure = new Rate('business_failure');

const base = __ENV.BASE_URL || 'http://127.0.0.1:8000';
let csrf = '';
let cart = '';

function absoluteUrl(path) {
  if (/^https?:\/\//i.test(path)) return path;
  return base + path;
}

function body(r) {
  try {
    return r.json();
  } catch (_) {
    return {};
  }
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const r = http.request(method, absoluteUrl(path), data === null ? null : JSON.stringify(data), {
    headers: Object.assign({ 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }, extra),
    redirects: 0,
    timeout: '3s',
  });

  const b = body(r);
  if (b.csrf) csrf = b.csrf;

  if (path === '/v2/work') {
    const ok = r.status === 200 && b.ok === true;
    const expectedThrottle = r.status === 429;
    const expectedExpiry = r.status === 401 && b.error === 'expired';
    failure.add(!ok && !expectedThrottle && !expectedExpiry);
  }

  return r;
}

function login() {
  let r = raw('/v2/login-form');
  const token = r.html().find('input[name="csrf"]').first().attr('value');
  const row = rows[(__VU - 1) % rows.length];

  r = raw('/v2/login', 'POST', {
    username: row.username,
    password: row.password,
    csrf: token,
  });

  if (r.status === 302) {
    r = raw(r.headers.Location);
  }

  check(r, { login: (r) => r.status === 200 });
}

function request(path, method = 'GET', data = null, extra = {}) {
  let r = raw(path, method, data, extra);

  if (r.status === 401 && ['expired', 'session'].indexOf(body(r).error) >= 0) {
    const renewed = raw('/v2/session/renew', 'POST', {});
    if (renewed.status !== 200) login();
    if (cart) raw(`/v2/carts/${cart}/recover`, 'POST', {});
    r = raw(path, method, data, extra);
  }

  return r;
}

function work() {
  if (!csrf) login();

  let r = request('/v2/work', 'POST', {});

  for (let retries = 0; retries < 4 && r.status === 429; retries++) {
    const retryAfter = Number(r.headers['Retry-After']);
    sleep((Number.isNaN(retryAfter) ? 1 : retryAfter) + 0.01);
    r = request('/v2/work', 'POST', {});
  }

  check(r, { work: (r) => r.status === 200 && body(r).ok === true });
}

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: cfg.users,
      iterations: cfg.iterations,
      maxDuration: '30s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
    business_failure: ['rate==0'],
  },
};

export default function () {
  login();
  for (let n = 0; n < 4; n++) work();
}

