import http from 'k6/http';
import { sleep, check } from 'k6';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const ACCOUNTS = [
  ...Array.from({ length: 16 }, (_, i) => `bench-${i + 1}`),
  'bench',
];
const USERNAME = ACCOUNTS[((__VU || 1) - 1) % ACCOUNTS.length];

let csrf = null;
let loggedIn = false;

function attrValue(tag, attrName) {
  const pattern = new RegExp('(?:^|\\s)' + attrName + '\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  const m = tag.match(pattern);
  if (m) {
    if (m[1] !== undefined) return m[1];
    if (m[2] !== undefined) return m[2];
    if (m[3] !== undefined) return m[3];
  }
  return undefined;
}

function extractCsrfFromHtml(html) {
  const inputRe = /<input\b[^>]*>/gi;
  let m;
  while ((m = inputRe.exec(html)) !== null) {
    const tag = m[0];
    if (attrValue(tag, 'name') === 'csrf') {
      const value = attrValue(tag, 'value');
      if (value !== undefined) return value;
    }
  }
  return '';
}

function updateCsrfFromResponse(res) {
  const contentType = (res.headers['Content-Type'] || '').toLowerCase();
  if (contentType.includes('application/json')) {
    try {
      const data = res.json();
      if (data && data.csrf) {
        csrf = data.csrf;
      }
    } catch (e) {
      // ignore non-json or missing csrf
    }
  }
}

function login() {
  for (let attempt = 0; attempt < 3; attempt++) {
    const formRes = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
    if (formRes.status !== 200) {
      check(formRes, { 'login form status 200': (r) => r.status === 200 });
      sleep(0.1);
      continue;
    }

    const formCsrf = extractCsrfFromHtml(formRes.body || '');
    if (!formCsrf) {
      check(formRes, { 'login form csrf present': () => false });
      sleep(0.1);
      continue;
    }

    const payload = JSON.stringify({ username: USERNAME, password: 'bench', csrf: formCsrf });
    let loginRes = http.post(`${BASE_URL}/v2/login`, payload, {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
    });

    if (loginRes.status === 302) {
      const location = loginRes.headers['Location'];
      if (!location) {
        check(loginRes, { 'login 302 location present': () => false });
        sleep(0.1);
        continue;
      }

      const base = BASE_URL.replace(/\/$/, '');
      const locationUrl = location.startsWith('http')
        ? location
        : `${base}${location.startsWith('/') ? location : '/' + location}`;

      loginRes = http.get(locationUrl, { redirects: 0 });
      updateCsrfFromResponse(loginRes);
    } else if (loginRes.status === 200) {
      updateCsrfFromResponse(loginRes);
    } else {
      check(loginRes, { 'login status 200 or 302': (r) => r.status === 200 || r.status === 302 });
      sleep(0.1);
      continue;
    }

    if (!csrf) {
      csrf = formCsrf;
    }

    return true;
  }

  return false;
}

function handle401(workRes) {
  let error = '';
  try {
    error = workRes.json('error') || '';
  } catch (e) {
    // ignore parse errors
  }

  if (error === 'expired') {
    const renewRes = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
      headers: { 'X-CSRF-Token': csrf, 'Content-Type': 'application/json' },
      redirects: 0,
    });
    updateCsrfFromResponse(renewRes);
    return renewRes.status < 400;
  }

  if (error === 'session') {
    const ok = login();
    if (ok) {
      loggedIn = true;
      return true;
    }
    return false;
  }

  if (error === 'denied') {
    check(workRes, { '401 denied not expected': () => false });
    return false;
  }

  check(workRes, { '401 unexpected': () => false });
  return false;
}

function doWork() {
  let retries429 = 0;
  let handled401 = false;

  while (true) {
    const res = http.post(`${BASE_URL}/v2/work`, '{}', {
      headers: { 'X-CSRF-Token': csrf, 'Content-Type': 'application/json' },
      redirects: 0,
    });
    updateCsrfFromResponse(res);

    if (res.status === 200) {
      let ok = false;
      try {
        ok = res.json('ok') === true;
      } catch (e) {
        ok = false;
      }
      check(res, { 'work status 200': (r) => r.status === 200 });
      check(res, { 'work ok true': () => ok });
      return ok;
    }

    if (res.status === 429) {
      if (retries429 < 4) {
        retries429++;
