import http from 'k6/http';
import { sleep } from 'k6';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
const USER_COUNT = 8;

export const options = {
  scenarios: {
    work_pool: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '38s',
      preAllocatedVUs: USER_COUNT,
      maxVUs:USER_COUNT,
    },
  },
};

function parseJson(res) {
  if (!res.body) return null;
  try {
    return JSON.parse(res.body);
  } catch (e) {
    return null;
  }
}

function decodeEntities(value) {
  return String(value)
    .replace(/&quot;/gi, '"')
    .replace(/&#x27;/gi, "'")
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}

function getAttr(tag, attrName) {
  const re = new RegExp(
    '\\b' + attrName + '\\s*=\\s*(?:"([^"]*)"|' + "'([^']*)'" + '|([^\\s>]+))',
    'i'
  );
  const m = tag.match(re);
  if (m) {
    if (m[1] !== undefined) return m[1];
    if (m[2] !== undefined) return m[2];
    if (m[3] !== undefined) return m[3];
  }
  return null;
}

function extractCsrfFromHtml(res) {
  const body = res.body;
  if (!body) return null;
  const inputRe = /<input\b[^>]*>/gi;
  let m;
  while ((m = inputRe.exec(body)) !== null) {
    const tag = m[0];
    const name = getAttr(tag, 'name');
    if (name && name.toLowerCase() === 'csrf') {
      const value = getAttr(tag, 'value');
      if (value !== null && value !== '') {
        return decodeEntities(value);
      }
    }
  }
  return null;
}

function extractCsrfFromResponse(res, fallback) {
  const data = parseJson(res);
  if (data && data.csrf) return data.csrf;
  const htmlCsrf = extractCsrfFromHtml(res);
  if (htmlCsrf) return htmlCsrf;
  return fallback;
}

function resolveUrl(loc) {
  if (!loc) return null;
  if (/^https?:\/\//i.test(loc)) return loc;
  if (loc.startsWith('/')) return BASE_URL + loc;
  return BASE_URL + '/' + loc;
}

function requestHeaders(csrf) {
  return {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
  };
}

function normalizeCookies(raw) {
  if (!raw) return [];

  if (Array.isArray(raw)) {
    const out = [];
    for (const c of raw) {
      if (c && c.name && c.value !== undefined && c.value !== null) {
        out.push({ name: String(c.name), value: String(c.value) });
      }
    }
    return out;
  }

  if (typeof raw === 'object') {
    const out = [];
    for (const name of Object.keys(raw)) {
      const val = raw[name];
      if (val !== undefined && val !== null) {
        let value = String(val);
        if (typeof val === 'object' && val.value !== undefined && val.value !== null) {
          value = String(val.value);
        }
        out.push({ name: String(name), value: value });
      }
    }
    return out;
  }

  return [];
}

function seedCookies(session) {
  const jar = http.cookieJar();
  try {
    jar.clear(BASE_URL);
  } catch (e) {}

  for (const cookie of session.cookies) {
    if (cookie && cookie.name) {
      try {
        jar.set(BASE_URL, cookie.name, cookie.value || '');
      } catch (e) {}
    }
  }
}

function getLoginFormCsrf() {
  let res = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });

  if (res.status >= 300 && res.status < 400) {
    const loc = resolveUrl(res.headers['Location']);
    if (!loc) throw new Error('login-form 302 without Location');
    res = http.get(loc, { redirects: 0 });
  }

  if (res.status < 200 || res.status >= 400) {
    throw new Error(`login-form failed ${res.status}: ${res.body}`);
  }

  const csrf = extractCsrfFromHtml(res);
  if (!csrf) throw new Error('login-form csrf missing');
  return csrf;
}

function login(user) {
  try {
    http.cookieJar().clear(BASE_URL);
  } catch (e) {}

  const loginFormCsrf = getLoginFormCsrf();

  let res = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username: user, password: 'bench', csrf: loginFormCsrf }),
    { redirects: 0, headers: requestHeaders(loginFormCsrf) }
  );

  if (res.status >= 300 && res.status < 400) {
    const loc = resolveUrl(res.headers['Location']);
    if (!loc) throw new Error('login 302 without Location');
    res = http.get(loc, { redirects: 0 });
  }

  if (res.status < 200 || res.status >= 400) {
    throw new Error(`login failed ${res.status}: ${res.body}`);
  }

  return extractCsrfFromResponse(res, loginFormCsrf);
}

function renewSession(csrf) {
  const res = http.post(
    `${BASE_URL}/v2/session/renew`,
    JSON.stringify({}),
    { redirects: 0, headers: requestHeaders(csrf) }
  );

  if (res.status < 200 || res.status >= 400) {
    throw new Error(`session renew failed ${res.status}: ${res.body}`);
  }

  return extractCsrfFromResponse(res, csrf);
}

function recover401(res, csrf, user) {
  const data = parseJson(res);
  const error = data && data.error ? String(data.error).toLowerCase() : '';

  if (error === 'denied') {
    return { ok: false, csrf: csrf };
  }

  if (error === 'expired') {
    try {
      const fresh = renewSession(csrf);
      return { ok: true, csrf: fresh };
    } catch (e) {
      const fresh = login(user);
      return { ok: true, csrf: fresh };
    }
  }

  const fresh = login(user);
  return { ok: true, csrf: fresh };
}

function postWork(csrf, user) {
  let currentCsrf = csrf;
  let retried401 = false;
  let attempts429 = 0;

  while (true) {
    const res = http.post(
      `${BASE_URL}/v2/work`,
      JSON.stringify({}),
      { redirects: 0, headers: requestHeaders(currentCsrf) }
    );

    if (res.status === 401) {
      if (retried401) {
        throw new Error(`work 401 after recovery: ${res.body}`);
      }

      const recovery = recover401(res, currentCsrf, user);
      if (!recovery.ok) {
        throw new Error(`work 401 denied: ${res.body}`);
      }

      currentCsrf = recovery.csrf;
      retried401 = true;
      continue;
    }

    if (res.status === 429) {
      if (attempts429 >= 4) {
        throw new Error('too many scheduled 429 retries');
      }

      attempts429 += 1;
      const retryAfter = parseFloat(res.headers['Retry-After'] || '1');
      sleep(retryAfter > 0 ? retryAfter : 1);
      continue;
    }

    if (res.status < 200 || res.status >= 400) {
      throw new Error(`work failed ${res.status}: ${res.body}`);
    }

    const data = parseJson(res);
    if (!data || data.ok !== true) {
      throw new Error(`work returned not ok: ${res.body}`);
    }

    return extractCsrfFromResponse(res, currentCsrf);
  }
}

export function setup() {
  const sessions = [];

  for (let i = 0; i < USER_COUNT; i++) {
    const user = `bench-${i + 1}`;
    const csrf = login(user);
    const rawCookies = http.cookieJar().cookiesForURL(BASE_URL);

    sessions.push({
      user: user,
      csrf: csrf,
      cookies: normalizeCookies(rawCookies),
    });
  }

  return { sessions: sessions };
}

let authed = false;
let currentCsrf = null;
let currentUser = null;

export default function (data) {
  try {
    if (!authed) {
      const sessions = data.sessions;
      const idx = ((__VU - 1) % sessions.length + sessions.length) % sessions.length;
      const session = sessions[idx];

      currentUser = session.user;
      seedCookies(session);
      currentCsrf = session.csrf;
      authed = true;
    }

    currentCsrf = postWork(currentCsrf, currentUser);
  } catch (e) {
    authed = false;
    currentCsrf = null;
    currentUser = null;
    throw e;
  }
}

