        if not name_match or name_match.group(2) != "csrf":
            continue
        value_match = re.search(r"\bvalue\s*=\s*([\"']?)([^\"'\s>/]+)\1", tag, re.I)
        if value_match:
            return value_match.group(2)
    return None


def extract_csrf(resp):
    data = get_json(resp)
    if isinstance(data, dict):
        csrf = data.get("csrf")
        if csrf:
            return csrf
    return parse_csrf_from_html(resp.text)


class WorkUser(HttpUser):
    wait_time = constant_pacing(CYCLE_SECONDS)

    def on_start(self):
        global USER_SEQUENCE
        USER_SEQUENCE += 1
        self.username = f"bench-{(USER_SEQUENCE - 1) % 16 + 1}"
        self.csrf = None
        self.logged_in = False
        if not self._login():
            raise StopUser()

    def _login(self):
        for _ in range(3):
            with self.client.get(
                "/v2/login-form",
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code != 200:
                    resp.failure(f"login-form status {resp.status_code}")
                    gsleep(0.2)
                    continue
                csrf = parse_csrf_from_html(resp.text)
                if not csrf:
                    resp.failure("login-form csrf missing")
                    gsleep(0.2)
                    continue

            headers = {"X-CSRF-Token": csrf}
            with self.client.post(
                "/v2/login",
                json={"username": self.username, "password": "bench", "csrf": csrf},
                headers=headers,
                allow_redirects=False,
                catch_response=True,
            ) as login_resp:
                if login_resp.status_code == 302:
                    loc = login_resp.headers.get("Location")
                    if not loc:
                        login_resp.failure("login 302 missing Location")
                        gsleep(0.2)
                        continue

                    next_url = urljoin(BASE_URL, loc)
                    with self.client.get(
                        next_url,
                        allow_redirects=False,
                        catch_response=True,
                    ) as redirect_resp:
                        if redirect_resp.status_code in (200, 201):
                            new_csrf = extract_csrf(redirect_resp)
                            if new_csrf:
                                self.csrf = new_csrf
                                self.logged_in = True
                                return True
                            redirect_resp.failure("login redirect csrf missing")
                            gsleep(0.2)
                            continue
                        redirect_resp.failure(f"login redirect status {redirect_resp.status_code}")
                        gsleep(0.2)
                        continue

                if login_resp.status_code in (200, 201):
                    data = get_json(login_resp)
                    new_csrf = extract_csrf(login_resp)
                    if isinstance(data, dict) and data.get("csrf"):
                        new_csrf = data["csrf"]
                    if new_csrf:
                        self.csrf = new_csrf
                        self.logged_in = True
                        return True
                    login_resp.failure("login csrf missing")
                    gsleep(0.2)
                    continue

                login_resp.failure(f"login status {login_resp.status_code}")
                gsleep(0.2)

        return False

    def _fresh_login(self):
        return self._login()

    def _error_from(self, resp):
        data = get_json(resp)
        if isinstance(data, dict):
            return data.get("error")
        return None

    def _renew_session(self):
        if not self.csrf:
            return self._fresh_login()

        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 200:
                data = get_json(resp)
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                return True

            if resp.status_code == 401:
                error = self._error_from(resp)
                if error == "session":
                    return self._fresh_login()
                return self._fresh_login()

            resp.failure(f"renew status {resp.status_code}")
            return False

    @task
    def work(self):
        global FIRST_WORK_AT
        if FIRST_WORK_AT is None:
            FIRST_WORK_AT = time.time()
        self._do_work()

    def _do_work(self):
        for _ in range(MAX_WORK_ATTEMPTS):
            if not self.csrf and not self._fresh_login():
                return False

            with self.client.post(
                "/v2/work",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 200:
                    data = get_json(resp)
                    if isinstance(data, dict) and data.get("ok") is True:
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                        return True
                    resp.failure("work ok false")
                    return False

                if resp.status_code == 429:
                    # Scheduled 429 is expected, not a failure; retry after 1s.
                    gsleep(1)
                    continue

                if resp.status_code == 401:
                    error = self._error_from(resp)
                    if error == "expired":
                        if self._renew_session():
                            continue
                        resp.failure("work expired recovery failed")
                        return False
                    if error == "session":
                        if self._fresh_login():
                            continue
                        resp.failure("work session recovery failed")
                        return False
                    resp.failure(f"work 401 denied/unknown {error}")
                    return False

                resp.failure(f"unexpected work status {resp.status_code}")
                return False

        return False


class WorkShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()

        if FIRST_WORK_AT is None:
            if run_time > 15:
                return None
            return (USER_COUNT, USER_COUNT)

        stop_at = FIRST_WORK_AT + WORK_TOTAL_SECONDS
