import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {

    private static final int WORKERS = 16;
    private static final long PERIOD_MS = 2000L;
    private static final int ITERATIONS = 18;

    private static final AtomicInteger USER_COUNTER = new AtomicInteger(0);
    private static volatile long T0_TARGET_MS = 0L;

    private static final Pattern INPUT_TAG =
        Pattern.compile("<input\\b([^>]*)>", Pattern.CASE_INSENSITIVE);

    private static final Pattern ATTRIBUTE =
        Pattern.compile("\\b([^\\s>]+)\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))", Pattern.CASE_INSENSITIVE);

    private static int statusOf(Session session, String key) {
        Object value = session.get(key);
        if (value == null) return -1;
        if (value instanceof Number) return ((Number) value).intValue();
        try {
            return Integer.parseInt(value.toString().trim());
        } catch (NumberFormatException nfe) {
            return -1;
        }
    }

    private static int retry429Count(Session session) {
        Object value = session.get("work429Retries");
        if (value == null) return 0;
        if (value instanceof Number) return ((Number) value).intValue();
        try {
            return Integer.parseInt(value.toString().trim());
        } catch (NumberFormatException nfe) {
            return 0;
        }
    }

    private static String jsonEscape(String value) {
        if (value == null) return "";
        return value.replace("\\", "\\\\").replace("\"", "\\\"");
    }

    private static String getAttributeValue(String tag, String attribute) {
        Matcher m = ATTRIBUTE.matcher(tag);
        while (m.find()) {
            String name = m.group(1);
            if (attribute.equalsIgnoreCase(name)) {
                return m.group(2) != null ? m.group(2) : m.group(3) != null ? m.group(3) : m.group(4);
            }
        }
        return null;
    }

    private static boolean attributeHasValue(String tag, String attribute, String expected) {
        Matcher m = ATTRIBUTE.matcher(tag);
        while (m.find()) {
            String name = m.group(1);
            String value = m.group(2) != null ? m.group(2) : m.group(3) != null ? m.group(3) : m.group(4);
            if (attribute.equalsIgnoreCase(name) && value != null && expected.equalsIgnoreCase(value)) {
                return true;
            }
        }
        return false;
    }

    private static String extractCsrfFromLoginForm(String html) {
        Matcher m = INPUT_TAG.matcher(html);
        while (m.find()) {
            String tag = "<input" + m.group(1) + ">";
            if (attributeHasValue(tag, "name", "csrf")) {
                String value = getAttributeValue(tag, "value");
                if (value != null) return value;
            }
        }
        throw new RuntimeException("csrf input not found");
    }

    private static String extractJsonString(String json, String key) {
        if (json == null) return null;
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*\"([^\"]*)\"");
        Matcher m = p.matcher(json);
        return m.find() ? m.group(1) : null;
    }

    private static boolean isOkJson(String body) {
        return body != null && Pattern.compile("\"ok\"\\s*:\\s*true").matcher(body).find();
    }

    private static ChainBuilder workRequest() {
        return exec(
            http("work")
                .post("/v2/work")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Content-Type", "application/json")
                .body(StringBody("{}"))
                .check(status().saveAs("workStatus"))
                .check(status().in(200, 429, 401))
                .check(bodyString().saveAs("workBody"))
        );
    }

    private static ChainBuilder handleWorkSuccess() {
        return exec(session -> {
            String body = session.getString("workBody");
            if (!isOkJson(body)) {
                throw new RuntimeException("work 200 body missing ok=true: " + body);
            }
            String csrf = extractJsonString(body, "csrf");
            if (csrf != null) {
                session = session.set("csrf", csrf);
            }
            return session;
        });
    }

    private static ChainBuilder workWithRetry429() {
        return exec(session -> session.set("work429Retries", 0))
            .exec(workRequest())
            .doWhile(session -> statusOf(session, "workStatus") == 429 && retry429Count(session) < 4)
            .on(
                pause(Duration.ofSeconds(1))
                    .exec(session -> session.set("work429Retries", retry429Count(session) + 1))
                    .exec(workRequest())
            );
    }

    private static ChainBuilder login() {
        return exec(session -> session.remove("loginLocation").remove("loginBody").remove("loginFormHtml"))
            .exec(
                http("login-form")
                    .get("/v2/login-form")
                    .check(status().is(200))
                    .check(bodyString().saveAs("loginFormHtml"))
            )
            .exec(session -> {
                String html = session.getString("loginFormHtml");
                String csrf = extractCsrfFromLoginForm(html);
                return session.set("csrf", csrf);
            })
            .exec(
                http("login")
                    .post("/v2/login")
                    .header("X-CSRF-Token", "#{csrf}")
                    .header("Content-Type", "application/json")
                    .body(StringBody(session -> {
                        String username = session.getString("username");
                        String csrf = session.getString("csrf");
                        return "{\"username\":\"" + jsonEscape(username) + "\",\"password\":\"bench\",\"csrf\":\"" + jsonEscape(csrf) + "\"}";
                    }))
                    .check(status().in(200, 302))
                    .check(bodyString().saveAs("loginBody"))
                    .check(header("Location").optional().saveAs("loginLocation"))
            )
            .doIf(session -> session.contains("loginLocation")
                && session.getString("loginLocation") != null
                && !session.getString("loginLocation").isEmpty())
            .then(
                exec(
                    http("login-follow")
                        .get(session -> session.getString("loginLocation"))
                        .check(status().is(200))
                        .check(bodyString().saveAs("loginBody"))
                )
            )
            .exec(session -> {
                String body = session.getString("loginBody");
                String csrf = extractJsonString(body, "csrf");
                if (csrf == null) {
                    throw new RuntimeException("login did not return csrf");
                }
                return session.set("csrf", csrf);
            });
    }

    private static ChainBuilder freshLoginAndRetryWork() {
        return exec(login())
            .exec(workRequest())
            .doIf(session -> statusOf(session, "workStatus") == 200)
            .then(handleWorkSuccess());
    }

    private static ChainBuilder renewSessionAndRetryWork() {
        return exec(
            http("renew-session")
                .post("/v2/session/renew")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Content-Type", "application/json")
                .body(StringBody("{}"))
                .check(status().saveAs("renewStatus"))
                .check(status().in(200, 401))
                .check(bodyString().saveAs("renewBody"))
        )
            .doIf(session -> statusOf(session, "renewStatus") == 401)
            .then(freshLoginAndRetryWork())
            .doIf(session -> statusOf(session, "renewStatus") == 200)
            .then(
                exec(session -> {
                    String body = session.getString("renewBody");
                    String csrf = extractJsonString(body, "csrf");
                    if (csrf == null) {
                        throw new RuntimeException("renew did not return csrf");
                    }
                    return session.set("csrf", csrf);
                })
                .exec(workRequest())
                .doIf(session -> statusOf(session, "workStatus") == 200)
                .then(handleWorkSuccess())
            );
    }

    private static ChainBuilder handleWork401() {
        return exec(session -> {
            String body = session.getString("workBody");
            String error = extractJsonString(body, "error");
            return session.set("workError", error == null ? "" : error);
        })
            .doIf(session -> "denied".equals(session.getString("workError")))
            .then(
                exec(session -> {
                    throw new RuntimeException("work 401 denied");
                })
            )
            .doIf(session -> "expired".equals(session.getString("workError")))
            .then(renewSessionAndRetryWork())
            .doIf(session -> "session".equals(session.getString("workError")))
            .then(freshLoginAndRetryWork())
            .doIf(session -> !"expired".equals(session.getString("workError"))
                && !"session".equals(session.getString("workError"))
                && !"denied".equals(session.getString("workError")))
            .then(
                exec(session -> {
                    throw new RuntimeException("unknown 401 error: " + session.getString("workError"));
                })
            );
    }

    private static ChainBuilder workAttempt() {
        return exec(workWithRetry429())
            .doIf(session -> statusOf(session, "workStatus") == 200)
            .then(handleWorkSuccess())
            .doIf(session -> statusOf(session, "workStatus") == 401)
            .then(handleWork401());
    }

    String baseUrl = System.getenv("BASE_URL");
    {
        if (baseUrl == null || baseUrl.isEmpty()) {
            baseUrl = "http://127.0.0.1:8000";
        }
        while (baseUrl.endsWith("/")) {
            baseUrl = baseUrl.substring(0, baseUrl.length() - 1);
        }
    }

    HttpProtocolBuilder httpProtocol = http
        .baseUrl(baseUrl)
        .acceptHeader("application/json")
        .contentTypeHeader("application/json")
        .userAgentHeader("model-simulation")
        .maxRedirects(0);

    ScenarioBuilder workScenario = scenario("work")
        .exec(session -> {
            int idx = USER_COUNTER.getAndIncrement();
            if (idx >= WORKERS) {
                throw new RuntimeException("too many virtual users");
            }
            return session.set("workerIdx", idx)
                          .set("username", "bench-" + (idx + 1));
        })
        .exec(login())
        .exec(session -> {
            int idx = session.getInt("workerIdx");
            long now = System.currentTimeMillis();
            long phaseMs = (long) (idx * (PERIOD_MS / (double) WORKERS));
            long scheduled = T0_TARGET_MS + phaseMs;
            long waitMs;
            if (now < scheduled) {
                waitMs = scheduled - now;
            } else {
                long elapsed = now - scheduled;
                long periods = (elapsed + PERIOD_MS - 1) / PERIOD_MS;
                long next = scheduled + periods * PERIOD_MS;
                waitMs = next - now;
            }
            return session.set("startWaitMs", waitMs);
        })
        .pause(session -> Duration.ofMillis(session.getLong("startWaitMs")))
        .repeat(ITERATIONS)
        .on(
            exec(workAttempt())
                .pace(Duration.ofMillis(PERIOD_MS))
        );

    {
        setUp(
            workScenario.injectOpen(atOnceUsers(WORKERS))
        ).protocols(httpProtocol).maxDuration(Duration.ofSeconds(60));
    }

    @Override
    public void before() {
        T0_TARGET_MS = System.currentTimeMillis() + 5000;
    }
}
