  let m;
  while ((m = inputRe.exec(html)) !== null) {
    const tag = m[0];
    const name = attrValue(tag, 'name');
    if (name === 'csrf') {
      const val = attrValue(tag, 'value');
      if (val !== null) return val;
    }
