          headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
          redirects: 0,
        });

        if (retryRes2.status >= 200 && retryRes2.status < 300) {
          const fresh = freshCsrfFromResponse(retryRes2);
          if (fresh) csrfToken = fresh;
          return { ok: true, status: retryRes2.status };
