          headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
          redirects: 0,
        });

        if (retryRes3.status >= 200 && retryRes3.status < 300) {
          const fresh = freshCsrfFromResponse(retryRes3);
          if (fresh) csrfToken = fresh;
          return { ok: true, status: retryRes3.status };
