ACCOUNTS = [f"bench-{i}" for i in range(1, 17)] + ["bench"]


def extract_csrf(html):
    """Return the first non-empty csrf value from an input[name=csrf] tag."""
    fallback = ""
    for tag in re.findall(r"<input\b[^>]*>", html, re.I):
        if not re.search(r"\bname\s*=\s*(?:\"csrf\"|'csrf'|csrf)", tag, re.I):
            continue
        m = re.search(r"\bvalue\s*=\s*(?:\"([^\"]*)\"|'([^']*)'|([^\s>]+))", tag, re.I)
        if not m:
            continue
        value = m.group(1) or m.group(2) or m.group(3) or ""
        if value:
            return value
        fallback = fallback or value
    return fallback


class PacingCoordinator:
    def __init__(self, total_users, rate):
        self.total_users = total_users
        self.rate = rate
        self.interval = total_users / rate
        self.stride = self.interval / total_users
        self.lock = BoundedSemaphore()
        self.base = None
        self.slots = []
        self.next_slot = 0
        self.first_work_time = None

    def assign_slot(self):
        with self.lock:
            now = time.monotonic()
            if self.base is None:
                self.base = now
                self.slots = [
                    self.base + i * self.stride for i in range(self.total_users)
                ]
                self.next_slot = 0
            idx = self.next_slot
            self.next_slot += 1
            if self.next_slot >= self.total_users:
                self.next_slot = 0
            return idx

    def wait_for_slot(self, idx):
        with self.lock:
            now = time.monotonic()
            target = self.slots[idx]

            if target > now:
                wait = target - now
                self.slots[idx] = target + self.interval
                return wait

            # Slightly late: preserve phase and run now.
            if now < target + self.interval:
                self.slots[idx] = target + self.interval
                return 0.0

            # Missed one or more full cycles; advance to the next future slot.
            while target <= now:
                target += self.interval
            self.slots[idx] = target + self.interval
            return target - now

    def mark_first_work(self):
        with self.lock:
            if self.first_work_time is None:
                self.first_work_time = time.monotonic()


