                try:
                    data = resp.json()
                    self.csrf = data.get("csrf", self.csrf)
                except Exception:
                    pass
                resp.success()
                return True
            resp.failure(f"session renew failed status={resp.status_code}")
            return False

    def do_work(self):
        coordinator.mark_first_work()
        result = self.work_single()

        if result == "success":
            return

        if isinstance(result, tuple):
            kind = result[0]

            if kind == "retry":
                retry_after = result[1]
                for _ in range(4):
                    time.sleep(retry_after)
                    result = self.work_single()
                    if result == "success":
                        return
                    if isinstance(result, tuple) and result[0] == "retry":
                        retry_after = result[1]
                        continue
                    return
                return

            if kind == "401":
                error = result[1]
                if error == "expired":
                    if self.renew_session():
                        self.work_single()
                    elif self.fresh_login():
                        self.work_single()
                elif error == "session":
                    if self.fresh_login():
                        self.work_single()
                # denied 401s were already marked as failures in work_single()

    @task
    def work_loop(self):
        while True:
            if (
                coordinator.first_work_time is not None
                and time.monotonic() >= coordinator.first_work_time + STOP_AFTER
            ):
                break

            wait = coordinator.wait_for_slot(self.slot)
            if wait > 0:
                time.sleep(wait)
            self.do_work()

        raise StopUser()


class WorkShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()

        if coordinator.first_work_time is None:
            if run_time > 12:
                return None
            return (TOTAL_USERS, TOTAL_USERS)

        if time.monotonic() >= coordinator.first_work_time + STOP_AFTER:
            return None

        return (TOTAL_USERS, TOTAL_USERS)
