class PacingGate:
    """Global start-rate limiter: 8 starts/s, never bursting."""

    def __init__(self, rate):
        self.stride = 1.0 / rate
        self.lock = BoundedSemaphore()
        self.next_start = None
        self.first_work_time = None

    def wait_turn(self):
        with self.lock:
            now = time.monotonic()
            if self.next_start is None:
                self.next_start = now
            start = self.next_start
            if start < now:
                start = now
            self.next_start = start + self.stride
            wait = start - now
        if wait > 0:
            time.sleep(wait)
        return wait

    def mark_first_work(self):
        with self.lock:
            if self.first_work_time is None:
                self.first_work_time = time.monotonic()


pacer = PacingGate(TARGET_RATE)

account_counter = 0
account_lock = BoundedSemaphore()


def next_username():
    global account_counter
    with account_lock:
        idx = account_counter
        account_counter += 1
    return ACCOUNTS[idx % len(ACCOUNTS)]


class WorkUser(HttpUser):
    wait_time = constant(0)
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

    def on_start(self):
        self.username = next_username()
        self.csrf = ""
        if not self.fresh_login():
            raise StopUser()

    def fresh_login(self):
        resp = self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            allow_redirects=False,
        )
        if resp.status_code == 302:
            location = resp.headers.get("Location")
            if not location:
                return False
            resp = self.client.get(
                location,
                name="/v2/login-form-follow",
                allow_redirects=False,
            )
        if resp.status_code != 200:
            return False

        self.csrf = extract_csrf(resp.text)
        if not self.csrf:
            return False

        headers = {"X-CSRF-Token": self.csrf}
        resp = self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": self.csrf},
            headers=headers,
            name="/v2/login",
            allow_redirects=False,
        )
        if resp.status_code == 302:
            location = resp.headers.get("Location")
            if not location:
                return False
            resp = self.client.get(
                location,
                name="/v2/login-follow",
                allow_redirects=False,
            )

        if resp.status_code < 400:
            try:
                data = resp.json()
                if isinstance(data, dict) and "csrf" in data:
                    self.csrf = data["csrf"]
            except Exception:
                pass
            return True
        return False

    def work_single(self):
        headers = {"X-CSRF-Token": self.csrf}
        resp = self.client.post(
            "/v2/work",
            json={},
            headers=headers,
            name="/v2/work",
            catch_response=True,
        )

        if resp.status_code == 200:
            try:
                data = resp.json()
            except Exception:
                resp.failure("non-JSON /v2/work 200 response")
                return "fail"
            if not isinstance(data, dict):
                resp.failure("non-object /v2/work 200 response")
                return "fail"
            if data.get("ok"):
                self.csrf = data.get("csrf", self.csrf)
                resp.success()
                return "success"
            resp.failure("work response ok=false")
            return "fail"

        if resp.status_code == 429:
            resp.success()
            retry_after = resp.headers.get("Retry-After", "1")
            try:
                retry_after = float(retry_after)
            except Exception:
                retry_after = 1.0
            return ("retry", retry_after)

        if resp.status_code == 401:
            error = ""
            try:
                data = resp.json()
                if isinstance(data, dict):
                    error = data.get("error", "")
            except Exception:
                pass
            if error in ("expired", "session"):
                resp.success()
                return ("401", error)
            resp.failure(f"unexpected /v2/work 401 error={error}")
            return "fail"

        resp.failure(
            f"unexpected /v2/work status={resp.status_code} body={resp.text[:200]}"
        )
        return "fail"

    def renew_session(self):
        headers = {"X-CSRF-Token": self.csrf}
        resp = self.client.post(
            "/v2/session/renew",
            json={},
            headers=headers,
            name="/v2/session/renew",
            catch_response=True,
        )
        if resp.status_code < 400:
            try:
                data = resp.json()
                if isinstance(data, dict):
                    self.csrf = data.get("csrf", self.csrf)
            except Exception:
                pass
            resp.success()
            return True
        resp.failure(f"session renew failed status={resp.status_code}")
        return False

    def _stop_reached(self):
        return (
            pacer.first_work_time is not None
            and time.monotonic() >= pacer.first_work_time + STOP_AFTER
        )

    def do_work(self):
        pacer.mark_first_work()
        result = self.work_single()
        scheduled_retries = 0
        recovered_once = False

        while True:
            if result == "success" or result == "fail":
                return
            if not isinstance(result, tuple):
                return

            kind = result[0]

            if kind == "retry":
                if scheduled_retries >= 4:
                    return
                scheduled_retries += 1
                retry_after = result[1]
                if retry_after > 0:
                    time.sleep(retry_after)

                if self._stop_reached():
                    return
                pacer.wait_turn()
                if self._stop_reached():
                    return

                result = self.work_single()
                continue

            if kind == "401":
                error = result[1]
                if recovered_once:
                    return
                recovered_once = True

                if error == "expired":
                    if self.renew_session():
                        if self._stop_reached():
                            return
                        pacer.wait_turn()
                        if self._stop_reached():
                            return
                        result = self.work_single()
                        continue
                    elif self.fresh_login():
                        if self._stop_reached():
                            return
                        pacer.wait_turn()
                        if self._stop_reached():
                            return
                        result = self.work_single()
                        continue
                    else:
                        return

                elif error == "session":
                    if self.fresh_login():
                        if self._stop_reached():
                            return
                        pacer.wait_turn()
                        if self._stop_reached():
                            return
                        result = self.work_single()
                        continue
                    else:
                        return

                else:
                    # denied 401s are already marked as failures in work_single
                    return

    @task
    def work_loop(self):
        while True:
            if self._stop_reached():
                break

            pacer.wait_turn()

            if self._stop_reached():
                break

            self.do_work()

        raise StopUser()


class WorkShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()

        if pacer.first_work_time is None:
            if run_time > 12:
                return None
            return (TOTAL_USERS, TOTAL_USERS)

        if time.monotonic() >= pacer.first_work_time + STOP_AFTER:
            return None

        return (TOTAL_USERS, TOTAL_USERS)
